Matching Ayahs
- = အလစ်ဖ်၊ လာမ်၊ မီမ်။ 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = ထိုသူတို့သည် မိမိတို့၏အရှင်ထံတော်မှ ဖြောင့်မတ်သောလမ်းညွှန်ခြင်းကို ရရှိထားကြ၏။ ထိုသူတို့သည်ပင် အောင်မြင်သောသူများဖြစ်ကြ၏။ 2:5; 31:5
- = အိုအစ္စရေးသားအပေါင်းတို့၊ သင်တို့အပေါ်၌ ငါပေးခဲ့သော ငါ့၏ကျေးဇူးဂုဏ်ကို သတိရကြလော့။ ထို့ပြင် ငါသည် သင်တို့အား လောကသားအပေါင်းတို့ထက် မွမ်းမံချီးမြှင့်ခဲ့၏။ 2:47; 2:122
- = ထိုအမျိုးသားတို့သည် လွန်ခဲ့သောလူမျိုးဖြစ်၏။ သူတို့ပြုခဲ့သည့်အကျိုးသည် သူတို့အတွက်ဖြစ်၏။ သင်တို့ပြုခဲ့သည့်အကျိုးသည် သင်တို့အတွက်ဖြစ်၏။ ထို့ပြင် သူတို့ပြုခဲ့သည်များနှင့်ပတ်သက်၍ သင်တို့အား မေးမြန်းခြင်းမပြုရာ။ 2:134; 2:141
- = ထိုအပြစ်ဒဏ်တွင် သူတို့သည် အစဉ်ထာဝရ နေကြရမည်။ သူတို့ထံမှ အပြစ်ဒဏ်ကို ပေါ့သက်စေခြင်းငှါ မပြုလုပ်ရချေ။ ထို့ပြင် သူတို့အား အချိန်ဆိုင်းငံ့ခြင်းလည်း မပြုရချေ။ 2:162; 3:88
- = သို့ရာတွင် ထိုနောက် နောင်တရပြီး မိမိတို့ကိုယ်ကို ပြုပြင်ကြသောသူများမှအပ။ အလ္လာဟ်အရှင်မြတ်သည် အလွန်ခွင့်လွှတ်တော်မူသောအရှင်၊ အလွန်သနားကြင်နာတော်မူသောအရှင် ဖြစ်တော်မူ၏။ 3:89; 24:5
- = သို့သော် မယုံကြည်ကြဘဲ ငါတို့၏ သက်သေလက္ခဏာများကို ငြင်းပယ်ကြသောသူတို့မှာ ထိုသူတို့သည် ငရဲနေသူများဖြစ်ကြ၏။ 5:10; 5:86
- = သူတို့ထံသို့ သူတို့၏အရှင်မြတ်၏ သက်သေလက္ခဏာတစ်ခုခု ရောက်ရှိလာတိုင်း သူတို့သည် ထိုအရာမှ မျက်နှာလွှဲပစ်ကြသည်ချည်းသာ။ 6:4; 36:46
- = ထို့ပြင် သင့်မတိုင်မီကလည်း တမန်တော်များအား ပြက်ရယ်ပြုခြင်းခံခဲ့ရ၏။ သို့သော် ထိုသူတို့အား ပြက်ရယ်ပြုခဲ့သောအရာသည်ပင် ပြက်ရယ်ပြုခဲ့သော ထိုသူတို့အား ဝိုင်းရံဖမ်းဆီးခဲ့၏။ 6:10; 21:41
- = (အိုတမန်တော်) သင်ပြောလော့။ "အကယ်၍ ကျွန်ုပ်သည် ကျွန်ုပ်၏အရှင်ကို နာခံမှုလွန်ကျူးပါမူ ထိုကြီးကျယ်သောနေ့၏ အပြစ်ဒဏ်ကို ကျွန်ုပ် အမှန်ကြောက်ရွံ့ရ၏။" 6:15; 39:13
- = ထိုအခါ ငလျင်ကြီးသည် သူတို့အား ဖမ်းဆီးလိုက်၏။ ထို့နောက် သူတို့သည် မိမိတို့၏အိမ်များ၌ လှဲလျောင်းကျဆင်းသေဆုံးသူများ ဖြစ်သွားကြ၏။ 7:78; 7:91
- = ထို့နောက် သူသည် မိမိ၏တောင်ဝှေးကို ပစ်ချလိုက်၏။ ထိုအခါ ထိုတောင်ဝှေးသည် ထင်ရှားသော မြွေဟောက်တစ်ကောင် ဖြစ်သွားလေ၏။ 7:107; 26:32
- = ထို့ပြင် သူသည် မိမိလက်ကို ဆွဲထုတ်လိုက်၏။ ထိုအခါ ထိုလက်သည် ကြည့်ရှုသူများအတွက် ဖြူဖွေးတောက်ပလျက် ထွက်လာခဲ့၏။ 7:108; 26:33
- = သူတို့က "ကျွန်ုပ်တို့သည် လောကသားအပေါင်းတို့၏အရှင်ကို ယုံကြည်လေပြီ" ဟုဆိုကြ၏။ 7:121; 26:47
- = မုဆာနှင့် ဟာရွန်တို့၏အရှင်။ 7:122; 26:48
- = ကျွန်ုပ်သည် သူတို့အား အချိန်ဆိုင်းငံ့ပေး၏။ ဧကန်မလွဲ ကျွန်ုပ်၏ကြံစည်မှုသည် ခိုင်မာသေချာ၏။ 7:183; 68:45
- = ထိုအရှင်မြတ်သည် မိမိ၏တမန်တော်အား လမ်းညွှန်မှုနှင့် သစ္စာတရားသော သာသနာတော်ကို ပို့ချတော်မူခဲ့၏။ ထိုသာသနာတော်ကို အခြားသာသနာအားလုံးထက် ထွန်းတောက်စေရန် ဖြစ်၏။ အကယ်၍ အစရှိသူတို့မနှစ်သက်ကြစေကာမူ။ 9:33; 61:9
- = အို တမန်တော်။ သင်သည် မယုံကြည်သူများနှင့် လျှို့ဝှက်မယုံကြည်သူများကို တိုက်ခိုက်ပါ။ ထို့ပြင် သူတို့အပေါ်၌ ကြမ်းတမ်းစွာ ဆက်ဆံပါ။ သူတို့၏ ခိုလှုံရာသည် ငရဲဂျဟန္နမ်ဖြစ်၏။ ထိုနေရာသည် အလွန်ဆိုးဝါးသော နေရာဖြစ်ချေတကား။ 9:73; 66:9
- = ထို့ပြင် သူတို့က "သင်တို့သည် မှန်ကန်သူများဖြစ်လျှင် ဤကတိတော်သည် မည်သည့်အချိန်တွင် ဖြစ်လာမည်နည်း" ဟု ဆိုကြ၏။ 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = ထို့ပြင် ငါတို့သည် မုဆာအား ငါတို့၏ သက်သေလက္ခဏာများနှင့် ထင်ရှားသော အာဏာတော်ကို ပေးအပ်ကာ စေလွှတ်ခဲ့သည်။ 11:96; 40:23
- = ထို့ပြင် ငါတို့သည် မုဆာအား ကျမ်းတော်ကို ဧကန်အမှန် ပေးအပ်ခဲ့သည်။ သို့သော် ထိုကျမ်းတော်နှင့်ပတ်သက်၍ သဘောထားကွဲပြားမှုများ ဖြစ်ပေါ်ခဲ့သည်။ အကယ်၍ သင်၏အရှင်မြတ်ထံတော်မှ ကြိုတင်စကားတော်တစ်ရပ် မရှိခဲ့လျှင် သူတို့အကြားတွင် စီရင်ဆုံးဖြတ်ခြင်းခံရပေမည်။ ထို့ပြင် ဧကန်မလွဲ သူတို့သည် ထိုကျမ်းတော်နှင့်ပတ်သက်၍ ပြင်းထန်သော သံသယဝင်နေကြ၏။ 11:110; 41:45
- = ထိုအချက်သည် အလ္လာဟ်အရှင်မြတ်အတွက် မခက်ခဲပေ။ 14:20; 35:17
- = "ငါသည် သူ့ကို ပုံသွင်းပြီး ငါ၏ဝိညာဉ်တော်မှ သူ့အတွင်းသို့ သွင်းပေးသောအခါ သင်တို့သည် သူ့ရှေ့တော်၌ ဦးတို့ချ၍ ပျပ်ဝက်ကြလော့။" 15:29; 38:72
- = ထိုအခါ ကောင်းကင်တမန်အပေါင်းတို့သည် တစ်ပါတည်း ပျပ်ဝက်ကြ၏။ 15:30; 38:73
- = (အလ္လာဟ်အရှင်မြတ်က) "သို့ဖြစ်လျှင် သင်သည် ထိုဥယျာဉ်တော်မှ ထွက်သွားလော့။ အကြောင်းမူကား ဧကန်မလွဲ သင်သည် နှင်ထုတ်ခြင်းခံရသူ ဖြစ်၏။" 15:34; 38:77
- = (အိဗ်လီစ်က) "အို ကျွန်ုပ်၏အရှင်၊ သို့ဖြစ်လျှင် သူတို့ရှင်ပြန်ထမြောက်ကြမည့် နေ့တော်အထိ ကျွန်ုပ်အား အချိန်ဆိုင်းငံ့ပေးတော်မူပါ။" 15:36; 38:79
- = (အရှင်မြတ်က) "သို့ဖြစ်လျှင် ဧကန်မလွဲ သင်သည် အချိန်ဆိုင်းငံ့ခြင်းခံရသူများထဲမှ တစ်ဦး ဖြစ်၏။" 15:37; 38:80
- = သတ်မှတ်ထားသောအချိန်နေ့တော်အထိ။" 15:38; 38:81
- = သူတို့တွင် သင့်၏ရွေးချယ်ထားသော အစေခံကျွန်များမှအပ။ 15:40; 38:83
- = ဧကန်မလွဲ သမ္မာသတိရှိသောသူတို့သည် ဥယျာဉ်များနှင့် စမ်းရေတွင်းများတွင် ရှိကြလိမ့်မည်။ 15:45; 51:15
- = (သူက) "သို့ဖြစ်လျှင် အို ကောင်းကင်တမန်တို့၊ သင်တို့၏ လုပ်ငန်းကိစ္စသည် အဘယ်နည်း" ဟု မေးလေ၏။ 15:57; 51:31
- = သူတို့က "ကျွန်ုပ်တို့သည် အပြစ်သားလူမျိုးတစ်မျိုးထံသို့ စေလွှတ်ခြင်းခံရပါ၏။" 15:58; 51:32
- = ယုံကြည်ကြပြီး မိမိတို့၏ယုံကြည်ခြင်းကို မတရားသဖြင့် ရောနှောခြင်းမပြုကြသောသူများ၊ ထိုသူတို့အတွက် လုံခြုံအေးချမ်းမှုရှိ၏။ ထိုသူတို့သည်သာ ဖြောင့်မတ်သောလမ်းကို ရရှိသူများဖြစ်ကြ၏။ 16:42; 29:59
- = ငါတို့သည် သူတို့အား ပေးအပ်ခဲ့သည်များကို ငြင်းပယ်ရန် သူတို့ပြုကြ၏။ သို့ဖြစ်ပေရာ သင်တို့သည် ခဏသာခံစားကြလော့။ ထို့နောက် သင်တို့သိရှိလတ္တံ့။ 16:55; 30:34
- = ထို့နောက် သူသည် အခြားလမ်းတစ်ခုကို လိုက်ခဲ့၏။ 18:89; 18:92
- = ဖိရ်အောင်းထံသို့ သွားလော့။ အကြောင်းမူကား သူသည် ဧကန်မလွဲ နယ်နမိတ်ကို ကျူးလွန်ခဲ့ပြီ။ 20:24; 79:17
- = ထို့ပြင် မိမိတို့၏ ကိုယ်အင်္ဂါများကို စောင့်ရှောက်ကြသောသူများ။ 23:5; 70:29
- = မိမိတို့၏ ဇနီးများ သို့မဟုတ် မိမိတို့၏လက်ယာဘက်က ပိုင်ဆိုင်ထားသောသူများမှအပ။ ထိုသူတို့သည် အပြစ်တင်ခြင်းမခံရကြပေ။ 23:6; 70:30
- = သို့ရာတွင် ယင်းမှလွန်ကျူး၍ ရှာဖွေသူများမှာ ထိုသူတို့သည် နယ်နမိတ်ကျူးကျော်သူများ ဖြစ်ကြ၏။ 23:7; 70:31
- = ထို့ပြင် မိမိတို့အား အပ်နှင်းထားသည့် ယုံကြည်အပ်သောအရာများနှင့် ကတိပဋိညာဉ်များကို စောင့်ထိန်းကြသောသူများ။ 23:8; 70:32
- = (သူက) "အို ကျွန်ုပ်၏အရှင်၊ သူတို့သည် ကျွန်ုပ်အား ငြင်းပယ်ခဲ့ကြသောကြောင့် ကျွန်ုပ်အား ကူညီတော်မူပါ။" 23:26; 23:39
- = တာ၊ စင်၊ မီမ်။ 26:1; 28:1
- = ဤသည်တို့သည် ထင်ရှားသောကျမ်းတော်၏ သက်သေလက္ခဏာများဖြစ်ကြ၏။ 26:2; 28:2
- = ဧကန်မလွဲ ဤအရာ၌ သက်သေလက္ခဏာတစ်ခုရှိ၏။ သို့သော် သူတို့အများစုသည် ယုံကြည်သူများ မဖြစ်ကြ။ 26:8; 26:67; 26:103; 26:121; 26:174; 26:190
- = ထို့ပြင် ဧကန်မလွဲ သင်၏အရှင်မြတ်သည်ပင် တန်ခိုးတော်အရှင်၊ အလွန်သနားကြင်နာတော်မူသောအရှင် ဖြစ်တော်မူ၏။ 26:9; 26:68; 26:104; 26:122; 26:140; 26:159; 26:175; 26:191
- = ထို့နောက် ကျန်သူများကို ရေနစ်စေခဲ့၏။ 26:66; 37:82
- = ဧကန်မလွဲ ကျွန်ုပ်သည် သင်တို့အတွက် သစ္စာရှိသော တမန်တော် ဖြစ်၏။ 26:107; 26:125; 26:143; 26:162; 26:178
- = သို့ဖြစ်ပေရာ အလ္လာဟ်အရှင်မြတ်ကို ကြောက်ရွံ့ကြလော့။ ထို့ပြင် ကျွန်ုပ်အား နာခံကြလော့။ 26:108; 26:110; 26:126; 26:131; 26:144; 26:150; 26:163; 26:179
- = ထို့ပြင် ကျွန်ုပ်သည် ယင်းအတွက် သင်တို့ထံမှ အကျိုးဆုလာဘ်တစ်စုံတစ်ရာကို မတောင်းဆိုပါ။ ကျွန်ုပ်၏အကျိုးဆုလာဘ်သည် လောကသားအပေါင်းတို့၏အရှင်ထံတော်တွင်သာ ရှိ၏။ 26:109; 26:127; 26:145; 26:164; 26:180
- = ဥယျာဉ်များနှင့် စမ်းရေတွင်းများတွင်။ 26:147; 44:52
- = သူတို့က "သင်�ည် မှော်ပညာ၏အကျိုးသက်ရောက်မှုခံရသူများထဲမှ တစ်ဦးသာဖြစ်၏။" 26:153; 26:185
- = သို့သော် သူ၏ဇနီးမှအပ။ ငါတို့သည် သူမသည် နောက်ကျကျန်ရစ်သူများထဲမှ တစ်ဦးဖြစ်ရန် ကြိုတင်သတ်မှတ်ထားခဲ့၏။ 26:171; 37:135
- = ထို့နောက် ငါတို့သည် အခြားသူများကို ဖျက်ဆီးပစ်ခဲ့၏။ 26:172; 37:136
- = ထို့ပြင် ငါတို့သည် သူတို့အပေါ်၌ (ကျောက်ခဲ) မိုးရွာစေခဲ့၏။ သတိပေးခံရသူများအပေါ်သို့ ရွာခဲ့သော မိုးသည် အလွန်ဆိုးဝါးလေစွတကား။ 26:173; 27:58
- = သို့ဖြစ်လျှင် သူတို့သည် အပြစ်ဒဏ်ကို အမြန်ဆောင်ခဲ့ရန် တောင်းဆိုနေကြသလော။ 26:204; 37:176
- = ထိုသူတို့သည် ဆွလာသ်ဝတ်ပြုမှုကို ဆောက်တည်ကြ၏၊ ဇကာသ်အလှူကို ပေးကြ၏၊ ထို့ပြင် သူတို့သည် နောင်ဘဝကို ယုံကြည်စိတ်ချကြ၏။ 27:3; 31:4
- = ထို့ပြင် ထိုနေ့တွင် အရှင်မြတ်သည် သူတို့အား ခေါ်တော်မူပြီး "သင်တို့ ယူဆခဲ့ကြသော ငါ၏လုပ်ဖော်ဆောင်ဖက်များသည် အဘယ်မှာနည်း" ဟု မေးတော်မူမည့်အကြောင်း သတိရပါ။ 28:62; 28:74
- = ထို့ပြင် ကျွန်ုပ်တို့၏ရှေးဘိုးဘေးများကော။ 37:17; 56:48
- = ထို့ပြင် သူတို့သည် အချင်းချင်းအချင်းချင်း မေးမြန်းလျက် ရင်ဆိုင်ကြလိမ့်မည်။ 37:27; 52:25
- = သို့ရာတွင် အလ္လာဟ်အရှင်မြတ်၏ ရွေးချယ်ထားသော အစေခံကျွန်များမှအပ။ 37:40; 37:74; 37:128; 37:160
- = နိအ်မ် ဥယျာဉ်တော်များတွင်။ 37:43; 56:12
- = ထို့ပြင် ငါတို့သည် သူ၏ဂုဏ်ကျေးဇူးကို နောင်လာနောင်သားများအကြားတွင် ချန်ခဲ့၏။ 37:78; 37:108; 37:129
- = ဧကန်မလွဲ ငါတို့သည် ကောင်းမှုပြုသူများကို ဤသို့ပင် အကျိုးဆုချီးမြှင့်တော်မူ၏။ 37:80; 37:121; 37:131; 77:44
- = ဧကန်မလွဲ သူသည် ငါတို့၏ ယုံကြည်သောအစေခံကျွန်တစ်ဦး ဖြစ်ခဲ့၏။ 37:81; 37:111; 37:132
- = သင်တို့အား အဘယ်အရာဖြစ်သွားသနည်း။ သင်တို့သည် မည်သို့ ဆုံးဖြတ်ကြသနည်း။ 37:154; 68:36
- = ဤသည်မှာ လောကသားအပေါင်းတို့အတွက် သတိပေးနှိုးဆော်ချက်တစ်ခုမျှသာ ဖြစ်၏။ 38:87; 81:27
- = ကျမ်းတော်၏ ချပေးအပ်ခြင်းသည် တန်ခိုးတော်ရှင်၊ ဉာဏ်တော်ရှင်တော်မူသော အလ္လာဟ်အရှင်မြတ်ထံတော်မှ ဖြစ်၏။ 39:1; 45:2; 46:2
- = ဟာ၊ မီမ်။ 40:1; 41:1; 42:1; 43:1; 44:1; 45:1; 46:1
- = ထင်ရှားသော ကျမ်းတော်ကို ကျွန်ုပ် သစ္စာပြု၏။ 43:2; 44:2
- = သို့ဖြစ်ပေရာ သူတို့၏ကတိပြုခံရသောနေ့တော်နှင့် တွေ့ကြုံသည်အထိ သူတို့အား အချည်းနှီးပြောဆိုခြင်းနှင့် ပျော်ပါးကစားခြင်းတွင် နစ်မျောပါစေ။ 43:83; 70:42
- = (သူတို့အား) "သင်တို့ပြုခဲ့သည့်အရာများ၏ အကျိုးငှါ ကျေနပ်စွာ စားကြလော့၊ သောက်ကြလော့" ဟု ဆိုအံ့။ 52:19; 77:43
- = သို့တည်းမဟုတ် သင် (တမန်တော်) သည် သူတို့ထံမှ အကျိုးဆုကို တောင်းဆိုသည်ဖြစ်၍ သူတို့သည် ကြွေးမြီဒဏ်ကြောင့် ဝန်ပိလျက်ရှိကြသလော။ 52:40; 68:46
- = သို့တည်းမဟုတ် သူတို့တွင် မမြင်ရသောအရာ (ဂဲ့ဗ်) ၏ အသိပညာ ရှိကြသဖြင့် သူတို့သည် (ယင်းကို) ရေးမှတ်ကြသလော။ 52:41; 68:47
- = ထိုအခါ ငါ၏ပြစ်ဒဏ်နှင့် သတိပေးချက်တို့သည် မည်သို့မည်ပုံ ပြင်းထန်ခဲ့သနည်း။ 54:16; 54:21; 54:30
- = ထို့ပြင် ငါတို့သည် ကုရ်အာန်ကျမ်းတော်မြတ်ကို ဆင်ခြင်သတိရရန် လွယ်ကူစေခဲ့၏။ သို့ဖြစ်လျှင် သတိရဆင်ခြင်သူ တစ်ဦးဦးရှိသေးသလော။ 54:17; 54:22; 54:32; 54:40
- = သို့ဖြစ်လျှင် သင်တို့၏အရှင်မြတ်၏ ကျေးဇူးတော်များအနက် မည်သည့်အရာကို သင်တို့က ငြင်းပယ်ကြမည်နည်း။ 55:13; 55:16; 55:18; 55:21; 55:23; 55:25; 55:28; 55:30; 55:32; 55:34; 55:36; 55:38; 55:40; 55:42; 55:45; 55:47; 55:49; 55:51; 55:53; 55:55; 55:57; 55:59; 55:61; 55:63; 55:65; 55:67; 55:69; 55:71; 55:73; 55:75; 55:77
- = ရှေးလူများထဲမှ အများအပြားသော အုပ်စု။ 56:13; 56:39
- = ထို့ပြင် ကျွန်ုပ်တို့သည် (ထိုအသီးအနှံများမှ) ဆုံးရှုံးခဲ့ရသူများလော။ 56:67; 68:27
- = သို့ဖြစ်ပေရာ သင်၏အရှင်မြတ်၊ အလွန်ကြီးမြတ်တော်မူသောအရှင်၏ နာမတော်ကို ချီးမွမ်းဆောင်တင်ပါ။ 56:74; 56:96; 69:52
- = ဤသည် လောကသားအပေါင်းတို့၏အရှင်ထံတော်မှ ချပေးအပ်သော (ဝါဟီ) ဖြစ်၏။ 56:80; 69:43
- = ကောင်းကင်များနှင့် မြေကြီးပေါ်ရှိအရာအားလုံးတို့သည် အလ္လာဟ်အရှင်မြတ်အား ချီးမွမ်းဆက်ကပ်ကြ၏။ ထိုအရှင်မြတ်သည် တန်ခိုးတော်ရှင်၊ ဉာဏ်တော်ရှင်တော်မူသောအရှင် ဖြစ်တော်မူ၏။ 59:1; 61:1
- = ငါတို့၏ သက်သေလက္ခဏာများကို သူ့အား ရွတ်ဖတ်ပြသသောအခါ သူက "ရှေးလူဟောင်းများ၏ ဒဏ္ဍာရီပုံပြင်များ" ဟု ဆို၏။ 68:15; 83:13
- = သို့ဖြစ်၍ သူသည် ကျေနပ်ဖွယ်ရာဘဝတွင် ရှိလိမ့်မည်။ 69:21; 101:7
- = မြင့်မားသော ဥယျာဉ်တော်၌။ 69:22; 88:10
- = ထို့ပြင် ဆင်းရဲသားအား အစာကျွေးရန် အားပေးမှုမပြု။ 69:34; 107:3
- = ဧကန်မလွဲ ဤ (ကုရ်အာန်) သည် မြင့်မြတ်သော တမန်တော် (ဂျီဘရီလ်) ၏ စကားတော်ဖြစ်၏။ 69:40; 81:19
- = ဧကန်မလွဲ ဤသည် သတိပေးနှိုးဆော်ချက်တစ်ခု ဖြစ်၏။ သို့ဖြစ်၍ အလိုရှိသူသည် မိမိ၏အရှင်ထံသို့ လမ်းတစ်ခုကို ယူနိုင်ပေ၏။ 73:19; 76:29
- = သို့ဖြစ်၍ အလိုရှိသူသည် ၎င်းကို သတိရဆင်ခြင်ပါစေ။ 74:55; 80:12
- = ထိုနေ့တွင် ငြင်းပယ်သူများအတွက် ပျက်စီးခြင်းဖြစ်ပေတကား။ 77:15; 77:19; 77:24; 77:28; 77:34; 77:37; 77:40; 77:45; 77:47; 77:49; 83:10
- = ဧကန်မလွဲ ဖြောင့်မတ်ကောင်းမြတ်သောသူတို့သည် ချမ်းသာသုခ၌ ရှိကြလိမ့်မည်။ 82:13; 83:22
- = ၎င်းသည် မှတ်တမ်းတင်ထားသော ကျမ်းတစ်စောင် ဖြစ်၏။ 83:9; 83:20
- = မွေ့ယာများပေါ်တွင် နေရာယူ၍ ကြည့်ရှုကြလိမ့်မည်။ 83:23; 83:35
- = ထို့ပြင် ၎င်းသည် မိမိ၏အရှင်အမိန့်တော်ကို နာခံပြီး ၎င်းတွင် တာဝန်ကျေခဲ့၏။ 84:2; 84:5
- = ထို့ပြင် ကျွန်ုပ်သည် သင်တို့ကိုးကွယ်သောအရာကို ကိုးကွယ်သူ မဟုတ်ပေ။ 109:3; 109:5
noblequran.com Schemas
