- မျက်မမြင်တို့အား သူတို့၏လမ်းလွဲမှုမှ (သင်မလမ်းညွှန်နိုင်ပေ)။ သင်သည် ငါတို့၏သက်သေလက္ခဏာများကို ယုံကြည်သောသူများကိုသာ ကြားနာစေနိုင်၏။ ထိုသူတို့သည်သာ မွတ်စ်လင်မ်များဖြစ်ကြ၏။ (الْعُمْيِ عَن ضَلَالَتِهِمْ إِن تُسْمِعُ إِلَّا مَن يُؤْمِنُ بِآيَاتِنَا فَهُم مُّسْلِمُونَ) 27:81; 30:53
- ဤလောကီဘဝ၏ ဥပမာသည် မိုးကောင်းကင်မှ ငါအရှင်မြတ်သွန်းချသော ရေကဲ့သို့ဖြစ်၏။ ထိုရေဖြင့် မြေကြီး၏အပင်များ ရောနှောပေါက်ရောက်ကြ၏။ (مَثَلُ الْحَيَاةِ الدُّنْيَا كَمَاءٍ أَنزَلْنَاهُ مِنَ السَّمَاءِ فَاخْتَلَطَ بِهِ نَبَاتُ الْأَرْضِ) 10:24; 18:45
- ၎င်းသင်္ဘောတွင် သတ္တဝါအမျိုးအစားတိုင်းမှ တစ်မျိုးလျှင်နှစ်ကောင်စီ၊ နှင့် သင်၏မိသားစုဝင်များကို (တင်ဆောင်လော့)။ သို့သော် ကြိုတင်၍ အမိန့်တော်ကျရောက်ပြီးသော သူများမှတစ်ပါး။ (فِيهَا مِن كُلٍّ زَوْجَيْنِ اثْنَيْنِ وَأَهْلَكَ إِلَّا مَن سَبَقَ عَلَيْهِ الْقَوْلُ) 11:40; 23:27
- ငါသည် သင်တို့အား "ငါ့ထံတွင် အလ္လာဟ်အရှင်မြတ်၏ ဘဏ္ဍာတိုက်များရှိသည်" ဟု မပြောဆိုချေ။ ထို့ပြင် ငါသည် မမြင်ရသောအရာကိုလည်း မသိချေ။ ငါလည်း မဆိုချေ... (لَّا أَقُولُ لَكُمْ عِندِي خَزَائِنُ اللَّهِ وَلَا أَعْلَمُ الْغَيْبَ وَلَا أَقُولُ) 6:50; 11:31
- ဧကန်စင်စစ် အလ္လာဟ်အရှင်မြတ်သည် လူသားတို့အပေါ် ကျေးဇူးတော်ရှင်ဖြစ်တော်မူ၏။ သို့ရာတွင် လူသားအများစုသည် ကျေးဇူးမသိတတ်ကြပေ။ (إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَشْكُرُونَ) 2:243; 40:61
- သူတို့ထံသို့ သူတို့၏အရှင်မြတ်၏ သက်သေလက္ခဏာတော်များမှ မည်သည့်သက်သေလက္ခဏာမျှ မရောက်လာခဲ့ပေ။ သို့သော် သူတို့သည် ထိုသက်သေလက္ခဏာများမှ မျက်နှာလွှဲခဲ့ကြ၏။ (وَمَا تَأْتِيهِم مِّنْ آيَةٍ مِّنْ آيَاتِ رَبِّهِمْ إِلَّا كَانُوا عَنْهَا مُعْرِضِينَ) 6:4; 36:46
- မည်သူတစ်ဦးတစ်ယောက်မျှ အခြားသူအတွက် မည်သည့်အကျိုးမျှ မပြုနိုင်သောနေ့ကို ကြောက်ရွံ့ကြလော့။ ထိုနေ့တွင် မည်သူ့ထံမှမျှ ရွေးဖိုးကို လက်ခံတော်မမူပေ။ (وَاتَّقُوا يَوْمًا لَّا تَجْزِي نَفْسٌ عَن نَّفْسٍ شَيْئًا وَلَا يُقْبَلُ مِنْهَا) 2:48; 2:123
- ဧကန်စင်စစ် အသင်သည် သေလွန်သူများကို ကြားနာစေနိုင်တော်မမူပေ။ ထို့ပြင် နားပင်းသူတို့သည်လည်း ကျောခိုင်း၍ ထွက်သွားကြသောအခါ ခေါ်သံကို ကြားနာစေနိုင်တော်မမူပေ။ (إِنَّكَ لَا تُسْمِعُ الْمَوْتَى وَلَا تُسْمِعُ الصُّمَّ الدُّعَاءَ إِذَا وَلَّوْا مُدْبِرِينَ) 27:80; 30:52
- သင်တို့အပေါ်၌ သေကောင်ကိုလည်းကောင်း၊ သွေးကိုလည်းကောင်း၊ ဝက်သားကိုလည်းကောင်း၊ အလ္လာဟ်အရှင်မြတ်မှတစ်ပါး အခြားသူ၏အမည်ဖြင့် သတ်သောအရာကိုလည်းကောင်း ဟရာမ်ဖြစ်စေတော်မူ၏။ (حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ وَالدَّمُ وَلَحْمُ الْخِنزِيرِ وَمَا أُهِلَّ لِغَيْرِ اللَّهِ بِهِ) 5:3; 16:115
- မိုးကောင်းကင်များနှင့် မြေကြီးပေါ်ရှိ အရာအားလုံးသည် အလ္လာဟ်အရှင်မြတ်အား ချီးမွမ်းဘုန်းတော်ကြီးစေကြ၏။ အရှင်မြတ်သည် တန်ခိုးတော်ရှင်၊ ဉာဏ်တော်ရှင်ဖြစ်တော်မူ၏။ (سَبَّحَ لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَهُوَ الْعَزِيزُ الْحَكِيمُ) 59:1; 61:1
- သို့ရာတွင် ထိုအပြစ်များပြုပြီးနောက် နောင်တရကာ ပြုပြင်ဖြောင့်မတ်လာသူများမှတစ်ပါး။ ဧကန်စင်စစ် အလ္လာဟ်အရှင်မြတ်သည် အလွန်ခွင့်လွှတ်တော်မူသောအရှင်၊ အလွန်သနားကြင်နာတော်မူသောအရှင် ဖြစ်တော်မူ၏။ (إِلَّا الَّذِينَ تَابُوا مِن بَعْدِ ذَلِكَ وَأَصْلَحُوا فَإِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ) 3:89; 24:5
- တမန်တော်များသည် သူတို့၏အရှင်မြတ်ထံမှ (ဖြစ်၏)။ ကျွန်ုပ်တို့သည် သူတို့တစ်ဦးနှင့်တစ်ဦးကြားတွင် ခွဲခြားခြင်းမပြုပေ။ ကျွန်ုပ်တို့သည် အရှင်မြတ်အား နာခံသောမွတ်စ်လင်မ်များဖြစ်ကြ၏။ (النَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّنْهُمْ وَنَحْنُ لَهُ مُسْلِمُونَ) 2:136; 3:84
- သင်၏အရှင်မြတ်ထံမှ သင်မတိုင်မီ သတိပေးနှိုးဆော်သူတစ်ဦးမျှ မရောက်လာသေးသောလူမျိုးအား သင်သတိပေးနှိုးဆော်ရန်၊ သူတို့သည် သတိရလိမ့်မည်ဟု... (مِّن رَّبِّكَ لِتُنذِرَ قَوْمًا مَّا أَتَاهُم مِّن نَّذِيرٍ مِّن قَبْلِكَ لَعَلَّهُمْ) 28:46; 32:3
- အို တမန်တော်မြတ်၊ သင်သည် ငြင်းပယ်သောသူတို့ကိုလည်းကောင်း၊ လျှို့ဝှက်သစ္စာဖောက်သူတို့ကိုလည်းကောင်း တိုက်ခိုက်တော်မူပါ။ သူတို့အပေါ်၌လည်း ကြမ်းတမ်းခက်ထန်စွာ ပြုမူတော်မူပါ။ သူတို့၏နေရာသည် ငရဲခံရာဖြစ်၏။ အလွန်ဆိုးဝါးသော ပြန်လည်ရောက်ရှိရာဖြစ်၏။ (يَا أَيُّهَا النَّبِيُّ جَاهِدِ الْكُفَّارَ وَالْمُنَافِقِينَ وَاغْلُظْ عَلَيْهِمْ وَمَأْوَاهُمْ جَهَنَّمُ وَبِئْسَ الْمَصِيرُ) 9:73; 66:9
- ဧကန်စင်စစ် သင်၏အရှင်မြတ်သည် ရှင်ပြန်ထမြောက်ရာနေ့တွင် သူတို့သဘောထားကွဲလွဲခဲ့ကြသောအရာများကို သူတို့ကြားတွင် စီရင်ဆုံးဖြတ်တော်မူမည်။ (إِنَّ رَبَّكَ يَقْضِي بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 10:93; 45:17
- သူက "အို ကျွန်ုပ်၏အရှင်မြတ်၊ ကျွန်ုပ်အတွက် နိမိတ်လက္ခဏာတစ်ခု ပြုတော်မူပါ။" အရှင်မြတ်က "သင်၏နိမိတ်လက္ခဏာမှာ သင်သည် လူသားတို့အား စကားပြောဆိုခြင်း မပြုရခြင်းဖြစ်၏..." (قَالَ رَبِّ اجْعَل لِّي آيَةً قَالَ آيَتُكَ أَلَّا تُكَلِّمَ النَّاسَ) 3:41; 19:10
- သို့ဖြစ်ပေရာ သင်သည် မိမိ၏မျက်နှာတော်ကို အာလ်မစ်ဂျိဒ်အလ်ဟရာမ် (ဗလီမြတ်တော်) ဘက်သို့ လှည့်တော်မူပါ။ သင်တို့သည်လည်း မည်သည့်နေရာ၌ရှိသည်ဖြစ်စေ သင်တို့၏မျက်နှာများကို ထိုဘက်သို့ လှည့်ကြလော့။ (فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ) 2:144; 2:150
- အို ဣသရေလအမျိုးသားတို့၊ သင်တို့အား ငါအရှင်မြတ် ပေးအပ်တော်မူခဲ့သော ငါ၏ကျေးဇူးတော်ကို အောက်မေ့ကြလော့။ ထို့ပြင် ငါသည် သင်တို့အား လောကခပ်သိမ်းတို့ထက် ချီးမြှောက်တော်မူခဲ့ကြောင်းကိုလည်း (အောက်မေ့ကြလော့)။ (يَا بَنِي إِسْرَائِيلَ اذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعَالَمِينَ) 2:47; 2:122
- နွားမ ခုနစ်ကောင်တို့ကို ပိန်လှီသောနွားမ ခုနစ်ကောင်က စားသုံးကြ၏။ စပါးနှံ ခုနစ်ခုမှာ စိမ်းလန်းသောအနှံများနှင့် အခြားသော ခြောက်သွေ့သောအနှံများဖြစ်၏။ (سَبْعَ بَقَرَاتٍ سِمَانٍ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ وَسَبْعَ سُنبُلَاتٍ خُضْرٍ وَأُخَرَ يَابِسَاتٍ) 12:43; 12:46
- လူမျိုးတိုင်းအတွက် သတ်မှတ်ထားသောအချိန်ကာလရှိ၏။ ထိုအချိန်ကာလရောက်ရှိလာသောအခါ သူတို့သည် တစ်နာရီမျှ နောက်မကျနိုင်ပေ။ ရှေ့လည်းမရောက်နိုင်ပေ။ (وَلِكُلِّ أُمَّةٍ أَجَلٌ فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49
- အလ္လာဟ်အရှင်မြတ်မှတစ်ပါး အခြားသူ၏အမည်ဖြင့် သတ်သောအရာ (ဟရာမ်ဖြစ်၏)။ သို့ရာတွင် မည်သူတစ်ဦးဦးသည် အနိုင်ကျင့်သူမဟုတ်ဘဲ၊ ကျူးလွန်သူမဟုတ်ဘဲ အတင်းအကြပ် (စားသုံးရန်) လိုအပ်လာလျှင်... (أُهِلَّ لِغَيْرِ اللَّهِ بِهِ فَمَنِ اضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَإِنَّ) 6:145; 16:115
- သူတို့အား "အလ္လာဟ်အရှင်မြတ် ချပေးအပ်တော်မူသောအရာကို လိုက်နာကြလော့" ဟု ဆိုအပ်သောအခါ သူတို့က "မဟုတ်ပါ၊ ကျွန်ုပ်တို့သည် ကျွန်ုပ်တို့၏ဘိုးဘေးများ တွေ့ရှိခဲ့သောအရာကိုသာ လိုက်နာကြမည်" ဟု ဆိုကြ၏။ (وَإِذَا قِيلَ لَهُمُ اتَّبِعُوا مَا أَنزَلَ اللَّهُ قَالُوا بَلْ نَتَّبِعُ مَا) 2:170; 31:21
