- သူတို့၏ဇနီးမယားများ သို့မဟုတ် သူတို့၏လက်ယာလက်များက ပိုင်ဆိုင်သောသူများမှအပ၊ သို့ဖြစ်လျှင် သူတို့သည် အပြစ်တင်ခြင်းခံထိုက်သောသူများ မဟုတ်ကြချေ။ (إِلَّا عَلَى أَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ) 23:6; 70:30
- အလ္လာဟ်အရှင်မြတ်သည် ညဉ့်ကို နေ့ထဲသို့ သွင်းတော်မူပြီး နေ့ကို ညဉ့်ထဲသို့ သွင်းတော်မူသောကြောင့်တည်း။ (بِأَنَّ اللَّهَ يُولِجُ اللَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي اللَّيْلِ) 22:61; 31:29
- မီးတောက်တစ်ခု၊ ထို့နောက် သူသည် မိမိအိမ်သူအိမ်သားများအား ပြောဆိုခဲ့၏။ "သင်တို့ စောင့်နေကြလော့၊ ကျွန်ုပ်သည် မီးတောက်တစ်ခုကို မြင်လိုက်ရ၏၊ ထိုမီးတောက်မှ သင်တို့ထံသို့ တစ်စုံတစ်ရာ ယူဆောင်လာနိုင်ပါမည်။" (نَارًا فَقَالَ لِأَهْلِهِ امْكُثُوا إِنِّي آنَسْتُ نَارًا لَّعَلِّي آتِيكُم مِّنْهَا) 20:10; 28:29
- သူက ပြောဆိုခဲ့၏။ "ကျွန်ုပ်သည် သူ့ထက် သာ၍ကောင်း၏၊ အရှင်မြတ်သည် ကျွန်ုပ်အား မီးမှ ဖန်ဆင်းတော်မူခဲ့ပြီး၊ ထိုသူအား ရွှံ့စေးမှ ဖန်ဆင်းတော်မူခဲ့၏။" (قَالَ أَنَا خَيْرٌ مِّنْهُ خَلَقْتَنِي مِن نَّارٍ وَخَلَقْتَهُ مِن طِينٍ) 7:12; 38:76
- သူတို့အား "အလ္လာဟ်အရှင်မြတ် ချမှတ်တော်မူခဲ့သော အမိန့်တော်သို့လည်းကောင်း၊ ရစူလ်တမန်တော်သို့လည်းကောင်း ကြလာကြ" ဟု ဆိုအပ်သောအခါ။ (وَإِذَا قِيلَ لَهُمْ تَعَالَوْا إِلَى مَا أَنزَلَ اللَّهُ وَإِلَى الرَّسُولِ) 4:61; 5:104
- သူတို့အတွက် ဝမ်းမနည်းလေနှင့်၊ သူတို့ကြံစည်သော ပရိယာယ်များအတွက် စိတ်မကျဉ်းမြောင်းလေနှင့်။ (وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِي ضَيْقٍ مِّمَّا يَمْكُرُونَ) 16:127; 27:70
- အကယ်၍ အလ္လာဟ်အရှင်မြတ်သည် သင့်အား ဆိုးကျိုးတစ်ခုခုဖြင့် ထိမိစေတော်မူပါက၊ အရှင်မြတ်မှတစ်ပါး ၎င်းကို ဖယ်ရှားပေးနိုင်သောအရှင် မရှိ၊ အကယ်၍။ (وَإِن يَمْسَسْكَ اللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُ إِلَّا هُوَ وَإِن) 6:17; 10:107
- သူတို့ရှေ့မှ လူမျိုးအဆက်ဆက်တို့သည် သူတို့၏ နေအိမ်များ၌ သွားလာကြ၏။ ထိုအရာများ၌ သက်သေလက္ခဏာများ ရှိ၏။ (قَبْلَهُم مِّنَ الْقُرُونِ يَمْشُونَ فِي مَسَاكِنِهِمْ إِنَّ فِي ذَلِكَ لَآيَاتٍ) 20:128; 32:26
- ထို့ပြင် ကျွန်ုပ်တို့သည် သူတို့၏စိတ်နှလုံးများပေါ်၌ ကွယ်ကာများကို ဖုံးအုပ်ထား၍ သူတို့သည် ၎င်းကို နားမလည်နိုင်ကြချေ၊ သူတို့၏နားများ၌လည်း ထိုင်းမှိုင်းခြင်းရှိ၏။ (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا وَإِن) 6:25; 18:57
- သူတို့၏ရစူလ်တမန်တော်များသည် ထင်ရှားသော အထောက်အထားများဖြင့် ရောက်လာကြ၏။ သို့ရာတွင် အလ္လာဟ်အရှင်မြတ်သည် သူတို့အား မတရားပြုကျင့်တော်မူမည် မဟုတ်၊ သို့သော် သူတို့သည် မိမိတို့ကိုယ်ကို မတရားပြုကျင့်နေကြ၏။ (رُسُلُهُم بِالْبَيِّنَاتِ فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 30:9
- ထို့ပြင် မြေကြီးပေါ်၌လည်း၊ အလ္လာဟ်အရှင်မြတ်မှတစ်ပါး သင်တို့အတွက် ကာကွယ်သူလည်းမရှိ၊ အကူအညီပေးသူလည်းမရှိ။ (وَالْأَرْضِ وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ) 2:107; 42:31
- ထို့နောက် သင်တို့အား မမြင်ရသောအရာနှင့် မြင်ရသောအရာတို့ကို သိရှိတော်မူသောအရှင်ထံသို့ ပြန်လည်ပို့ဆောင်ခြင်းခံကြရမည်။ ထိုအရှင်မြတ်သည် သင်တို့ပြုလုပ်ခဲ့သမျှတို့ကို သတင်းပေးတော်မူမည်။ (ثُمَّ تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 62:8
- ညအချိန်၌ သင်တို့အနားယူရန်နှင့် နေ့အချိန်၌ သင်တို့အလင်းရောင်ရရန် (အရှင်မြတ်သည် ဖန်ဆင်းတော်မူခဲ့၏)။ ထိုအရာများ၌ စဉ်းစားတွေးခေါ်သော လူမျိုးအတွက် သက်သေလက္ခဏာများရှိ၏။ (اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ فِي ذَلِكَ لَآيَاتٍ لِّقَوْمٍ) 10:67; 27:86
- သင်၏အရှင်မြတ်ထံတော်မှ သင့်ထံသို့ ချပေးတော်မူသောအရာသည် သူတို့အများစုအတွက် ပုန်ကန်မှုနှင့် မယုံကြည်မှုတို့ကိုသာ တိုးပွားစေမည်။ (وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّا أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَانًا وَكُفْرًا) 5:64; 5:68
- သူကပြောဆိုခဲ့၏။ "အို ကျွန်ုပ်၏လူမျိုးတို့၊ သင်တို့အမြင်၌ အဘယ်သို့နည်း။ အကယ်၍ ကျွန်ုပ်သည် ကျွန်ုပ်၏အရှင်မြတ်ထံတော်မှ ထင်ရှားသော အထောက်အထားပေါ်၌ ရှိပြီး အရှင်မြတ်က ကျွန်ုပ်အား ပေးအပ်တော်မူပါက။" (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي وَآتَانِي) 11:28; 11:63
- ထို့ပြင် သူတို့ကပြောဆိုကြ၏။ "အဘယ်ကြောင့် သူ့အတွက် သူ့အရှင်မြတ်ထံမှ နိမိတ်လက္ခဏာတစ်ခုကို ချပေးတော်မမူခဲ့သနည်း။" သင်ပြောလိုက်ပါ။ "အမှန်မှာ။" (وَيَقُولُونَ لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا) 10:20; 29:50
- အလ္လာဟ်အရှင်မြတ်ထံတော်မှ ပြန်လည်ရုပ်သိမ်းခြင်းမရှိသော နေ့တစ်နေ့ မရောက်မီ။ (مِن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا مَرَدَّ لَهُ مِنَ اللَّهِ) 30:43; 42:47
- ထိုအရာသည် အလ္လာဟ်အရှင်မြတ်၏ အလုံးအရင်းတော်ဖြစ်၏။ အရှင်မြတ်သည် အလိုတော်ရှိသူအား ပေးသနားတော်မူ၏။ အလ္လာဟ်အရှင်မြတ်သည် ကြီးကျယ်သော အလုံးအရင်းတော်၏အရှင် ဖြစ်တော်မူ၏။ (ذَلِكَ فَضْلُ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 62:4
- ထို့ပြင် သင်တို့အတွက် ကျွဲနွားသိုးဆိတ်များ၌ သင်ခန်းစာရှိ၏။ ကျွန်ုပ်တို့သည် သင်တို့အား ၎င်းတို့၏ဗိုက်အတွင်းမှ (နို့ရည်ကို) တိုက်ကျွေးပါ၏။ (وَإِنَّ لَكُمْ فِي الْأَنْعَامِ لَعِبْرَةً نُّسْقِيكُم مِّمَّا فِي بُطُونِهِ) 16:66; 23:21
- ၎င်းအကြောင်းသည် သူတို့၏အရှင်မြတ်ထံမှ အမှန်တရားဖြစ်ကြောင်းကိုလည်းကောင်း၊ အလ္လာဟ်အရှင်မြတ်သည် သူတို့ပြုလုပ်သမျှတို့ကို သတိမူတော်မမူသောအရှင် မဟုတ်ကြောင်းကိုလည်းကောင်း။ (أَنَّهُ الْحَقُّ مِن رَّبِّهِمْ وَمَا اللَّهُ بِغَافِلٍ عَمَّا يَعْمَلُونَ) 2:144; 2:149
- သူတို့၏ ရှေ့တွင်လည်းကောင်း၊ နောက်တွင်လည်းကောင်း (သတိပေးခြင်းခံရ၏)။ အလ္လာဟ်အရှင်မြတ်မှတစ်ပါး အခြားကို မကိုးကွယ်ကြရန်။ (مِن بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ أَلَّا تَعْبُدُوا إِلَّا اللَّهَ) 41:14; 46:21
- အမှန်စင်စစ် သင်တို့သည် မိန်းမများကိုချန်ထားခဲ့ပြီး ယောက်ျားများထံသို့ အာသာဆန္ဒဖြင့် ချဉ်းကပ်ကြ၏။ မဟုတ်၊ သင်တို့သည် နယ်နိမိတ်ကိုကျော်လွန်သော လူမျိုးဖြစ်ကြ၏။ (إِنَّكُمْ لَتَأْتُونَ الرِّجَالَ شَهْوَةً مِّن دُونِ النِّسَاءِ بَلْ أَنتُمْ قَوْمٌ) 7:81; 27:55
- မိုးကောင်းကင်များနှင့် မြေကြီး တည်ရှိနေသရွေ့ ထိုအရပ်၌ သူတို့သည် အစဉ်ထာဝရ နေထိုင်ကြရမည်။ သို့ရာတွင် သင်၏အရှင်မြတ် အလိုတော်ရှိသောအချိန်မှအပ။ (خَالِدِينَ فِيهَا مَا دَامَتِ السَّمَاوَاتُ وَالْأَرْضُ إِلَّا مَا شَاءَ رَبُّكَ) 11:107; 11:108
- မိုးကောင်းကင်များနှင့် မြေကြီးပေါ်၌ရှိသော သတ္တဝါတို့၊ သို့ရာတွင် အလ္လာဟ်အရှင်မြတ် အလိုတော်ရှိသောသူမှအပ။ (مَن فِي السَّمَاوَاتِ وَمَن فِي الْأَرْضِ إِلَّا مَن شَاءَ اللَّهُ) 27:87; 39:68
- ထိုဥယျာဉ်တော်များ၌ သူတို့အား ရွှေလက်ကောက်များနှင့် ပုလဲများဖြင့် တန်ဆာဆင်ခြင်းခံကြရမည်။ ထိုအရပ်၌ သူတို့၏အဝတ်အစားများသည် ပိုးသားဖြစ်၏။ (يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَلُؤْلُؤًا وَلِبَاسُهُمْ فِيهَا حَرِيرٌ) 22:23; 35:33
