- သင်တို့အား မမြင်ရသောအရာနှင့် မြင်ရသောအရာတို့ကို သိရှိတော်မူသောအရှင်ထံသို့ ပြန်လည်ပို့ဆောင်ခြင်းခံကြရမည်။ ထိုအရှင်မြတ်သည် သင်တို့ပြုလုပ်ခဲ့သမျှတို့ကို သတင်းပေးတော်မူမည်။ (تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 9:105; 62:8
- သင်တို့၏သားများကို သတ်ဖြတ်ပြီး သင်တို့၏မိန်းမများကို အသက်ချမ်းသာပေး၏။ ထိုအရာ၌ သင်တို့၏အရှင်မြတ်ထံမှ ကြီးလေးသော စမ်းသပ်ခြင်း ရှိ၏။ (أَبْنَاءَكُمْ وَيَسْتَحْيُونَ نِسَاءَكُمْ وَفِي ذَلِكُم بَلَاءٌ مِّن رَّبِّكُمْ عَظِيمٌ) 2:49; 7:141; 14:6
- အမှန်စင်စစ် သင်၏အရှင်မြတ်သည် မိမိ၏လမ်းတော်မှ လမ်းလွဲသူကို အကောင်းဆုံး သိရှိတော်မူသောအရှင်၊ ထိုအရှင်သည်ပင်။ (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 16:125; 53:30; 68:7
- အလ္လာဟ်အရှင်မြတ်သည် မိုးကောင်းကင်များနှင့် မြေကြီးပေါ်၌ရှိသမျှတို့ကို ပိုင်ဆိုင်တော်မူသောအရှင် ဖြစ်တော်မူ၏။ (اللَّهِ الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 14:2; 34:1; 42:53
- သင်တို့ရှေ့မှ လွန်ခဲ့သော လူမျိုးအဆက်ဆက်တို့တွင်၊ ဂျင်န်များနှင့် လူသားများထဲမှ။ (فِي أُمَمٍ قَدْ خَلَتْ مِن قَبْلِكُم مِّنَ الْجِنِّ وَالْإِنسِ) 7:38; 41:25; 46:18
- အလ္လာဟ်အရှင်မြတ်ကို ကိုးကွယ်ကြလော့။ အရှင်မြတ်မှတစ်ပါး သင်တို့အတွက် ကိုးကွယ်ရာဟူ၍ မရှိ၊ သင်တို့ မကြောက်ရွံ့ကြသလော။ (اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 7:65; 23:23; 23:32
- ကျွန်ုပ်တို့သည် သူတို့၏စိတ်နှလုံးများပေါ်၌ ကွယ်ကာများကို ဖုံးအုပ်ထား၍ သူတို့သည် ၎င်းကို နားမလည်နိုင်ကြချေ၊ သူတို့၏နားများ၌လည်း ထိုင်းမှိုင်းခြင်းရှိ၏။ (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 6:25; 17:46; 18:57
- ထိုအရှင်မြတ်သည် သူတို့အကြား ကိယာမနေ့တော်၌ သူတို့သဘောထား ကွဲပြားခဲ့သောအရာများတွင် စီရင်ဆုံးဖြတ်တော်မူမည်။ (يَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 2:113; 16:124; 22:69
- သူကပြောဆိုခဲ့၏။ "အို ကျွန်ုပ်၏လူမျိုးတို့၊ သင်တို့အမြင်၌ အဘယ်သို့နည်း။ အကယ်၍ ကျွန်ုပ်သည် ကျွန်ုပ်၏အရှင်မြတ်ထံတော်မှ ထင်ရှားသော အထောက်အထားပေါ်၌ ရှိပါက။" (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي) 11:28; 11:63; 11:88
- ထိုသို့ သင်တို့၏လက်များက ရှေ့သို့ ပို့ဆောင်ခဲ့သောအရာများကြောင့်ဖြစ်၏။ အလ္လာဟ်အရှင်မြတ်သည် ကျွန်များအား မတရားပြုကျင့်တော်မူသောအရှင် မဟုတ်ပေ။ (ذَلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ اللَّهَ لَيْسَ بِظَلَّامٍ لِّلْعَبِيدِ) 3:182; 8:51; 22:10
- သူတို့အတွက် ဤလောက၌ အရှက်ကွဲခြင်းရှိ၏၊ သူတို့အတွက် နောင်လောက၌လည်း ကြီးလေးသော ပြစ်ဒဏ်ရှိ၏။ (لَهُمْ فِي الدُّنْيَا خِزْيٌ وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ) 2:114; 5:41
- မိုးကောင်းကင်များနှင့် မြေကြီးပေါ်၌ရှိသမျှတို့ကို (အလ္လာဟ်အရှင်မြတ်သည် ပိုင်ဆိုင်တော်မူ၏)၊ အလ္လာဟ်အရှင်မြတ်သည် ကိုယ်စားလှယ်အဖြစ် လုံလောက်တော်မူ၏။ (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَفَى بِاللَّهِ وَكِيلًا) 4:132; 4:171
- အီမာန်ယုံကြည်ပြီး ကောင်းမှုကုသိုလ်များ ပြုလုပ်ခဲ့ကြသော သူတို့မှအပ၊ သူတို့အတွက် မကုန်ဆုံးနိုင်သော ဆုလာဘ်ရှိ၏။ (إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 84:25; 95:6
- သင်သည် အသိပညာ မရှိသောအရာကို ကျွန်ုပ်နှင့် တွဲဖက်မထားရန်၊ ထို့ကြောင့် သူတို့နှစ်ဦးကို နာခံခြင်းမပြုလေနှင့်။ (لِتُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا) 29:8; 31:15
- အမှန်စင်စစ် ဤအရာသည် သတိပေးစကားတစ်ရပ် ဖြစ်၏။ သို့ဖြစ်ပေရာ အလိုရှိသူတိုင်း မိမိ၏အရှင်မြတ်ထံသို့ လမ်းကြောင်းတစ်ခုကို ယူဆောင်သွားပါစေ။ (إِنَّ هَذِهِ تَذْكِرَةٌ فَمَن شَاءَ اتَّخَذَ إِلَى رَبِّهِ سَبِيلًا) 73:19; 76:29
- ကျေးဇူးသိသောသူသည် မိမိကိုယ်အတွက်သာ ကျေးဇူးသိ၏။ ကျေးဇူးမသိသောသူမူကား။ (وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ وَمَن كَفَرَ فَإِنَّ) 27:40; 31:12
- ထိုသူတို့သည် ဆွလာသ်ဝတ်ပြုမှုကို ထိန်းသိမ်းကြ၏၊ ဇကာသ်အလှူကို ပေးကြ၏၊ ထို့ပြင် နောင်လောကကို ယုံကြည်ကြ၏။ (الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَهُم بِالْآخِرَةِ هُمْ يُوقِنُونَ) 27:3; 31:4
- အီဗရာဟီမ်၊ အီစ်မာအီလ်၊ အစ်စ်ဟာက်၊ ယာကူ့ဘ်နှင့် မျိုးနွယ်စုများထံသို့လည်းကောင်း၊ မူစာနှင့် အီစာတို့အား ပေးအပ်တော်မူခဲ့သောအရာများကိုလည်းကောင်း (ယုံကြည်ကြ၏)။ (إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَى وَعِيسَى) 2:136; 3:84
- အစုလိုက်အဖွဲ့လိုက် လာကြပြီး၊ ၎င်းတို့ထိုအရပ်သို့ ရောက်ရှိသောအခါ၊ ၎င်း၏တံခါးများကို ဖွင့်ပေးခြင်းခံကြရမည်၊ ၎င်း၏အစောင့်များက သူတို့အား ပြောဆိုကြလိမ့်မည်။ (زُمَرًا حَتَّى إِذَا جَاءُوهَا فُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا) 39:71; 39:73
- အလ္လာဟ်အရှင်မြတ်သည် သင်တို့၏ ကျိန်ဆိုချက်များရှိ အချည်းနှီးသောစကားများအတွက် သင်တို့အား ဖမ်းဆီးတော်မူမည်မဟုတ်၊ သို့သော် သင်တို့၏စိတ်နှလုံးတို့ ရည်စူးခဲ့သောအရာအတွက် ဖမ်းဆီးတော်မူမည်။ (لَّا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِن يُؤَاخِذُكُم بِمَا) 2:225; 5:89
- ကရုဏာတော် (ရောက်လာသောအခါ) သူတို့သည် ယင်းအတွက် ဝမ်းမြောက်ကြ၏။ အကယ်၍ သူတို့၏လက်များက ရှေ့သို့ ပို့ခဲ့သောအရာများကြောင့် ဆိုးကျိုးတစ်ခုခု သူတို့အား ထိမိပါက။ (رَحْمَةً فَرِحُوا بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ) 30:36; 42:48
- အောက်မှ မြစ်ချောင်းများ စီးဆင်းသော ဥယျာဉ်တော်များ၊ ထိုဥယျာဉ်တော်များ၌ သူတို့သည် အစဉ်ထာဝရ နေထိုင်ကြရမည်။ ကောင်းမှုပြုသူတို့၏ ဆုလာဘ်သည် အလွန်ကောင်းမွန်လှ၏။ (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَنِعْمَ أَجْرُ الْعَامِلِينَ) 3:136; 29:58
- အလ္လာဟ်အရှင်မြတ်သည် မိုးကောင်းကင်များနှင့် မြေကြီးပေါ်၌ရှိသမျှတို့ကို သိရှိတော်မူ၏၊ အလ္လာဟ်အရှင်မြတ်သည်။ (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَاللَّهُ) 3:29; 49:16
- အလ္လာဟ်အရှင်မြတ်ကို နာခံကြလော့၊ ရစူလ်တမန်တော်ကိုလည်း နာခံကြလော့။ အကယ်၍ သင်တို့ မျက်နှာလွှဲပါက၊ ထိုအရှင်မြတ်၏တာဝန်မှာ။ (أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِن تَوَلَّوْا فَإِنَّمَا عَلَيْهِ) 24:54; 64:12
- သူတို့အတွက် သူတို့၏အရှင်မြတ်ထံတော်၌ သူတို့၏ဆုလာဘ်ရှိ၏၊ သူတို့အပေါ်၌ ကြောက်ရွံ့ခြင်းမရှိ၊ သူတို့သည်။ (فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:274; 2:277
- ထို့ပြင် သူတို့က ပြောဆိုခဲ့ကြ၏။ "အကယ်၍ ကျွန်ုပ်တို့သည် အရိုးစုများနှင့် အမှုန့်အမွှားများ ဖြစ်သွားပါက၊ အသစ်တစ်ဖန် ဖန်ဆင်းခြင်း ခံရမည်လော။" (وَقَالُوا أَإِذَا كُنَّا عِظَامًا وَرُفَاتًا أَإِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا) 17:49; 17:98
- ထို့ပြင် သူတို့သည် အလ္လာဟ်အရှင်မြတ်မှတစ်ပါး မိမိတို့အတွက် ကာကွယ်သူလည်းမရှိ၊ အကူအညီပေးသူလည်းမရှိ။ (وَلَا يَجِدُونَ لَهُم مِّن دُونِ اللَّهِ وَلِيًّا وَلَا نَصِيرًا) 4:173; 33:17
- "သင်မည်မျှကြာ နေထိုင်ခဲ့သနည်း။" သူက ပြန်ပြောဆိုခဲ့၏။ "ကျွန်ုပ်သည် တစ်ရက် သို့မဟုတ် တစ်ရက်၏ တစ်စိတ်တစ်ပိုင်းမျှ နေထိုင်ခဲ့၏။" သူက ပြောဆိုခဲ့၏။ (كَمْ لَبِثْتَ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالَ) 2:259; 18:19
- ကိယာမနေ့တော်တိုင်အောင် အစဉ်ထာဝရ၊ အလ္လာဟ်အရှင်မြတ်မှတစ်ပါး သင်တို့ထံသို့ ယူဆောင်လာနိုင်သော ကိုးကွယ်ရာဟူ၍ မည်သူရှိသနည်း။ (سَرْمَدًا إِلَى يَوْمِ الْقِيَامَةِ مَنْ إِلَهٌ غَيْرُ اللَّهِ يَأْتِيكُم) 28:71; 28:72
- ကောင်းမှုကုသိုလ်ကို ပြုလုပ်သောသူ၊ ယောက်ျားဖြစ်စေ၊ မိန်းမဖြစ်စေ၊ ထိုသူသည် အီမာန်ယုံကြည်သူလည်းဖြစ်၏။ (مَنْ عَمِلَ صَالِحًا مِّن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ) 16:97; 40:40
- ထိုသူတို့သည် အလ္လာဟ်အရှင်မြတ်၏လမ်းတော်မှ တားဆီးပိတ်ပင်ကြ၏၊ ထိုလမ်းတော်ကို ကောက်ကွေ့စေလိုကြ၏၊ ထို့ပြင် နောင်လောကကို ငြင်းပယ်ကြ၏။ (الَّذِينَ يَصُدُّونَ عَن سَبِيلِ اللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِالْآخِرَةِ) 7:45; 11:19
- သင်တို့ အလိုရှိရာအရပ်၌ (စားသုံးကြလော့)၊ သို့ရာတွင် ဤသစ်ပင်နှင့် မနီးကပ်ကြလေနှင့်၊ သို့မှမဟုတ် သင်တို့သည် မတရားကျူးလွန်သူများ ဖြစ်သွားလိမ့်မည်။ (حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَذِهِ الشَّجَرَةَ فَتَكُونَا مِنَ الظَّالِمِينَ) 2:35; 7:19
- သင်ပြောလိုက်ပါ။ "အို ကျွန်ုပ်၏လူမျိုးတို့၊ သင်တို့သည် သင်တို့၏ နည်းလမ်းအတိုင်း လုပ်ဆောင်ကြလော့၊ ကျွန်ုပ်သည် လုပ်ဆောင်နေပါ၏။ ထို့နောက် သင်တို့ သိကြလိမ့်မည်။" (قُلْ يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 39:39
- အမှန်စင်စစ် ဆုံးရှုံးသူများမှာ ကိယာမနေ့တော်၌ မိမိတို့ကိုယ်ကို ဆုံးရှုံးခဲ့ကြသော သူများနှင့် မိမိတို့၏ မိသားစုဝင်များကို ဆုံးရှုံးခဲ့ကြသော သူများပင် ဖြစ်၏။ (إِنَّ الْخَاسِرِينَ الَّذِينَ خَسِرُوا أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ الْقِيَامَةِ أَلَا) 39:15; 42:45
- လမ်းမှန်ရောက်သောသူသည် မိမိကိုယ်အတွက်သာ လမ်းမှန်ရောက်၏။ လမ်းလွဲသောသူမူကား မိမိကိုယ်ကိုသာ လမ်းလွဲစေ၏။ (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَا) 10:108; 39:41
- မယုံကြည်သောသူတို့က "အဘယ်ကြောင့် သူ့အတွက် သူ့အရှင်မြတ်ထံမှ နိမိတ်လက္ခဏာတစ်ခု မချပေးခဲ့သနည်း" ဟု ပြောဆိုကြ၏။ (وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ) 13:7; 13:27
- ထိုအရှင်မြတ်သည် သင်တို့အတွက် ညအချိန်၌ အနားယူရန်နှင့် နေ့အချိန်၌ အလင်းရောင်ရရန် ဖန်ဆင်းတော်မူသောအရှင်၊ အမှန်စင်စစ်။ (الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ) 10:67; 40:61
- ထိုနေ့တော်မရောက်မီတွင် ထိုနေ့၌ ရောင်းဝယ်ခြင်းလည်းမရှိ၊ ခင်မင်ရင်းနှီးခြင်းလည်းမရှိ။ (مِّن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا) 2:254; 14:31
- သူတို့သည် သူတို့၏အဖော်တွင် ရူးသွပ်ခြင်း မရှိကြောင်း ဆင်ခြင်သုံးသပ်ကြရန်၊ သူသည် သတိပေးသူတစ်ဦးမှအပ အခြားမဟုတ်ပေ။ (يَتَفَكَّرُوا مَا بِصَاحِبِهِم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ) 7:184; 34:46
- ထိုအရပ်၌ သူတို့သည် အစဉ်ထာဝရ နေထိုင်ကြရမည်၊ သူတို့ထံမှ ပြစ်ဒဏ်ကို သက်သာစေခြင်းမပြုရ၊ သူတို့အား အချိန်ဆိုင်းငံ့ခြင်းလည်း မပြုရ။ (خَالِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنظَرُونَ) 2:162; 3:88
- သင်သည် ကျွန်ုပ်တို့က ၎င်းတို့အနက် အချို့အား ခံစားခွင့်ပေးခဲ့သောအရာများဆီသို့ သင်၏မျက်လုံးများကို မစိုက်လေနှင့်။ (لَا تَمُدَّنَّ عَيْنَيْكَ إِلَى مَا مَتَّعْنَا بِهِ أَزْوَاجًا مِّنْهُمْ) 15:88; 20:131
- ထို့ပြင် လူတို့အား သူတို့၏ပစ္စည်းဥစ္စာများကို မလျှော့ချကြလေနှင့်၊ မြေကြီးပေါ်၌လည်း ဖျက်ဆီးသူများအဖြစ် မနေထိုင်ကြလေနှင့်။ (وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ) 11:85; 26:183
- ထိုသူအား သူဖွားမြင်သောနေ့၊ သေဆုံးသောနေ့နှင့် အသက်ရှင်လျက် ပြန်လည်ထမြောက်တော်မူသောနေ့တို့၌ ငြိမ်သက်ခြင်းသတင်း ရှိပါစေ။ (وَسَلَامٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيًّا) 19:15; 19:33
- အို ကျွန်ုပ်၏လူမျိုးတို့၊ သင်တို့သည် သင်တို့၏ နည်းလမ်းအတိုင်း လုပ်ဆောင်ကြလော့၊ ကျွန်ုပ်သည် လုပ်ဆောင်နေပါ၏။ ထို့နောက် မည်သူဖြစ်သည်ကို သင်တို့ သိကြလိမ့်မည်။ (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ مَن) 6:135; 11:93
- မည်သည့်ရစူလ်တမန်တော်အတွက်မျှ အလ္လာဟ်အရှင်မြတ်၏ ခွင့်ပြုချက်မပါဘဲ နိမိတ်လက္ခဏာတစ်ခုကို ယူဆောင်လာရန် မဖြစ်နိုင်ချေ။ (وَمَا كَانَ لِرَسُولٍ أَن يَأْتِيَ بِآيَةٍ إِلَّا بِإِذْنِ اللَّهِ) 13:38; 40:78
- ထို့နောက် သတ္တဝါတိုင်းအား မိမိရရှိခဲ့သောအရာအတွက် အပြည့်အစုံ ဆပ်ပေးခြင်းခံကြရမည်၊ သူတို့အပေါ်၌ မတရားပြုကျင့်ခြင်း မပြုရ။ (ثُمَّ تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:161
- ယောက်ျားဖြစ်စေ၊ မိန်းမဖြစ်စေ၊ ထိုသူသည် အီမာန်ယုံကြည်သူလည်းဖြစ်၏၊ သို့ဖြစ်လျှင် ထိုသူတို့သည် ဥယျာဉ်တော်သို့ ဝင်ရောက်ကြရမည်။ (مِن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ فَأُولَئِكَ يَدْخُلُونَ الْجَنَّةَ) 4:124; 40:40
- ထိုအရှင်မြတ်သည် သားသမီးကို ယူဆောင်တော်မူသည်မရှိ၊ နိုင်ငံတော်၌လည်း အရှင်မြတ်အတွက် ပူးပေါင်းဆောင်ရွက်သူ မရှိချေ။ (لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُ شَرِيكٌ فِي الْمُلْكِ) 17:111; 25:2
- အလ္လာဟ်အရှင်မြတ်သည် လမ်းမှန်ပြသောသူအား ထိုသူသည်ပင် လမ်းမှန်ရောက်၏။ အရှင်မြတ်သည် လမ်းလွဲစေတော်မူသောသူအတွက် သင်သည် မည်သည့်အခါမျှ မတွေ့ရှိနိုင်။ (وَمَن يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ) 17:97; 18:17
- သူတို့သည် သင့်အတွက် မည်သို့သော ဥပမာများကို ပေးဆောင်ခဲ့ကြသည်ကို ကြည့်ရှုလော့၊ သို့ဖြစ်၍ သူတို့သည် လမ်းလွဲခဲ့ကြ၏။ သို့ဖြစ်ပေရာ သူတို့သည် လမ်းကြောင်းကို မရှာဖွေနိုင်ကြချေ။ (انظُرْ كَيْفَ ضَرَبُوا لَكَ الْأَمْثَالَ فَضَلُّوا فَلَا يَسْتَطِيعُونَ سَبِيلًا) 17:48; 25:9
- သင်ပြောလိုက်ပါ။ "အကယ်၍ ကျွန်ုပ်သည် ကျွန်ုပ်၏အရှင်မြတ်ကို နာခံမှုမပြုပါက၊ ကြီးကျယ်သောနေ့၏ ပြစ်ဒဏ်ကို ကြောက်ရွံ့ပါ၏။" (قُلْ إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 39:13
- သူတို့နှစ်ဦး၏ အဝတ်အစားများ ဖယ်ရှားခြင်းခံလိုက်ရသဖြင့်၊ သူတို့နှစ်ဦးသည် ဥယျာဉ်တော်မှ အရွက်များဖြင့် မိမိတို့ကိုယ်ကို ဖုံးအုပ်လာကြ၏။ (بَدَتْ لَهُمَا سَوْآتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ الْجَنَّةِ) 7:22; 20:121
- ထို့ပြင် အလ္လာဟ်အရှင်မြတ်မှတစ်ပါး သင်တို့တတ်နိုင်သော အရာများကို ခေါ်ဆိုကြလော့၊ အကယ်၍ သင်တို့သည် မှန်ကန်သူများဖြစ်ပါက။ (وَادْعُوا مَنِ اسْتَطَعْتُم مِّن دُونِ اللَّهِ إِن كُنتُمْ صَادِقِينَ) 10:38; 11:13
- မြေကြီးပေါ်၌ရှိသမျှအရာနှင့် ၎င်းနှင့်တူသော နောက်ထပ်တစ်ဆယ်တို့ကို (ပိုင်ဆိုင်သော်လည်း) ၎င်းတို့ဖြင့် ရွေးနုတ်ရန် (ကြိုးစားကြလိမ့်မည်)။ (مَّا فِي الْأَرْضِ جَمِيعًا وَمِثْلَهُ مَعَهُ لِيَفْتَدُوا بِهِ مِنْ) 5:36; 39:47
- ကျွန်ုပ်တို့ သင်တို့အား ပေးအပ်တော်မူသောအရာကို ခိုင်မာစွာ ဆုပ်ကိုင်ကြလော့၊ ထိုအရာ၌ပါရှိသော အကြောင်းအရာများကို သတိရကြလော့၊ သင်တို့ ဘာသာတရားကို စောင့်ထိန်းနိုင်ကြရန်။ (خُذُوا مَا آتَيْنَاكُم بِقُوَّةٍ وَاذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ) 2:63; 7:171
- သင်တို့သည် ယင်းမတရားသော အကျင့်ကို ကျူးလွန်ကြသလော။ ယင်းသို့သော အကျင့်ကို သင်တို့ရှေ့မှ လောကသားတစ်ဦးတစ်ယောက်မျှ မကျူးလွန်ခဲ့ချေ။ (أَتَأْتُونَ الْفَاحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ الْعَالَمِينَ) 7:80; 29:28
- မိုးကောင်းကင်များနှင့် မြေကြီးပေါ်၌ရှိသမျှတို့သည် အလ္လာဟ်အရှင်မြတ်အတွက်ဖြစ်၏၊ အလ္လာဟ်အရှင်မြတ်သည်။ (وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَانَ اللَّهُ) 4:126; 4:131
- သူတို့ပြုလုပ်ခဲ့သော အပြစ်များ၏ ဆိုးကျိုးများသည် သူတို့ကို ဝန်းရံခဲ့၏။ ထို့ပြင် သူတို့ ပရိယာယ်ပြုခဲ့သောအရာသည်လည်း သူတို့ကို ဝန်းရံခဲ့၏။ (سَيِّئَاتُ مَا عَمِلُوا وَحَاقَ بِهِم مَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 16:34; 45:33
- သင်တို့အနက်မှ ရစူလ်တမန်တော်တစ်ပါးသည် သင်တို့အား ကျွန်ုပ်တို့၏ သက်သေလက္ခဏာများကို ဖတ်ကြားပေး၏၊ သင်တို့ကို သန့်စင်ပေး၏၊ ကျမ်းတော်နှင့် ပညာအလင်းကို သင်ပေး၏။ (رَسُولًا مِّنكُمْ يَتْلُو عَلَيْكُمْ آيَاتِنَا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ الْكِتَابَ وَالْحِكْمَةَ) 2:151; 62:2
- ထိုရေအရင်းမှ စမ်းရေတွင်းတစ်ဆယ့်နှစ်ခု စီးဆင်းခဲ့၏။ လူမျိုးတိုင်းသည် မိမိတို့၏ ရေသောက်ရာနေရာကို သိရှိခဲ့ကြ၏။ (مِنْهُ اثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ) 2:60; 7:160
- ထိုအရာသည် ထင်မြင်ချက်မျှသာဖြစ်၏၊ အမှန်စင်စစ် ထင်မြင်ချက်သည် အမှန်တရားနှင့် ပတ်သက်၍ မည်သည့်အကျိုးမျှ မပေးနိုင်ချေ။ (إِلَّا ظَنًّا إِنَّ الظَّنَّ لَا يُغْنِي مِنَ الْحَقِّ شَيْئًا) 10:36; 53:28
- သို့ဖြစ်ပေရာ ကျွန်ုပ်က ၎င်းကို ပုံသွင်းပြီးစီးသောအခါ၊ ကျွန်ုပ်၏ဝိညာဉ်မှ ၎င်းအတွင်းသို့ မှုတ်သွင်းလိုက်သောအခါ၊ သင်တို့သည် ယင်းအား ဦးချကြလော့။ (فَإِذَا سَوَّيْتُهُ وَنَفَخْتُ فِيهِ مِن رُّوحِي فَقَعُوا لَهُ سَاجِدِينَ) 15:29; 38:72
- ထိုအိမ်၏ ကောင်းသောအဆုံးအဖြတ်သည် မည်သူ့အတွက်ဖြစ်သနည်း။ အမှန်စင်စစ် မတရားကျူးလွန်သူများသည် အောင်မြင်ကြမည်မဟုတ်ချေ။ (مَن تَكُونُ لَهُ عَاقِبَةُ الدَّارِ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ) 6:135; 28:37
- ထိုအရှင်မြတ်သည် မိုးကောင်းကင်များနှင့် မြေကြီးကို ဖန်ဆင်းတော်မူသောအရှင်၊ ထိုအရှင်မြတ်သည် သူတို့နှင့်တူသောအရာများကို ဖန်ဆင်းတော်မူနိုင်စွမ်းရှိတော်မူ၏။ (الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ قَادِرٌ عَلَى أَن يَخْلُقَ مِثْلَهُمْ) 17:99; 36:81
- အီမာန်ယုံကြည်သော ယောက်ျားများနှင့် အီမာန်ယုံကြည်သော မိန်းမများအတွက် အောက်မှ မြစ်ချောင်းများ စီးဆင်းသော ဥယျာဉ်တော်များရှိ၏၊ ထိုဥယျာဉ်တော်များ၌ သူတို့သည် အစဉ်ထာဝရ နေထိုင်ကြရမည်။ (الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 9:72; 48:5
- အကယ်၍ သင်သည် သူတို့အား မိုးကောင်းကင်များနှင့် မြေကြီးကို မည်သူဖန်ဆင်းတော်မူခဲ့သနည်းဟု မေးမြန်းပါက၊ သူတို့သည် "အလ္လာဟ်အရှင်မြတ်" ဟု ဆိုကြလိမ့်မည်၊ သင်ပြောလိုက်ပါ။ (وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ لَيَقُولُنَّ اللَّهُ قُلِ) 31:25; 39:38
- ထို့ပြင် ကျွန်ုပ်တို့သည် ဤကုရ်အာန်ကျမ်းတော်မြတ်၌ လူသားများအတွက် ဥပမာမျိုးစုံကို ဖော်ပြခဲ့ကြ၏။ (وَلَقَدْ ضَرَبْنَا لِلنَّاسِ فِي هَذَا الْقُرْآنِ مِن كُلِّ مَثَلٍ) 30:58; 39:27
- ကျွန်ုပ်တို့၏ ရစူလ်တမန်တော်များသည် လူတ်ထံသို့ ရောက်လာသောအခါ၊ သူသည် သူတို့အတွက် အလွန်အမင်း စိတ်ဆင်းရဲခဲ့၏၊ စိတ်ကျဉ်းမြောင်းခဲ့၏၊ ထို့ပြင် ပြောဆိုခဲ့၏။ (جَاءَتْ رُسُلُنَا لُوطًا سِيءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعًا وَقَالَ) 11:77; 29:33
- ထို့ပြင် ကျွန်ုပ်တို့သည် ကောင်းကင်တမန်များအား "အာဒမ်ကို ဦးချကြလော့" ဟု မိန့်ကြားတော်မူခဲ့သောအခါ၊ သူတို့သည် ဦးချကြ၏။ အီဗလီစ်မှအပ၊ သူသည် ငြင်းဆန်ခဲ့၏။ (وَإِذْ قُلْنَا لِلْمَلَائِكَةِ اسْجُدُوا لِآدَمَ فَسَجَدُوا إِلَّا إِبْلِيسَ أَبَى) 2:34; 20:116
- ထို့ပြင် မြေကြီးကို ကျွန်ုပ်တို့ဖြန့်ခင်းတော်မူခဲ့၏၊ ထိုမြေကြီးပေါ်၌ တောင်တန်းများကို စိုက်ထူတော်မူခဲ့၏၊ ထိုမြေကြီးပေါ်၌ အမျိုးမျိုးသော အပင်များကို ပေါက်ရောက်စေတော်မူခဲ့၏။ (وَالْأَرْضَ مَدَدْنَاهَا وَأَلْقَيْنَا فِيهَا رَوَاسِيَ وَأَنبَتْنَا فِيهَا مِن كُلِّ) 15:19; 50:7
- သူတို့သည် အလ္လာဟ်အရှင်မြတ်အား စိတ်ရိုးဖြောင့်ခံစားမှုဖြင့် ခေါ်ဆိုကြ၏၊ ထို့နောက် အရှင်မြတ်သည် သူတို့အား ကုန်းမြေသို့ ကယ်တင်တော်မူသောအခါ။ (دَعَوُا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ فَلَمَّا نَجَّاهُمْ إِلَى الْبَرِّ) 29:65; 31:32
- သူတို့အတွက် ပြုတ်ကျဲသော ရေမှ သောက်စရာရှိ၏၊ ထို့ပြင် သူတို့ မယုံကြည်ခဲ့သောကြောင့် နာကျင်စေသော ပြစ်ဒဏ်လည်းရှိ၏။ (لَهُمْ شَرَابٌ مِّنْ حَمِيمٍ وَعَذَابٌ أَلِيمٌ بِمَا كَانُوا يَكْفُرُونَ) 6:70; 10:4
- အလ္လာဟ်အရှင်မြတ်မှတစ်ပါး ကျွန်ုပ်တို့အား အကျိုးလည်းမပေးနိုင်၊ အပြစ်လည်းမပေးနိုင်သော အရာကို ကျွန်ုပ်တို့ ခေါ်ဆိုကြမည်လော။ (أَنَدْعُو مِن دُونِ اللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا) 6:71; 10:106
- အလ္လာဟ်အရှင်မြတ်သည် မိုးကောင်းကင်များနှင့် မြေကြီးပေါ်၌ရှိသမျှတို့ကို သိရှိတော်မူကြောင်း (သင်တို့သိကြလော့)။ (أَنَّ اللَّهَ يَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 5:97; 58:7
