- ထိုအရာတွင် သက်သေလက္ခဏာတစ်ခု ရှိပေသည်။ သို့ရာတွင် သူတို့အများစုသည် ယုံကြည်သူများ မဟုတ်ကြပေ။ (إِنَّ فِي ذَلِكَ لَآيَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ) 26:8; 26:67; 26:103; 26:121; 26:139; 26:158; 26:174; 26:190
- သူတို့သည် မြေကြီးပေါ်တွင် လှည့်လည်သွားလာ၍ ယခင်လူများ၏ အဆုံးစီရင်ခြင်းသည် မည်သို့ဖြစ်ခဲ့သည်ကို ကြည့်ရှုကြစေသတည်း။ (يَسِيرُوا فِي الْأَرْضِ فَيَنظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذِينَ) 12:109; 30:9; 30:42; 35:44; 40:21; 40:82; 47:10
- သူက ပြောဆိုခဲ့သည်- အို ကျွန်ုပ်၏လူမျိုးသားတို့၊ အလ္လာဟ်အရှင်မြတ်ကို ကိုးကွယ်ကြလော့။ အရှင်မြတ်မှတစ်ပါး သင်တို့အား ဘုရားတစ်ဆူ မရှိချေ။ (قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ) 7:65; 7:73; 7:85; 11:50; 11:61; 11:84; 23:23
- အရှင်မြတ်သည် သူအား အောက်မှမြစ်ချောင်းများ စီးဆင်းနေသော ဥယျာဉ်တော်များသို့ သွင်းတော်မူမည်။ ထိုဥယျာဉ်တော်များတွင် သူတို့သည် ထာဝရစံနေကြရမည်။ (يُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 4:13; 4:57; 4:122; 58:22; 64:9; 65:11
- ရှင်ပြန်ထမြောက်သောနေ့တွင် သူတို့အကြား သဘောထားကွဲလွဲနေကြရာကို စီရင်ဆုံးဖြတ်တော်မူမည်။ (بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 2:113; 10:93; 16:124; 22:69; 32:25; 45:17
- သူတို့သည် မြေကြီးပေါ်တွင် လှည့်လည်သွားလာ၍ (ယခင်လူများ၏) အဆုံးစီရင်ခြင်းသည် မည်သို့ဖြစ်ခဲ့သည်ကို မကြည့်ရှုကြသလော။ (أَوَلَمْ يَسِيرُوا فِي الْأَرْضِ فَيَنظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 30:9; 35:44; 40:21; 40:82; 47:10
- အောက်မှမြစ်ချောင်းများ စီးဆင်းနေသော ဥယျာဉ်တော်များ၊ ထိုဥယျာဉ်တော်များတွင် သူတို့သည် ထာဝရအမြဲတည်နေကြရမည်။ (جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا) 4:57; 4:122; 5:119; 64:9; 65:11
- အရှင်မြတ်သည် ညဉ့်ကို နေ့တွင်းသို့ သွင်းတော်မူ၏။ နေ့ကိုလည်း ညဉ့်တွင်းသို့ သွင်းတော်မူ၏။ (تُولِجُ اللَّيْلَ فِي النَّهَارِ وَتُولِجُ النَّهَارَ فِي اللَّيْلِ) 3:27; 22:61; 31:29; 35:13; 57:6
- မိုးကောင်းကင်များနှင့် မြေကြီးပေါ်ရှိ အရာအားလုံးသည် အလ္လာဟ်အရှင်မြတ်အား ချီးမွမ်းဆုတောင်းကြသည်။ (سَبَّحَ لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 59:1; 61:1; 62:1; 64:1
- အလ္လာဟ်အရှင်မြတ်ကို ကိုးကွယ်ကြလော့။ အရှင်မြတ်မှတစ်ပါး သင်တို့အား ဘုရားတစ်ဆူ မရှိချေ။ သို့ဖြစ်လျှင် သင်တို့ (အရှင်မြတ်အား) မကြောက်ရွံ့ကြသလော။ (اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا) 7:65; 11:84; 23:23; 23:32
- ကောင်းကင်တမန်များအား အာဒမ်အား ဦးညွှတ်ကြလော့ဟု ငါအရှင်မြတ်က မိန့်ဆိုသောအခါ အိဗ်လီစ်မှတစ်ပါး သူတို့အားလုံး ဦးညွှတ်ခဲ့ကြသည်။ (وَإِذْ قُلْنَا لِلْمَلَائِكَةِ اسْجُدُوا لِآدَمَ فَسَجَدُوا إِلَّا إِبْلِيسَ) 2:34; 17:61; 18:50; 20:116
- အလ္လာဟ်အရှင်မြတ်သည် မိုးကောင်းကင်များနှင့် မြေကြီးပေါ်ရှိအရာအားလုံးကို သိရှိတော်မူ၏။ (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 3:29; 5:97; 49:16; 58:7
- အောက်မှမြစ်ချောင်းများ စီးဆင်းနေသော ဥယျာဉ်တော်များ၊ ထိုဥယျာဉ်တော်များတွင် သူတို့သည် ထာဝရတည်နေကြရမည်၊ ယင်းသည်။ (جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ) 4:13; 5:85; 9:89; 57:12
- သူ၏အကျိုးဆုလဒ်သည် သူ၏အရှင်သခင်၏အထံတွင် ရှိ၏။ သူတို့အား ကြောက်ရွံ့ခြင်းမရှိသကဲ့သို့ သူတို့။ (أَجْرُهُ عِندَ رَبِّهِ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:112; 2:262; 2:274; 2:277
- သူ၏အရှင်သခင်၏အထံတွင်၊ သူတို့အား ကြောက်ရွံ့ခြင်းမရှိသကဲ့သို့ သူတို့သည် ဝမ်းနည်းကြေကွဲခြင်းလည်း မရှိကြ။ (عِندَ رَبِّهِ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ) 2:112; 2:262; 2:274; 2:277
- မည်သူမဆို တရားလမ်းမှန်ကို ရရှိခဲ့ပါက မိမိအတွက်သာ ရရှိခြင်းဖြစ်၏။ မည်သူမဆို လမ်းမှားသွားပါက။ (فَمَنِ اهْتَدَى فَإِنَّمَا يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ) 10:108; 17:15; 27:92
- မိမိအတွက်သာ ရရှိခြင်းဖြစ်၏။ မည်သူမဆို လမ်းမှားသွားပါက မိမိ၏ဆုံးရှုံးခြင်းအတွက်သာ လမ်းမှားခြင်းဖြစ်၏။ (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا) 10:108; 17:15; 39:41
- အရှင်မြတ်၏အထံတော်မှ သူ့အား သက်သေလက္ခဏာတစ်ခု အဘယ်ကြောင့် မချပေးခဲ့သနည်း။ (အို-နဗီတမန်တော်) အမိန့်တော်ရှိလော့- စင်စစ်။ (لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا) 10:20; 13:27; 29:50
- အကြင်သူတို့သည် ယုံကြည်ခဲ့ကြပြီး ကောင်းမြတ်သောအကျင့်များကို ကျင့်ကြံပြုမူခဲ့ကြ၏။ ထိုသူတို့အား ပြတ်တောက်ခြင်းမရှိသော အကျိုးဆုလဒ် ရှိပေသည်။ (الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 41:8; 84:25; 95:6
- အရှင်မြတ်သည် အသက်ရှိသောအရာကို သေသောအရာမှ ထုတ်ယူတော်မူ၏။ သေသောအရာကိုလည်း အသက်ရှိသောအရာမှ ထုတ်ယူတော်မူ၏။ (وَتُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَتُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ) 3:27; 10:31; 30:19
- အကြင်သူသည် အလ္လာဟ်အရှင်မြတ် ချပေးသနားတော်မူသည့်အတိုင်း တရားစီရင်မဆုံးဖြတ်ပါ၊ ထိုသူတို့သည်။ (وَمَن لَّمْ يَحْكُم بِمَا أَنزَلَ اللَّهُ فَأُولَئِكَ هُمُ) 5:44; 5:45; 5:47
- အရှင်မြတ်သည် မိုးကောင်းကင်များ၊ မြေကြီးနှင့် ယင်းတို့အကြားရှိအရာအားလုံးကို ခြောက်ရက်အတွင်း ဖန်ဆင်းတော်မူ၏။ (خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا فِي سِتَّةِ أَيَّامٍ) 25:59; 32:4; 50:38
- အလ္လာဟ်အရှင်မြတ်သည် လူသားတို့အပေါ် ကျေးဇူးတော်ရှင်တော်မူသည်။ သို့ရာတွင် အများစုသော။ (إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَ) 2:243; 10:60; 40:61
- အလ္လာဟ်အရှင်မြတ်သည် သူတို့အား မတရားပြုသောအရှင် မဟုတ်ချေ။ သို့သော် သူတို့သည် မိမိတို့ကိုယ်ကိုသာ မတရားပြုနေကြခြင်းဖြစ်၏။ (فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 29:40; 30:9
- အရှင်မြတ်သည် သင်တို့၏အပြစ်များကို လွှတ်တော်မူမည်ဖြစ်ပြီး သင်တို့အား အောက်မှမြစ်ချောင်းများ စီးဆင်းနေသော ဥယျာဉ်တော်များသို့ သွင်းတော်မူမည်။ (عَنكُمْ سَيِّئَاتِكُمْ وَلَأُدْخِلَنَّكُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 5:12; 64:9; 66:8
- အရှင်မြတ်သည် သင်တို့အပေါ် သေသောအသား၊ သွေး၊ ဝက်သားနှင့် အလ္လာဟ်အရှင်မြတ်မှတစ်ပါး အခြားအမည်ဖြင့် သတ်ခြင်းခံရသောအရာတို့ကို ဟရာမ်ဖြစ်စေတော်မူခဲ့၏။ (حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 5:3; 16:115
- စင်စစ်အားဖြင့် ကျွန်ုပ်၏အရှင်သခင်၏ အမိန့်တော်ကို လွန်ကျူးပါက ကြီးလေးသောနေ့တွင် ခံရမည့် ပြစ်ဒဏ်ကို ကျွန်ုပ်ကြောက်ရွံ့ပါ၏။ (إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 10:15; 39:13
- သူတို့ထံ အသိပညာရောက်ရှိပြီးနောက် သူတို့အကြား ငြူစူမှုကြောင့်သာ (ကွဲပြားခဲ့ကြသည်)။ (إِلَّا مِن بَعْدِ مَا جَاءَهُمُ الْعِلْمُ بَغْيًا بَيْنَهُمْ) 3:19; 42:14; 45:17
- သူတို့သည် ဆွလာသ်ဝတ်ပြုမှုကို ထိန်းသိမ်းဆောက်တည်ကြပြီး ငါအရှင်မြတ် ပေးအပ်ထားသော စားနပ်ရိက္ခာမှ လျှို့ဝှက်စွာနှင့် လူသိရှင်ကြား လှူဒါန်းကြ၏။ (وَأَقَامُوا الصَّلَاةَ وَأَنفَقُوا مِمَّا رَزَقْنَاهُمْ سِرًّا وَعَلَانِيَةً) 13:22; 14:31; 35:29
- အလ္လာဟ်အရှင်မြတ်ကို ပယ်ထားခဲ့၍ ကျွန်ုပ်တို့အား အကျိုးမပြုနိုင်၊ အန္တရာယ်လည်း မပေးနိုင်သောအရာကို (ကိုးကွယ်ခြင်းလော)။ (مِن دُونِ اللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا) 6:71; 10:106; 25:55
- သူတို့သည် သင်၏ထံသို့ ချပေးသနားတော်မူသောအရာနှင့် သင့်မတိုင်မီ ချပေးသနားတော်မူခဲ့သော အရာတို့ကို ယုံကြည်ကြသည်။ (يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ) 2:4; 4:60; 4:162
- အလ္လာဟ်အရှင်မြတ်သည် မိုးကောင်းကင်မှ ရေကို ချပေးသနားတော်မူသည်ကို အသင်မြင်တွေ့တော်မူသလော။ (أَلَمْ تَرَ أَنَّ اللَّهَ أَنزَلَ مِنَ السَّمَاءِ مَاءً) 22:63; 35:27; 39:21
- အရှင်မြတ်သည် တစ်စုံတစ်ခုသောအရာကို ဖြတ်သန်းဆုံးဖြတ်တော်မူသောအခါ ထိုအရာအား ဖြစ်လော့ဟု မိန့်ဆိုတော်မူရုံသာ ရှိသည်။ ထိုအခါ ထိုအရာလည်း ဖြစ်သွားလေသည်။ (قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ) 3:47; 19:35; 40:68
- မဒ်ယန်သို့လည်း သူတို့၏ညီတော် ရှိုအိုက်ဗ်ကို (အရှင်မြတ်က စေလွှတ်တော်မူ၏)။ သူက ပြောဆိုခဲ့သည်- အို ကျွန်ုပ်၏လူမျိုးသားတို့၊ အလ္လာဟ်အရှင်မြတ်ကို ကိုးကွယ်ကြလော့။ (وَإِلَى مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ) 7:85; 11:84; 29:36
- ယင်းသည် သိမြင်မရသောဝှက်ထားသည့် သတင်းများမှ ဖြစ်၏။ ငါအရှင်မြတ်က ၎င်းတို့ကို သင့်အား ဝဟီမြတ်ဖြင့် ပေးအပ်၏။ အသင်သည် (ယင်းတို့ကို) မသိခဲ့ပေ။ (ذَلِكَ مِنْ أَنْبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ) 3:44; 11:49; 12:102
- သူတို့၏သတ်မှတ်ချိန်ကျရောက်လာသောအခါ ထိုအချိန်ကို တစ်နာရီမျှမနှောင်းနိုင်သကဲ့သို့ မစောစီးနိုင်ကြပေ။ (فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49; 16:61
- ရှိုင်တွန်၏ ခြေရာများကို သင်တို့မလိုက်ကြနှင့်။ စင်စစ် ယင်းသည် သင်တို့အတွက် ထင်ရှားသောရန်သူ ဖြစ်ပေသည်။ (وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ) 2:168; 2:208; 6:142
- လူသားများအနက် အချို့သည် အသိပညာမရှိဘဲ အလ္လာဟ်အရှင်မြတ်နှင့် ပတ်သက်၍ အငြင်းအခုံ ပြုကြ၏။ (وَمِنَ النَّاسِ مَن يُجَادِلُ فِي اللَّهِ بِغَيْرِ عِلْمٍ) 22:3; 22:8; 31:20
- အလ္လာဟ်အရှင်မြတ်သည် အလိုတော်ရှိသူအား ပေးသနားတော်မူ၏။ အလ္လာဟ်အရှင်မြတ်သည် အလွန်ကြီးကျယ်သော ကျေးဇူးတော်ရှင်ဖြစ်တော်မူ၏။ (اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 57:29; 62:4
- ဝိညာဉ်တိုင်းသည် မိမိပြုခဲ့သမျှအတွက် ပြည့်ပြည့်စုံစုံ အကျိုးဆုလဒ်ကို ရရှိကြမည်။ သူတို့အား မတရားပြုခြင်း မခံရကြ။ (تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:25; 3:161
- အလ္လာဟ်အရှင်မြတ်က ဟရာမ်ဖြစ်စေတော်မူသော ဝိညာဉ်ကို တရားမျှတမှုဖြင့်မှတစ်ပါး သင်တို့ မသတ်ကြနှင့်။ (وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ) 6:151; 17:33; 25:68
- အရှင်မြတ်သည် တစ်စုံတစ်ခုသောအရာကို ဖြတ်သန်းဆုံးဖြတ်တော်မူသောအခါ ထိုအရာအား ဖြစ်လော့ဟု မိန့်ဆိုတော်မူရုံသာရှိ၏။ (إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن) 3:47; 19:35; 40:68
- သင်တို့သည် ငရဲဂျဟန္နမ်၏တံခါးများသို့ ဝင်ကြလော့။ ထိုအရပ်၌ ထာဝရတည်နေကြရမည်။ မာနထောင်လွှားသူတို့၏ နေရာသည် အလွန်ဆိုးရွားလှပေသတည်း။ (فَادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ) 16:29; 39:72; 40:76
- အကြင်သူတို့အား ကျမ်းမြတ်မှ တစ်စိတ်တစ်ပိုင်း ပေးအပ်ခြင်းခံရသည်ကို အသင်မမြင်သလော။ (أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ) 3:23; 4:44; 4:51
- သူတို့အတွက် အောက်မှမြစ်ချောင်းများ စီးဆင်းနေသော ဥယျာဉ်တော်များရှိ၏။ ထိုဥယျာဉ်တော်များတွင် သူတို့သည် ထာဝရတည်နေကြရမည်။ (لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:198; 5:119; 9:89
- အို ကျွန်ုပ်၏လူမျိုးသားတို့၊ သင်တို့သည် မိမိတို့၏အနေအထားအတိုင်း လုပ်ကိုင်ဆောင်ရွက်ကြလော့။ ကျွန်ုပ်လည်း လုပ်ကိုင်ဆောင်ရွက်ပါမည်။ သို့ဖြစ်လျှင် သင်တို့သိရှိကြလတ္တံ့။ (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 11:93; 39:39
- အကြင်သူသည် အလ္လာဟ်အရှင်မြတ်နှင့် ရစူလ်တမန်တော်အား ဆန့်ကျင်ဘက်ပြုမူပါက ထိုသူ့အတွက် ငရဲဂျဟန္နမ်၏မီးရှိပေသည်။ ထိုမီးထဲတွင် သူသည် ထာဝရတည်နေရမည်။ (اللَّهَ وَرَسُولَهُ فَأَنَّ لَهُ نَارَ جَهَنَّمَ خَالِدًا فِيهَا) 9:63; 72:23
- သူတို့၏နှလုံးသားများပေါ်တွင် (ကုရ်အာန်ကျမ်းမြတ်ကို) နားလည်ခြင်းမှ ကာကွယ်တားဆီးသော အကာအကွယ်များကို ငါအရှင်မြတ်က ထားတော်မူခဲ့သည်။ သူတို့၏နားများတွင်လည်း လေးလံခြင်းရှိ၏။ (عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 17:46; 18:57
- မည်သည့်မြို့ရွာသို့ သတိပေးနှိုးဆော်သူ တစ်ဦးဦး ရောက်ရှိလာခဲ့သည်ဖြစ်စေ ထိုမြို့ရွာ၏ ချမ်းသာကြွယ်ဝသူများက ပြောဆိုခဲ့ကြသည်- ကျွန်ုပ်တို့။ (فِي قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَا إِنَّا) 34:34; 43:23
- သူတို့က ပြောဆိုကြသည်- ကျွန်ုပ်တို့အတွက် သင်၏အရှင်သခင်ထံ ဆုတောင်းပေးပါ။ အရှင်မြတ်က ယင်းနွားမသည် မည်သို့မျိုးဖြစ်သည်ကို ကျွန်ုပ်တို့အား ရှင်းလင်းဖော်ပြတော်မူပါစေ။ (قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ) 2:68; 2:70
- သူတို့သည် အလ္လာဟ်အရှင်မြတ်ဟု ဆိုကြလတ္တံ့။ (အို-နဗီတမန်တော်) အမိန့်တော်ရှိလော့- အလ္လာဟ်အရှင်မြတ်အား ချီးမွမ်းခြင်းသည် အရှင်မြတ်အတွက်သာ ဖြစ်၏။ သို့ရာတွင် သူတို့အများစုသည်။ (لَيَقُولُنَّ اللَّهُ قُلِ الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا) 29:63; 31:25
- သူ၏လူမျိုးသားတို့၏ အဖြေမှာ သူတို့က ဤသူတို့ကို မောင်းထုတ်ကြလော့ဟု ဆိုခြင်းသာဖြစ်ခဲ့၏။ (وَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَن قَالُوا أَخْرِجُوهُم) 7:82; 27:56
- ယင်းဥယျာဉ်တော်များအောက်တွင် မြစ်ချောင်းများ စီးဆင်းနေသည်။ ထိုဥယျာဉ်တော်များတွင် သူတို့သည် ထာဝရအမြဲတည်နေကြရမည်။ ယင်းသည် ကြီးကျယ်သော အောင်မြင်မှုကြီးပင် ဖြစ်ပေသည်။ (تَحْتَهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ذَلِكَ الْفَوْزُ الْعَظِيمُ) 9:100; 64:9
- ထိုသူတို့သည် မိမိတို့၏အရှင်သခင်၏ တရားလမ်းမှန်ပေါ်တွင်ရှိကြ၏။ ထိုသူတို့သည်သာ အောင်မြင်သောသူများဖြစ်ကြ၏။ (أُولَئِكَ عَلَى هُدًى مِّن رَّبِّهِمْ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ) 2:5; 31:5
- အကြင်သူ့အား ဂုဏ်သိက္ခာဖျက်ဆီးသော ပြစ်ဒဏ်သည် ရောက်ရှိလာ၏။ ထို့ပြင် ယင်းသူ့အပေါ်၌လည်း အမြဲတည်သော ပြစ်ဒဏ်သည် ကျရောက်၏။ (مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ) 11:39; 39:40
- သင်တို့သည် မြေကြီးပေါ်တွင် လှည့်လည်သွားလာ၍ မှားယွင်းစွာ ငြင်းပယ်ခဲ့သူတို့၏ အဆုံးစီရင်ခြင်းသည် မည်သို့ဖြစ်ခဲ့သည်ကို ကြည့်ရှုကြလော့။ (فَسِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ) 3:137; 16:36
- သူတို့သည် မိမိတို့၏လက်များက ရှေ့သို့ပေးပို့ထားသောအရာများကြောင့် ယင်းကို ဘယ်သောအခါမျှ အလိုမရှိကြ။ အလ္လာဟ်အရှင်မြတ်သည် မတရားသူများကို အကြွင်းမဲ့ သိတော်မူ၏။ (يَتَمَنَّوْهُ أَبَدًا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ) 2:95; 62:7
- အရှင်မြတ်သည် မိမိ၏လမ်းတော်မှ လမ်းလွှဲသွားသူကို အကြွင်းမဲ့သိတော်မူ၏။ အရှင်မြတ်သည် (ခပ်သိမ်းသောအရာတို့ကို) အကြွင်းမဲ့သိတော်မူ၏။ (هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 53:30; 68:7
- အလ္လာဟ်အရှင်မြတ်သည် ကျွန်ုပ်၏အရှင်သခင်နှင့် သင်တို့၏အရှင်သခင်ဖြစ်တော်မူ၏။ သို့ဖြစ်ပေရာ အရှင်မြတ်ကိုသာ သင်တို့ကိုးကွယ်ကြလော့။ ယင်းသည် ဖြောင့်မတ်သောလမ်းတော်ပင်ဖြစ်၏။ (إِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هَذَا صِرَاطٌ مُّسْتَقِيمٌ) 3:51; 19:36
- အရှင်မြတ်သည် လူသားတို့အပေါ် ကျေးဇူးတော်ရှင်ပင်ဖြစ်၏။ သို့ရာတွင် သူတို့အများစုသည် ကျေးဇူးတရားကို သိရှိတတ်ကြသည်မဟုတ်။ (لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ) 10:60; 27:73
- မိုးကောင်းကင်များ၊ မြေကြီးနှင့် ယင်းတို့အကြားရှိအရာအားလုံးကို အမှန်တရားနှင့် သတ်မှတ်ထားသောအချိန်အတိုင်းသာ (ငါအရှင်မြတ်က ဖန်ဆင်းတော်မူ၏)။ (السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ وَأَجَلٍ مُّسَمًّى) 30:8; 46:3
- သို့ဖြစ်လျှင် အသင်သည် သူတို့ကိုလွှတ်၍ထားလိုက်ပါ။ သူတို့သည် အချည်းနှီးဖြစ်သောအရာများတွင် နစ်မြုပ်၍ ကစားမြူးထူးနေကြစေကုန်။ သူတို့အား ကတိပေးထားသော သူတို့၏နေ့နှင့် တွေ့ဆုံကြသည့်အချိန်အထိ။ (فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتَّى يُلَاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ) 43:83; 70:42
- သူတို့သည် ယုံကြည်သူများနှင့် တွေ့ဆုံကြသောအခါ ကျွန်ုပ်တို့ ယုံကြည်ကြပါပြီဟု ဆိုကြ၏။ တစ်ဦးတည်း သီးသန့်ဖြစ်သွားသောအခါမူကား။ (وَإِذَا لَقُوا الَّذِينَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَوْا) 2:14; 2:76
- သူတို့သည် တောရာကျမ်းနှင့် အိန်ဂျီလ်ကျမ်း၊ ထို့ပြင် မိမိတို့၏အရှင်သခင်ထံမှ ချပေးသနားတော်မူခဲ့သောအရာတို့ကို စောင့်ထိန်းကျင့်သုံးကြ၏။ (أَقَامُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ) 5:66; 5:68
- အရှင်မြတ်သည် သူတို့ရှေ့တွင်ရှိသောအရာနှင့် သူတို့နောက်တွင်ရှိသောအရာကို သိရှိတော်မူ၏။ သူတို့မူကား ယင်းကို အသိပညာဖြင့် ဝန်းရံခြင်းငှာ မစွမ်းနိုင်ကြ။ (يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ) 2:255; 20:110
- အရှင်မြတ်သည် မိုးကောင်းကင်များနှင့် မြေကြီးကို ခြောက်ရက်အတွင်း ဖန်ဆင်းတော်မူသော အရှင်ဖြစ်၏။ (وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ) 11:7; 57:4
- စင်စစ် ထိုအရာတွင် သင်တို့အတွက် သက်သေလက္ခဏာတစ်ခု ရှိပေ၏။ အကယ်၍ သင်တို့သည် ယုံကြည်သူများဖြစ်ပါက။ (إِنَّ فِي ذَلِكَ لَآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ) 2:248; 3:49
- လူသားများထံ လမ်းညွှန်တော်မြတ် ရောက်ရှိလာသောအခါ သူတို့အား ယုံကြည်ခြင်းမှ အဘယ်အရာက တားဆီးနိုင်ခဲ့သနည်း။ (وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَى) 17:94; 18:55
- သူတို့သည် အလ္လာဟ်အရှင်မြတ်၏လမ်းတော်မှ လမ်းလွှဲစေရန် အရှင်မြတ်အား ပူးတွဲဖက်များ ပြုလုပ်ခဲ့ကြ၏။ (အို-နဗီတမန်တော်) အမိန့်တော်ရှိလော့- သင်တို့သည် ခံစားစားသုံးကြလော့။ (وَجَعَلُوا لِلَّهِ أَندَادًا لِّيُضِلُّوا عَن سَبِيلِهِ قُلْ تَمَتَّعُوا) 14:30; 39:8
- သူတို့ထံ သူတို့အထဲမှ သတိပေးနှိုးဆော်သူတစ်ဦး ရောက်ရှိလာသည်ကို အံ့အားသင့်ခဲ့ကြ၏။ ငြင်းပယ်သောသူများက ပြောဆိုခဲ့ကြသည်- ဤသူသည်။ (وَعَجِبُوا أَن جَاءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ الْكَافِرُونَ هَذَا) 38:4; 50:2
- စင်စစ် သင်၏အရှင်သခင်သည် မိမိ၏လမ်းတော်မှ လမ်းလွဲသွားသူကို အကြွင်းမဲ့သိတော်မူ၏။ (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ) 53:30; 68:7
- မိမိ၏ဥစ္စာကို လူအများအား ကြွားဝါပြသရန် သုံးစွဲ၍ အလ္လာဟ်အရှင်မြတ်ကို မယုံကြည်သောသူကဲ့သို့။ (كَالَّذِي يُنفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ) 2:264; 4:38
- သင်တို့အား ငါအရှင်မြတ် ပေးအပ်ထားသော အရာများမှ ယင်းနေ့မရောက်မီ လှူဒါန်းကြလော့။ (أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ) 2:254; 63:10
- အရှင်မြတ်သည် မိုးကောင်းကင်များနှင့် မြေကြီးပေါ်ရှိအရာအားလုံးကို သင်တို့အတွက် လက်အောက်ခံ ဖြစ်စေတော်မူ၏။ (سَخَّرَ لَكُم مَّا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 31:20; 45:13
- စင်စစ်အားဖြင့် ကျွန်ုပ်တို့သည် အသင်တို့ခေါ်တော်မူရာ၌ သံသယဝင်စရာအကြောင်းတရားရှိ၏။ (وَإِنَّنَا لَفِي شَكٍّ مِّمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ) 11:62; 14:9
- စင်စစ် သင်၏အရှင်သခင်သည် အလိုတော်ရှိသူအား စားနပ်ရိက္ခာကို ကျယ်ပြန့်စေတော်မူ၏။ ကျဉ်းမြောင်းစေလည်း စေတော်မူ၏။ စင်စစ် အရှင်မြတ်သည်။ (إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّهُ) 17:30; 34:36
- မိုးကောင်းကင်များနှင့် မြေကြီးနှင့် ယင်းတို့အကြားရှိအရာအားလုံး၏ အရှင်သခင်၊ အကယ်၍ သင်တို့သည် ယုံကြည်စိတ်ချသူများဖြစ်ပါက။ (رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِن كُنتُم مُّوقِنِينَ) 26:24; 44:7
- ကျွန်ုပ်တို့သည် အလ္လာဟ်အရှင်မြတ်ကို ယုံကြည်ပါသည်။ ထို့ပြင် ကျွန်ုပ်တို့ထံသို့ ချပေးသနားတော်မူသောအရာနှင့်၊ (ယခင်နဗီတမန်တော်များထံသို့) ချပေးသနားတော်မူသောအရာကိုလည်း ယုံကြည်ပါသည်။ (آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَى) 2:136; 3:199
- မတရားသူတို့ကို ကြောက်မက်ဖွယ်သော အော်ဟစ်သံကြီးက ဖမ်းဆီးအပ်နှံလိုက်၏။ ထိုအခါ သူတို့သည် မိမိတို့၏အိမ်များတွင် ဒူးထောက်လျက် သေကျေပျက်စီးခဲ့ကြရ၏။ (وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ) 11:67; 11:94
- မိန်းမတို့သည် မိမိတို့၏ကိုယ်အတွက် ပြုကြသောအရာ၌ သင်တို့အား အပြစ်မရှိချေ။ (فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنفُسِهِنَّ) 2:234; 2:240
- သင်၏အရှင်သခင်သည် မိမိ၏လမ်းတော်မှ လမ်းလွဲသွားသူကို အကြွင်းမဲ့သိတော်မူ၏။ အရှင်မြတ်သည်။ (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 53:30; 68:7
- အရှင်မြတ်၏အမိန့်တော်အရ ဝိညာဉ်တော် (ဝဟီမြတ်) ကို အရှင်မြတ်၏ကျွန်များအနက် အလိုတော်ရှိသူထံ ချပေးသနားတော်မူ၏။ (بِالرُّوحِ مِنْ أَمْرِهِ عَلَى مَن يَشَاءُ مِنْ عِبَادِهِ) 16:2; 40:15
- မာရ်ယမ်၏သား အီဆာအား ထင်ရှားသော သက်သေလက္ခဏာများကို ငါအရှင်မြတ်က ပေးအပ်ခဲ့၏။ ထို့ပြင် သန့်ရှင်းသောဝိညာဉ်တော်ဖြင့်လည်း အရှင်မြတ်က သူ့အား အားဖြည့်တော်မူခဲ့၏။ (وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ) 2:87; 2:253
- ရှင်ပြန်ထမြောက်သောနေ့တွင် သူတို့အကြား သဘောထားကွဲလွဲခဲ့ကြသောအရာကို စီရင်ဆုံးဖြတ်တော်မူမည်ဖြစ်၏။ (لَيَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ) 16:124; 22:69
- ငါအရှင်မြတ်သည် ယင်းမြို့၏ အထက်ပိုင်းကို အောက်ပိုင်းဖြစ်စေတော်မူခဲ့၏။ ထို့ပြင် ယင်းအပေါ်၌ မီးဖုတ်ထားသော ရွှံ့အုတ်ခဲများကို မိုးကဲ့သို့ ရွာသွန်းစေတော်မူခဲ့၏။ (جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ) 11:82; 15:74
- အသင်သည် သူတို့အား သတိပေးနှိုးဆော်စေကာမူ မဆော်စေကာမူ သူတို့အတွက် တူညီပါသည်။ သူတို့သည် ယုံကြည်ကြမည်မဟုတ်ပေ။ (سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ) 2:6; 36:10
- လူသားများကို ပယ်ထား၍ အကယ်၍ သင်တို့သည် မှန်ကန်သူများဖြစ်ပါက သေခြင်းကို ဆန္ဒပြုကြလော့။ (مِّن دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِن كُنتُمْ صَادِقِينَ) 2:94; 62:6
- အလ္လာဟ်အရှင်မြတ်ကို (ကိုးကွယ်ကြလော့)။ အရှင်မြတ်မှတစ်ပါး သင်တို့အား ဘုရားတစ်ဆူ မရှိချေ။ သို့ဖြစ်လျှင် သင်တို့သည် အရှင်မြတ်အား မကြောက်ရွံ့ကြသလော။ (اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 23:23; 23:32
- သူတို့အား ကျွန်ုပ်တို့ ကတိပြုထားသမျှကို အသင်အား တစ်စိတ်တစ်ဒေသ ပြသစေကာမူ၊ သို့မဟုတ် အသင်အား (ဤလောကမှ) သေစေတော်မူသည်ဖြစ်စေ၊ ငါအရှင်မြတ်ထံသို့သာ သူတို့ ပြန်လည်ရောက်ရှိကြမည်။ (وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا) 10:46; 40:77
- သူတို့က ပြောဆိုကြသည်- ကျွန်ုပ်တို့သေဆုံး၍ မြေမှုန့်နှင့် အရိုးများဖြစ်သွားသောအခါ ကျွန်ုပ်တို့သည် ထမြောက်ရှင်ပြန်ခြင်းကို ခံရကြမည်လော။ (قَالُوا أَإِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَبْعُوثُونَ) 23:82; 56:47
- စင်စစ် ကျေးဇူးတော်သည် အလ္လာဟ်အရှင်မြတ်၏ လက်တော်တွင် ရှိ၏။ အရှင်မြတ်သည် အလိုတော်ရှိသူအား ပေးသနားတော်မူ၏။ အလ္လာဟ်အရှင်မြတ်သည်။ (إِنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ) 3:73; 57:29
- သင်တို့သည် မမြင်ရသောအရာနှင့် မြင်ရသောအရာတို့ကို အကြွင်းမဲ့သိတော်မူသော အရှင်မြတ်ထံသို့ ပြန်လည်ရောက်ရှိကြရမည်။ ထိုအခါ အရှင်မြတ်သည် သင်တို့ပြုမူခဲ့သမျှကို သင်တို့အား သတင်းပေးတော်မူမည်။ (إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:105; 62:8
- အို ယုံကြည်သူတို့၊ အလ္လာဟ်အရှင်မြတ်၏ ကျေးဇူးတော်ကို သင်တို့အပေါ်၌ အောက်မေ့သတိရကြလော့။ ထိုအချိန်က။ (يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ) 5:11; 33:9
- အသင်မတိုင်မီကလည်း ငါအရှင်မြတ်သည် ဝဟီမြတ် ချပေးသနားတော်မူသော အမျိုးသားများကိုသာ ရစူလ်တမန်အဖြစ် စေလွှတ်တော်မူခဲ့ပြီ။ (وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِم) 12:109; 16:43
- အရှင်မြတ်သည် သူ၏အပြစ်များကို ဖြေလွှတ်တော်မူမည်ဖြစ်ပြီး သူ့အား အောက်မှမြစ်ချောင်းများ စီးဆင်းနေသော ဥယျာဉ်တော်များသို့ သွင်းတော်မူမည်။ (يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا) 64:9; 66:8
- အနာရောဂါရှိသောသူ သို့မဟုတ် ခရီးသွားနေသောသူအတွက် အခြားသောရက်များတွင် (အစားထိုး၍) စားသည်။ (مَّرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ) 2:184; 2:185
- သူတို့သည် ထင်မှတ်ချက်ကိုသာ လိုက်နာကြ၏။ သူတို့သည် မှန်းဆချက်ကိုသာ ပြုကြ၏။ (إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ) 6:116; 10:66
- အကြင်သူသည် အလ္လာဟ်အရှင်မြတ်နှင့် နောက်ဆုံးနေ့ကို မျှော်လင့်တောင့်တပါအံ့၊ ထိုသူ့အတွက် ကောင်းမြတ်သော နမူနာပုံပြင် ဖြစ်၏။ (أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ) 33:21; 60:6
- မိုးကောင်းကင်များ၊ မြေကြီးနှင့် ယင်းတို့အကြားရှိအရာအားလုံးကို အမှန်တရားဖြင့်မှတစ်ပါး ငါအရှင်မြတ် ဖန်ဆင်းတော်မမူခဲ့ပေ။ (وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ) 15:85; 46:3
- အသင်သည် မိမိ၏လက်ကို မိမိ၏အင်္ကျီအိတ်ထဲသို့ သွင်းလိုက်ပါ။ ထိုအခါ အနာရောဂါတစ်စုံတစ်ရာမရှိဘဲ ဖြူဖွေးတောက်ပစွာ ထွက်လာလိမ့်မည်။ (يَدَكَ فِي جَيْبِكَ تَخْرُجْ بَيْضَاءَ مِنْ غَيْرِ سُوءٍ) 27:12; 28:32
- အရှင်မြတ်သည် မိမိ၏ကရုဏာတော်ဖြင့် အလိုတော်ရှိသူကို ရွေးချယ်တော်မူ၏။ အလ္လာဟ်အရှင်မြတ်သည် အလွန်ကြီးကျယ်သော ကျေးဇူးတော်ရှင် ဖြစ်တော်မူ၏။ (يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 2:105; 3:74
- အလ္လာဟ်အရှင်မြတ်အား မိုးကောင်းကင်များနှင့် မြေကြီးတို့၏ အရှင်သခင် ဖြစ်တော်မူသည်ကို အသင်မသိသလော။ (أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ) 2:107; 5:40
- သင်တို့သည် မိမိတို့၏အတွက် ကောင်းမှုကုသိုလ် မည်သည်ကိုမဆို ရှေးသို့စေလွှတ်ထားခဲ့ငြားအံ့၊ ထိုကောင်းမှုကို အလ္လာဟ်အရှင်မြတ်၏အထံတော်၌ တွေ့ရှိကြလတ္တံ့။ (وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ) 2:110; 73:20
- အသင်သည် မည်သည့်နေရာမှ ထွက်ခွာသွားပါစေ၊ သင်၏မျက်နှာတော်ကို အိဗ်ရာဟီမ်ဝတ်ကျောင်းတော် (မက္ကာရှိ အလ္လာဟ်အရှင်မြတ်၏ ဟရာမ်ဖြစ်သော ဗလီတော်) ဘက်သို့ မျက်နှာမူလှည့်လိုက်ပါ။ (وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ) 2:149; 2:150
- သူတို့မတိုင်မီက သူတို့လည်း ရှိခဲ့ကြပြီ။ အသင်သည် အလ္လာဟ်အရှင်မြတ်၏ နိယာမတရားတော်အတွက် ပြောင်းလဲခြင်းကို လုံးဝမတွေ့ရှိရပေ။ (خَلَوْا مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا) 33:62; 48:23
- အကြင်အရှင်မြတ်အတွက် မိုးကောင်းကင်များနှင့် မြေကြီးပေါ်ရှိအရာအားလုံး ပိုင်ဆိုင်တော်မူ၏။ (الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 34:1; 42:53
- မိန်းမတစ်ဦးမျှ ကိုယ်ဝန်မဆောင်နိုင်၊ မဖွားမြင်နိုင်၊ အရှင်မြတ်၏အသိပညာတော်ဖြင့်မှတစ်ပါး။ (وَمَا تَحْمِلُ مِنْ أُنثَى وَلَا تَضَعُ إِلَّا بِعِلْمِهِ) 35:11; 41:47
- အရှင်မြတ်သည် ညဉ့်ကို (လွှမ်းမိုးစေတော်မူ၏)။ နေနှင့်လကိုလည်း လက်အောက်ခံဖြစ်စေတော်မူ၏။ တစ်ခုချင်းစီသည် သတ်မှတ်ထားသောအချိန်တိုင်အောင် စီးဆင်းနေကြ၏။ (اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُّسَمًّى) 35:13; 39:5
- ယင်းဥယျာဉ်တော်များအောက်မှ မြစ်ချောင်းများ စီးဆင်းနေ၏။ ထိုဥယျာဉ်တော်များတွင် သူတို့သည် ထာဝရတည်နေကြရမည်။ ယင်းသည်သာ ဆုလဒ်ဖြစ်ပေသည်။ (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ جَزَاءُ) 5:85; 20:76
- သူက ပြောဆိုခဲ့သည်- မဟုတ်ပါ၊ သင်တို့၏စိတ်နှလုံးသားများက သင်တို့အတွက် တစ်စုံတစ်ရာကို အလှဆင်ပေးခဲ့ကြပေသည်။ သို့ဖြစ်လျှင် သည်းခံခြင်းသည် ကောင်းမြတ်လှပေသည်။ (قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ) 12:18; 12:83
- မိုးကောင်းကင်များနှင့် မြေကြီးပေါ်ရှိအရာအားလုံးနှင့် အလ္လာဟ်အရှင်မြတ်။ (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَأَنَّ اللَّهَ) 5:97; 22:64
- သူတို့ထံ ရစူလ်တမန်တစ်ပါးပါး ရောက်ရှိလာခဲ့သည်ရှိသော် ထိုတမန်တော်အား သူတို့သည် ပြက်ရယ်ပြုစရာအဖြစ် ပြုလုပ်ခဲ့ကြသည်။ (وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 15:11; 36:30
- သူတို့က ပြောဆိုကြသည်- အို မူစာ၊ အသင်သည် ချပစ်မည်လော၊ သို့မဟုတ် ကျွန်ုပ်တို့သည် ချပစ်မည်လော။ (قَالُوا يَامُوسَى إِمَّا أَن تُلْقِيَ وَإِمَّا أَن نَّكُونَ) 7:115; 20:65
- အရှင်မြတ်သည် သင်တို့အား သေစေတော်မူ၏။ ထို့ပြင် သင်တို့အနက် အချို့သည် အသက်အရွယ်၏ အညံ့ဆုံးအခြေသို့ ပြန်လည်ရောက်ရှိစေခြင်းခံရ၏။ (ထိုသို့ပြုတော်မူသည်) မှာ။ (يَتَوَفَّاكُمْ وَمِنكُم مَّن يُرَدُّ إِلَى أَرْذَلِ الْعُمُرِ لِكَيْ) 16:70; 22:5
- သူတို့အတွက် မိမိတို့၏အရှင်သခင်ထံတွင် အောက်မှမြစ်ချောင်းများ စီးဆင်းနေသော ဥယျာဉ်တော်များရှိ၏။ ထိုဥယျာဉ်တော်များတွင် သူတို့သည် ထာဝရတည်နေကြရမည်။ (رَبِّهِمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:15; 3:136
- ငါအရှင်မြတ်သည် သူတို့၏နှလုံးသားများပေါ်တွင် (ကုရ်အာန်ကျမ်းမြတ်ကို) နားမလည်နိုင်ရန် အကာအကွယ်များကို ထားတော်မူခဲ့သည်။ ထို့ပြင် သူတို့၏နားများတွင်လည်း လေးလံခြင်းကို ထားတော်မူခဲ့သည်။ (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ) 17:46; 18:57
- အလ္လာဟ်အရှင်မြတ်၏ ကတိတော်သည် အမှန်တရားဖြစ်၏။ သို့ရာတွင် သူတို့အများစုသည် မသိကြပေ။ (إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ) 10:55; 28:13
- ယင်းအချက်သည် အကြောင်းရင်းမှာ သူတို့သည် အလ္လာဟ်အရှင်မြတ်နှင့် အရှင်မြတ်၏ ရစူလ်တမန်တော်အား ဆန့်ကျင်ဘက်ပြုခဲ့ကြသောကြောင့်ဖြစ်၏။ အကြင်သူသည် အလ္လာဟ်အရှင်မြတ်အား ဆန့်ကျင်ဘက်ပြုပါက။ (ذَلِكَ بِأَنَّهُمْ شَاقُّوا اللَّهَ وَرَسُولَهُ وَمَن يُشَاقِقِ اللَّهَ) 8:13; 59:4
- ထိုနေ့တွင် အရှင်မြတ်သည် သူတို့အား ခေါ်တော်မူ၍ ငါ၏ပူးတွဲဖက်များဟု သင်တို့ ထင်မှတ်ခဲ့ကြသော အရာများ အဘယ်မှာရှိကြသနည်းဟု မိန့်ဆိုတော်မူလတ္တံ့။ (وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تَزْعُمُونَ) 28:62; 28:74
- အလ္လာဟ်အရှင်မြတ်သည် မိုးကောင်းကင်များနှင့် မြေကြီးကို ဖန်ဆင်းတော်မူသော အရှင်ဖြစ်သည်ကို သူတို့မမြင်ကြသလော။ (أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ) 17:99; 46:33
- အကြင်အရှင်မြတ်သည် သင်တို့အား မြေမှုန့်မှ၎င်း၊ ထို့နောက် သုက်ရည်မှ၎င်း၊ ထို့နောက်။ (بِالَّذِي خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ) 18:37; 40:67
- သူတို့သည် ကျွန်ုပ်တို့၏အရှင်သခင်၊ အရှင်မြတ်သည် ကျွန်ုပ်တို့ထံသို့ ရစူလ်တမန်တစ်ပါး အဘယ်ကြောင့် မစေလွှတ်ခဲ့သနည်း၊ သို့ဖြစ်လျှင် ကျွန်ုပ်တို့သည် အရှင်မြတ်၏ သက်သေလက္ခဏာများကို လိုက်နာကြမည်ပေါ့ဟု ဆိုကြလတ္တံ့။ (لَقَالُوا رَبَّنَا لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ) 20:134; 28:47
- ထို့နောက် သူတို့သည် မိမိတို့၏အရှင်သခင်ထံသို့ ပြန်လည်ရောက်ရှိကြမည်။ ထိုအခါ အရှင်မြတ်သည် သူတို့ပြုမူခဲ့သမျှကို သတင်းပေးတော်မူမည်။ (ثُمَّ إِلَى رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا يَعْمَلُونَ) 6:108; 39:7
- ထိုအကြောင်းအရာနှင့် ပတ်သက်၍ သူတို့အား အသိပညာမရှိချေ။ သူတို့သည် ထင်မှတ်ချက်ကိုသာ လိုက်နာကြ၏။ (مَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا) 43:20; 45:24
- စင်စစ်အားဖြင့် ကျွန်ုပ်တို့သည် ကျွန်ုပ်တို့၏ဘိုးဘေးများအား ဘာသာတရားတစ်ခုအပေါ်၌ တွေ့ရှိခဲ့ရပြီး ကျွန်ုပ်တို့သည်လည်း သူတို့၏ခြေရာကို လိုက်နာဆည်းပူးသူများဖြစ်ကြ၏။ (إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِم) 43:22; 43:23
- အကြင်သူတို့အား ကျမ်းမြတ် ပေးအပ်ခြင်းခံရပြီ၊ သူတို့ထံသို့ (အမှန်တရား) ရောက်ရှိလာပြီးမှသာ (ကွဲပြားခဲ့ကြသည်)။ (الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَهُمُ) 3:19; 98:4
- အိဗ်ရာဟီမ်က ပြောဆိုခဲ့သောအခါ- အို ကျွန်ုပ်၏အရှင်သခင်၊ ဤအရပ်ဌာနကို လုံခြုံသောအရပ်ဖြစ်စေတော်မူပါ။ (وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَذَا بَلَدًا آمِنًا) 2:126; 14:35
- အရှင်မြတ်သည် သင်တို့အတွက် နားများ၊ မျက်စိများနှင့် နှလုံးသားများကို ဖန်ဆင်းပေးတော်မူ၏။ သင်တို့သည် ကျေးဇူးတရားကို အနည်းငယ်မျှသာ သိရှိကြ၏။ (وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَّا تَشْكُرُونَ) 32:9; 67:23
- အကြင်သူတို့သည် မိမိတို့ထံသို့ ရောက်ရှိလာသော အခွင့်အာဏာတစ်စုံတစ်ရာမရှိဘဲ အလ္လာဟ်အရှင်မြတ်၏ သက်သေလက္ခဏာများနှင့် ပတ်သက်၍ အငြင်းအခုံပြုကြ၏။ (الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ) 40:35; 40:56
- သို့ဖြစ်ပေရာ သင်တို့သည် အိဗ်ရာဟီမ်၏ စစ်မှန်ဖြောင့်မတ်သော ဘာသာတရားကို လိုက်နာကြလော့။ ထို့ပြင် သူသည် အလ္လာဟ်အရှင်မြတ်အား ပူးတွဲဖက်ထားသူများထဲမှ မဟုတ်ခဲ့ပေ။ (فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ) 3:95; 16:123
- ဖိရ်အောင်န်၏အဆွေအမျိုးထဲမှ သင်တို့အား ငါအရှင်မြတ် ကယ်ဆယ်တော်မူခဲ့သောအချိန်ကို (အောက်မေ့ကြလော့)။ သူတို့သည် သင်တို့အား ဆိုးရွားလှသော ပြစ်ဒဏ်ကို ပေးအပ်နေကြ၏။ (وَإِذْ أَنجَيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ) 7:141; 14:6
- ယင်းသည် ဖြောင့်မတ်သောဘာသာတရားဖြစ်၏။ သို့ရာတွင် လူအများစုသည် မသိကြပေ။ (ذَلِكَ الدِّينُ الْقَيِّمُ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ) 12:40; 30:30
- အလ္လာဟ်အရှင်မြတ်သည် သင်တို့အတွက် မိုးကောင်းကင်ပေါ်ရှိအရာတို့ကို လက်အောက်ခံဖြစ်စေတော်မူသည်ကို အသင်မမြင်သလော။ (أَلَمْ تَرَ أَنَّ اللَّهَ سَخَّرَ لَكُم مَّا فِي) 22:65; 31:20
- ငြင်းပယ်သောသူများက ဤအရာသည် ထင်ရှားသော မှော်အတတ်မှတစ်ပါး အခြားမဟုတ်ဟု ဆိုကြလတ္တံ့။ (لَقَالَ الَّذِينَ كَفَرُوا إِنْ هَذَا إِلَّا سِحْرٌ مُّبِينٌ) 6:7; 11:7
- သူတို့ထံ၌ ငါအရှင်မြတ်၏ ထင်ရှားသော သက်သေလက္ခဏာများကို ရွတ်ဖတ်ပြသသောအခါ ငြင်းပယ်သောသူများက ပြောဆိုကြ၏။ (وَإِذَا تُتْلَى عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالَ الَّذِينَ كَفَرُوا) 19:73; 46:7
- အာဒန်ဥယျာဉ်တော်များ၊ ယင်းတို့အောက်မှ မြစ်ချောင်းများ စီးဆင်းနေ၏။ ထိုဥယျာဉ်တော်များတွင် သူတို့သည် ထာဝရတည်နေကြရမည်။ (جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 20:76; 98:8
- အလိုတော်ရှိသောအရာကို (ဖန်ဆင်းတော်မူ၏)။ စင်စစ် အလ္လာဟ်အရှင်မြတ်သည် ခပ်သိမ်းသောအရာတို့အပေါ် တန်ခိုးတော်ရှင်ဖြစ်တော်မူ၏။ (مَا يَشَاءُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ) 24:45; 35:1
- အရှင်မြတ်သည် သင်တို့၏အပြစ်များကို လွှတ်တော်မူရန်နှင့် သင်တို့အား သတ်မှတ်ထားသောအချိန်တိုင်အောင် ရွှေ့ဆိုင်းတော်မူရန်။ (لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَى أَجَلٍ مُّسَمًّى) 14:10; 71:4
- သင်တို့သည် ကျွန်ုပ်တို့၏ဘိုးဘေးများ ကိုးကွယ်ခဲ့ကြသောအရာမှ ကျွန်ုပ်တို့အား လှည့်ဖျားတားဆီးလိုကြသလော။ (تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ آبَاؤُنَا) 14:10; 34:43
- သင်၏အရှင်သခင်က ကောင်းကင်တမန်များအား ပြောဆိုတော်မူသောအခါ- စင်စစ်ငါအရှင်မြတ်သည် ရွှံ့စေးမှ လူသားကို ဖန်ဆင်းတော်မူမည်။ (وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِّن) 15:28; 38:71
- အရှင်မြတ်သည် မိမိ၏ကရုဏာတော်မတိုင်မီ သတင်းကောင်းအဖြစ် လေတိုက်ခတ်မှုကို စေလွှတ်တော်မူသောအရှင် ဖြစ်၏။ (وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ) 7:57; 25:48
- (အို-နဗီတမန်တော်) အမိန့်တော်ရှိလော့- သင်တို့သည် မြေကြီးပေါ်တွင် လှည့်လည်သွားလာ၍ (ယခင်လူများ၏) အဆုံးစီရင်ခြင်းသည် မည်သို့ဖြစ်ခဲ့သည်ကို ကြည့်ရှုကြလော့။ (قُلْ سِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 27:69; 30:42
- မိုးကောင်းကင်များနှင့် မြေကြီးကို ဖန်ဆင်းတော်မူခြင်း၊ ညဉ့်နှင့်နေ့တို့၏ အလှည့်အပြောင်းအစားထိုးခြင်းတို့တွင် (သက်သေလက္ခဏာများရှိ၏)။ (إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ) 2:164; 3:190
- အကြင်သူသည် အလ္လာဟ်အရှင်မြတ်အား ကောင်းမွန်သော ချေးငွေကို ချေးငှားလိုက်ပါလိမ့်၊ ထိုအခါ အရှင်မြတ်က ယင်းကို အဆပေါင်းများစွာ တိုးပွားစေတော်မူမည်။ (مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ) 2:245; 57:11
- သို့ဖြစ်လျှင် အသင်သည် သူတို့အကြား အလ္လာဟ်အရှင်မြတ် ချပေးသနားတော်မူသည့်အတိုင်း တရားစီရင်ဆုံးဖြတ်တော်မူပါ။ သူတို့၏ စိတ်ဆန္ဒများကိုလည်း မလိုက်ပါနှင့်။ (فَاحْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ) 5:48; 5:49
- သူတို့သည် ကောင်းကင်တမန်များ သူတို့ထံသို့ ရောက်ရှိလာခြင်း၊ သို့မဟုတ် သင်၏အရှင်သခင်၏ (ပြစ်ဒဏ်တော်) ရောက်ရှိလာခြင်းကိုသာ စောင့်မျှော်နေကြသလော။ (هَلْ يَنظُرُونَ إِلَّا أَن تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ) 6:158; 16:33
- စင်စစ် အကြင်သူတို့သည် အလ္လာဟ်အရှင်မြတ်အပေါ် မဟုတ်မမှန်ကို စပ်ဆိုကြ၏။ ထိုသူတို့သည် အောင်မြင်ကြမည်မဟုတ်ပေ။ (إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ) 10:69; 16:116
- ဖိရ်အောင်န်၏အဆွေအမျိုးနှင့် သူတို့မတိုင်မီက လူများ၏ ကျင့်သုံးမှုကဲ့သို့ပင်၊ သူတို့သည် ငါအရှင်မြတ်၏ သက်သေလက္ခဏာများကို ငြင်းပယ်ခဲ့ကြ၏။ (كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا بِآيَاتِنَا) 3:11; 8:54
- ယုံကြည်ပြီး ကောင်းမြတ်သောအကျင့်များကို ကျင့်ကြံပြုမူသောသူတို့အတွက် ဆုလဒ်ရှိကြောင်း ဝမ်းမြောက်စရာသတင်းကို ပေးတော်မူ၏။ (وَيُبَشِّرُ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّالِحَاتِ أَنَّ لَهُمْ أَجْرًا) 17:9; 18:2
- အလ္လာဟ်အရှင်မြတ်သည် မိမိ၏ကျွန်များအနက် အလိုတော်ရှိသူအား စားနပ်ရိက္ခာကို ကျယ်ပြန့်စေတော်မူ၏။ ကျဉ်းမြောင်းစေလည်း စေတော်မူ၏။ (اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ) 28:82; 29:62
- သင်တို့သည် မမြင်ရသောအရာနှင့် မြင်ရသောအရာတို့ကို အကြွင်းမဲ့သိတော်မူသော အရှင်မြတ်ထံသို့ ပြန်လည်ရောက်ရှိကြရမည်။ ထိုအခါ အရှင်မြတ်သည် သင်တို့ပြုမူခဲ့သမျှကို သင်တို့အား သတင်းပေးတော်မူမည်။ (وَسَتُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ) 9:105; 62:8
- သွေးသားဆက်နွယ်သူတို့သည် အလ္လာဟ်အရှင်မြတ်၏ ကျမ်းတော်မြတ်တွင် အချင်းချင်း ပိုမိုနီးစပ်ကြ၏။ (وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ) 8:75; 33:6
cmds - Commands, Exhortations, Prohibitions, Instructions
- fard / wajib (فرض / واجب) — မဖြစ်မနေပြုရမည် (ပြုရမည်; ချန်လှပ်ပါက အပြစ်ဖြစ်)
- mustahabb / mandub (مستحب / مندوب) — အကြံပြုထားသော (ပြုလျှင် ကောင်းမှုရှိ၊ မပြုလျှင် အပြစ်မရှိ)
- mubah (مباح) — ကြားနေ / ခွင့်ပြုထားသော (ကောင်းမှုရော အပြစ်ပါ မရှိ)
- makruh (مكروه) — မနှစ်သက်အပ် (မအားပေးထားသော်လည်း ပြုလျှင် အပြစ်မရှိ)
- haram (حرام) — တားမြစ်ထားသော (ပြုလျှင် အပြစ်ဖြစ်)
- halal (حلال, ခွင့်ပြု / ဥပဒေအရ ခွင့်ပြု) — mubah နှင့် mustahabb နှစ်မျိုးလုံး ပါဝင် — တားမြစ်ထားခြင်း မဟုတ်သော အရာအားလုံး
- အလ္လာဟ်အရှင်မြတ်ကိုသာ ကိုးကွယ်ပြီး အရှင်၏ အကူအညီ/စောင့်ရှောက်မှုကို တောင်းခံပါ။ 1:5
- အလ္လာဟ်အရှင်မြတ်ကိုသာ ကိုးကွယ်ပါ။ 2:21
- အလ္လာဟ်အရှင်မြတ်နှင့် မည်သူ့ကိုမျှ တွဲဖက်မထားပါနှင့်။ 2:22
- အလ္လာဟ်အရှင်မြတ်သည် ခွင့်လွှတ်တော်မူသောအရှင် (နောင်တကို လက်ခံတော်မူသောအရှင်) ဖြစ်သည်၊ အရှင်သည် အာဒမ် (အလိုင်းဟိစ်ဆလာမ်) ၏ နောင်တကို လက်ခံတော်မူခဲ့သည်။ 2:37
- အမှန်တရားကို မမှန်တရားနှင့် ရောနှောခြင်းမပြုပါနှင့်၊ ထို့ပြင် အမှန်တရားကို ဖုံးကွယ်ခြင်းမပြုပါနှင့်။ 2:42
- ဆွလာသ် (နေ့စဉ်ဝတ်ပြုဆုတောင်း) ကို ဆောက်တည်ပြီး ဇကာသ် (အလှူဒါန) ကို ပေးအပ်ပါ။ 2:43
- မိမိကိုယ်တိုင် ကျင့်သုံးပြီးမှသာ အခြားသူများကို ကောင်းမှုကုသိုလ်ပြုရန် ညွှန်ကြားပါ။ 2:44
- မိမိ၏ ကိစ္စအရပ်ရပ်၌ အလ္လာဟ်အရှင်မြတ်၏ အကူအညီကို တောင်းခံပါ။ 2:45
- ဖောက်ပြန်ခြင်းတွင် မပါဝင်စေရန် သို့မဟုတ် ဖြန့်ကျက်ခြင်းမပြုရန်။ 2:60
- လူများကို ဝတ်ပြုကျောင်းများသို့ သွားရောက်ခြင်းမှ တားဆီးခြင်းမပြုပါနှင့်။ 2:114
- ဗလီ၏ မြင့်မြတ်မှုကို ရိုသေပါ။ သင်တို့၏ ဆုတောင်းရာနေရာများကို သန့်ရှင်းစင်ကြယ်အောင် ထားရှိပါ။ 2:125
- အလ္လာဟ်အရှင်မြတ်ကို (ဆုတောင်းခြင်း၊ ဂုဏ်တော်ဘွဲ့များ ရွတ်ဆိုခြင်း စသည်ဖြင့်) အောက်မေ့သတိရပါ၊ အရှင်သည်လည်း သင်တို့ကို အောက်မေ့သတိရတော်မူမည်၊ ထို့ပြင် အရှင်အား ကျေးဇူးတင်ကြပါ။ 2:152
- ခက်ခဲသော အခြေအနေများတွင် စိတ်ရှည်သည်းခံမှုကို ကျင့်သုံးပါ။ 2:153
- ရှိုင်သွန် (စာတန်) ၏ ခြေရာကို မလိုက်ပါနှင့်၊ သူသည် ထင်ရှားသော ရန်သူ ဖြစ်သည်။ 2:168
- မည်သူ့ကိုမျှ မျက်စိမှိတ်၍ မလိုက်ပါနှင့်။ 2:170
- ယုံကြည်စိတ်ချရသော တာဝန်ဝတ္တရားအားလုံးကို ထိန်းသိမ်းပြီး ကျေပွန်အောင်ဆောင်ရွက်ပါ။ သင်တို့၏ ဘာသာရေးတာဝန်များကို ရိုးသားစွာ ထမ်းဆောင်ပါ။ သင်တို့၏ ကျိန်ဆိုမှုများနှင့် ကတိသစ္စာများကို ကျေပွန်အောင်ဆောင်ရွက်ပါ။ ကတိများ၊ အထူးသဖြင့် အလ္လာဟ်အရှင်မြတ်အား ပြုထားသော ကတိများကို စောင့်သိပါ။ လိုအပ်နေသူများကို ကူညီပံ့ပိုးပြီး ခက်ခဲမှုများကို သက်သာစေပါ။ ဘုရားရှင်၏ မျက်နှာသာတော် ဆုံးရှုံးစေသော အပြစ်များကို ကျူးလွန်ခြင်းမှ ရှောင်ကြဉ်ပါ။ မာနကြီးခြင်းသည် သင်တို့ကို မတရားမှုဆီသို့ မပို့ဆောင်ပါစေနှင့်။ 2:177
- ကိဆွတ်စ် (ပြစ်ဒဏ်ပေးရာတွင် တန်းတူညီမျှမှု ဥပဒေ) တွင် သင်တို့အတွက် အသက် (အသက်ရှင်ရေး အခွင့်အလမ်း) ရှိသည်။ 2:179
- ရမဿွာန်လ၌ ဥပုသ်စောင့်ပါ။ အလ္လာဟ်အရှင်မြတ်အား ကြောက်ရွံ့သော သူများ (မုတ္တကီများ) ဖြစ်လာရန် သတ်မှတ်ထားသော ဥပုသ်ကို စောင့်ထိန်းပါ။ 2:183
- ကုရ်အာန်ကျမ်းတော်မြတ်ကို လမ်းညွှန်မှု၏ အဆုံးစွန်သော အရင်းအမြစ်အဖြစ် ရိုသေပါ။ 2:185
- အချင်းချင်း၏ ဥစ္စာပစ္စည်းကို မတရားစွာ မစားသုံးပါနှင့်၊ ထို့ပြင် တရားသူကြီးများထံ (သင်တို့၏ အမှုများကို မတင်ပြမီ) လာဘ်စားခြင်း မပြုပါနှင့်။ 2:188
- စကားဖြင့်ဖြစ်စေ၊ အပြုအမူဖြင့်ဖြစ်စေ အခြားသူများကို ညှဉ်းပန်းနှိပ်စက်ခြင်းမပြုပါနှင့်။ ကျူးကျော်သူအဖြစ် မည်သည့်အခါမျှ စစ်မတိုက်ပါနှင့်၊ ကာကွယ်ရန်အတွက်သာ တိုက်ပါ။ 2:190
- မိဘမဲ့များကို ကာကွယ်စောင့်ရှောက်ပါ။ မိဘမဲ့များ၏ ဥစ္စာပစ္စည်းတွင် ရိုးသားစွာ ဆောင်ရွက်ပြီး ၎င်းတို့၏ ဥစ္စာပစ္စည်းကို သိမ်းပိုက်ခြင်းမပြုပါနှင့်။ 2:220
- နောင်တရပြီး အလ္လာဟ်အရှင်မြတ်၏ ခွင့်လွှတ်ခြင်းကို တောင်းခံပါ။ ဓမ္မတာလာနေစဉ် လိင်ဆက်ဆံခြင်းမပြုပါနှင့်။ (ရုပ်ပိုင်းဆိုင်ရာရော ဝိညာဉ်ရေးရာပါ) သန့်ရှင်းစင်ကြယ်မှုကို ထိန်းသိမ်းပါ။ 2:222
- မိမိ၏ မိသားစုအပေါ် တာဝန်ဝတ္တရားများကို ကျေပွန်အောင်ဆောင်ရွက်ပါ။ 2:233
- ခေါင်းဆောင်များကို ၎င်းတို့၏ အရည်အချင်းပေါ်တွင် အခြေခံ၍ ရွေးချယ်ပါ။ 2:247
- ဘာသာရေးတွင် အတင်းအကြပ် မပြုပါနှင့်။ 2:256
- ဥစ္စာပစ္စည်းကို ကုသိုလ်ဖြစ်စေရန် သုံးစွဲပါ။ ဥစ္စာပစ္စည်းရော အချိန်ပါ ကုသိုလ်ဖြစ်အောင် ပေးကမ်းပါ။ 2:261
- မိမိ၏ ရက်ရောမှုကို ဝါကြွားခြင်းဖြင့် ကုသိုလ်ဖြစ်မှုကို ပျက်စီးမစေပါနှင့်။ 2:264
- ရှိုင်သွန် (စာတန်) သည် သင်တို့အား ဆင်းရဲမွဲတေမှုဖြင့် ခြိမ်းခြောက်ပြီး ဖာဟ်ရှာအ် (မကောင်းမှုများ၊ တရားမဝင် လိင်ဆက်ဆံမှု၊ အပြစ်များ) ကို ကျူးလွန်ရန် အမိန့်ပေးသည်။ 2:268
- ဆင်းရဲနွမ်းပါးသူများကို ရှာဖွေပြီး ၎င်းတို့ကို ကူညီပါ။ 2:273
- အတိုးစားခြင်း သို့မဟုတ် အကျိုးအမြတ်တိုးပွားခြင်းတွင် မပါဝင်ပါနှင့်။ အတိုးရှိသော ဥစ္စာပစ္စည်းကို မစားသုံးပါနှင့်။ ရစ်ဘာ (အတိုး) ကို မစားပါနှင့်။ 2:275
- မြီရှင်သည် ခက်ခဲသော အခြေအနေတွင် ရှိပါက ပြန်ဆပ်ရန် အချိန်ပိုပေးပါ။ 2:280
- စီးပွားရေး လွှဲပြောင်းမှုများတွင် မိမိ၏ စကားကို စောင့်သိပါ။ မိမိ၏ ငွေကြေးကိစ္စများတွင် ရိုးသားပါ။ မိမိ၏ တာဝန်ယူမှုအားလုံးတွင် ရိုးသားဖြောင့်မတ်စွာ ပြုမူပါ။ သတ်မှတ်ထားသော ကာလအတွက် ကြွေးမြီ စာချုပ်ချုပ်ဆိုသောအခါ ၎င်းကို ရေးမှတ်ထားပါ။ စီးပွားရေးစာချုပ် ချုပ်ဆိုသည့် အခါတိုင်း သက်သေများ ထားရှိပါ။ 2:282
- ယုံကြည်စိတ်ချရသော တာဝန်ဝတ္တရားအားလုံးကို ထိန်းသိမ်းပြီး ကျေပွန်အောင်ဆောင်ရွက်ပါ။ 2:283
- ကျမ်းတော်မြတ်များနှင့် နဗီတမန်တော်အားလုံးကို ယုံကြည်ပါ။ 2:285
- အလ္လာဟ်အရှင်မြတ်သည် မည်သူ့ကိုမျှ သူ၏ စွမ်းရည်ထက်ကျော်လွန်သော တာဝန်ကို မပေးအပ်ပါ။ ကောင်းမှုကုသိုလ်များအတွက် ဆုလာဘ်ရရှိပြီး မကောင်းမှုများအတွက် ပြစ်ဒဏ်ခံရမည်။ ဘုရားရှင်သည် လူတစ်ဦးကို သူ၏ စွမ်းရည်ထက် ကျော်လွန်၍ ဝန်မပေးပါ။ ကျွန်ုပ်တို့လည်း ထိုသို့ မပြုသင့်ပါ။ ခက်ခဲသောအချိန်၌ပင် အလ္လာဟ်အရှင်မြတ်၏ အစီအစဉ်တော်ကို ယုံကြည်စိတ်ချပါ။ 2:286
- မည်သူမဆို ကတိသစ္စာများကို ကျေပွန်အောင်ဆောင်ရွက်ပြီး အလ္လာဟ်အရှင်မြတ်အား ကြောက်ရွံ့ပါက၊ အလ္လာဟ်အရှင်မြတ်သည် အလ္လာဟ်အရှင်မြတ်အား ကြောက်ရွံ့သော သူများ (မုတ္တကီများ) ကို ချစ်တော်မူသည်။ 3:76
- စွမ်းဆောင်နိုင်ပါက ဟဂ်ျ (ဘုရားဖူးသွားခြင်း) ကို ဆောင်ရွက်ပါ။ 3:97
- ကွဲပြားခြင်းမပြုပါနှင့်။ 3:103
- ကောင်းမှုကုသိုလ်ကို ညွှန်ကြားပြီး မကောင်းမှုကို တားမြစ်ပါ။ သင်တို့၏ လူ့အဖွဲ့အစည်းတွင် ဖြောင့်မတ်ခြင်းကို အားပေးပါ။ အခြားသူများကို အလ္လာဟ်အရှင်မြတ်ကို အောက်မေ့သတိရရန် ဖိတ်ခေါ်ပါ။ 3:104
- ယုံကြည်သူများသည် အလ္လာဟ်အရှင်မြတ်ကိုသာ ယုံကြည်အားထားသင့်သည်။ 3:122
- ရစ်ဘာ (အတိုး) ကို မစားပါနှင့်။ 3:130
- ကရုဏာတော်ရရှိရန် အလ္လာဟ်အရှင်မြတ်နှင့် အရှင်၏ ရစူလ်တမန်တော်ကို နာခံပါ။ 3:132
- အလ္လာဟ်အရှင်မြတ်သည် (အလ္လာဟ်အရှင်မြတ်၏ လမ်းတော်တွင် ကုသိုလ်ဖြစ်စေသော အလှူဒါနများ စသည်ဖြင့်) ချမ်းသာသောအခါ၌လည်းကောင်း၊ ဆင်းရဲသောအခါ၌လည်းကောင်း သုံးစွဲကြသော သူများ၊ ဒေါသကို ထိန်းချုပ်ကြသော သူများနှင့် လူသားများကို ခွင့်လွှတ်ကြသော သူများကို ချစ်တော်မူသည်။ 3:134
- ဒေါသကို ထိန်းချုပ်ပါ။ မိမိ၏ ဒေါသကို ထိန်းချုပ်ပါ။ 3:134
- အခြားသူများ၏ အမှားများကို ခွင့်လွှတ်ပြီး သည်းခံပါ။ 3:135
- စကားပြောရာတွင် ရိုင်းစိုင်းခြင်းမပြုပါနှင့်။ သင်တို့နှင့် သဘောထားကွဲပြားသူများကို စိတ်ရှည်သည်းခံပါ။ 3:159
- အကယ်၍ အလ္လာဟ်အရှင်မြတ်သည် သင်တို့ကို ကူညီတော်မူပါက၊ မည်သူမျှ သင်တို့ကို အနိုင်ယူနိုင်မည်မဟုတ်။ သို့သော် အရှင်သည် သင်တို့ကို စွန့်ပစ်တော်မူပါက၊ အရှင်မှတစ်ပါး မည်သူသည် သင်တို့ကို ကူညီနိုင်မည်နည်း။ 3:160
- လူတိုင်း သေခြင်းကို မြည်းစမ်းရမည်။ ထို့ပြင် ရှင်ပြန်ထမြောက်ရာနေ့တွင်သာ သင်တို့၏ အကျိုးဆုလာဘ်ကို အပြည့်အစုံ ပေးအပ်ခြင်းခံရမည်။ 3:185
- သဘာဝတရား၏ အံ့ဖွယ်များနှင့် ဤစကြဝဠာ၏ ဖန်တီးမှုအကြောင်းကို နက်နက်ရှိုင်းရှိုင်း တွေးတောဆင်ခြင်ပါ။ ဘုရားရှင်သည် ဤစကြဝဠာကို အဓိပ္ပာယ်နှင့် ရည်ရွယ်ချက်ဖြင့် ဖန်တီးတော်မူခဲ့ကြောင်း သိမှတ်ပါ။ 3:191
- အမျိုးသားများနှင့် အမျိုးသမီးများသည် မိမိတို့၏ ကောင်းမှုကုသိုလ်များအတွက် တန်းတူညီမျှ ဆုလာဘ်ရရှိသည်။ 3:195
- မိမိတို့၏ အရှင်သခင် (ရဗ်ဗ်) ကို ကြောက်ရွံ့သောသူများအတွက် (ဂျန္နသ်သုခဘုံ၌) မြစ်များစီးဆင်းသော ဥယျာဉ်များရှိသည်။ ထိုတွင် ထာဝရ စံမြန်းရမည်။ ၎င်းသည် အလ္လာဟ်အရှင်မြတ်၏ ဧည့်ခံခြင်းတော်ဖြစ်သည်။ 3:198
- လုပ်ရပ်တိုင်းတွင် အလ္လာဟ်အရှင်မြတ်၏ ကျေနပ်ရောင့်ရဲတော်မူခြင်းကို အမြဲကြိုးပမ်းပါ။ 3:200
- မိမိတို့၏ အရှင်သခင် (ရဗ်ဗ်) အား ကြောက်ရွံ့ပြီး (ဆွေမျိုးသားချင်းများနှင့် ဆက်ဆံရေး) ကို မဖြတ်တောက်ပါနှင့်။ 4:1
- မိဘမဲ့များအား ၎င်းတို့၏ ဥစ္စာပစ္စည်းကို ပေးအပ်ပြီး (မိမိတို့၏ ဆိုးသော အရာများကို) ၎င်းတို့၏ (ကောင်းသော အရာများနှင့်) လဲလှယ်ခြင်းမပြုပါနှင့်။ ထို့ပြင် ၎င်းတို့၏ ဥစ္စာပစ္စည်းကို မိမိတို့၏ ဥစ္စာပစ္စည်းထဲသို့ ထည့်သွင်းစားသုံးခြင်းမပြုပါနှင့်။ 4:2
- သင်တို့ (လက်ထပ်သော) အမျိုးသမီးများအား ၎င်းတို့၏ မဟ်ရ် (လက်ထပ်ချိန်တွင် ခင်ပွန်းဖြစ်သူမှ ဇနီးဖြစ်သူအား ပေးအပ်ရမည့် လက်ထပ်ခ) ကို စေတနာဖြင့် ပေးအပ်ပါ။ 4:4
- မိဘမဲ့များ၏ အခွင့်အရေးများကို စောင့်ရှောက်ပါ။ 4:6
- ကွယ်လွန်သူ၏ ဥစ္စာပစ္စည်းကို ၎င်း၏ မိသားစုဝင်များကြားတွင် ဝေမျှခြင်းခံရမည်။ အမျိုးသမီးများသည် အမွေဆက်ခံခွင့်ရှိသည်။ 4:7
- မိဘမဲ့များ၏ ဥစ္စာပစ္စည်းကို မတရားစွာ မစားသုံးပါနှင့်။ 4:10
- အမွေဆက်ခံခြင်းဆိုင်ရာ အမိန့်တော်များကို လိုက်နာပါ။ 4:11
- အမျိုးသမီးများကို ၎င်းတို့၏ ဆန္ဒကိုဆန့်ကျင်၍ အမွေဆက်ခံခြင်းမပြုရ၊ ထို့ပြင် ၎င်းတို့အား ကြမ်းတမ်းစွာ မဆက်ဆံရ။ ၎င်းတို့ (ဇနီးများ) နှင့် လျောက်ပတ်စွာ အတူနေထိုင်ပါ။ အမျိုးသမီးများ၏ အခွင့်အရေးများကို ရိုသေပြီး စောင့်ရှောက်ပါ။ မိမိ၏ ဇနီးသည်ကို ကရုဏာတရားနှင့် စေတနာဖြင့် ဆက်ဆံပါ။ အမျိုးသမီးများအား ဂုဏ်သိက္ခာနှင့် တရားမျှတမှုဖြင့် ဆက်ဆံပါ။ 4:19
- သင်တို့နှင့် သွေးရင်းသားချင်း ဆွေမျိုးများကို လက်မထပ်ပါနှင့်။ 4:23
- အချင်းချင်း သတ်ဖြတ်ခြင်းမပြုပါနှင့်။ အမှန်မှာ အလ္လာဟ်အရှင်မြတ်သည် သင်တို့အပေါ် အလွန်ကရုဏာတော်ရှိသောအရှင် ဖြစ်သည်။ အချင်းချင်း၏ ဥစ္စာပစ္စည်းကို မတရားစွာ မစားသုံးပါနှင့်။ 4:29
- သင်တို့သည် တားမြစ်ထားသော ကြီးလေးသည့် အပြစ်များကို ရှောင်ကြဉ်ပါက၊ အလ္လာဟ်အရှင်မြတ်သည် သင်တို့၏ (အငယ်စား) အပြစ်များကို ဖျက်ပစ်တော်မူမည်ဖြစ်ပြီး သင်တို့ကို မြင့်မြတ်သော နေရာ (ဂျန္နသ်သုခဘုံ) သို့ ဝင်ရောက်စေတော်မူမည်။ 4:31
- အလ္လာဟ်အရှင်မြတ်သည် သင်တို့ထဲမှ အချို့ကို အချို့ထက် သာလွန်စေတော်မူခဲ့သော အရာများကို ဆန္ဒမပြုပါနှင့်။ ငြူစူခြင်းနှင့် မနာလိုခြင်းကို ရှောင်ကြဉ်ပါ။ 4:32
- အမျိုးသားများသည် အမျိုးသမီးများ၏ ထိန်းသိမ်းစောင့်ရှောက်သူများနှင့် ပြုစုပျိုးထောင်သူများဖြစ်သည်၊ အကြောင်းမှာ အလ္လာဟ်အရှင်မြတ်သည် အချို့ကို အချို့ထက် သာလွန်စေတော်မူသောကြောင့်လည်းကောင်း၊ ၎င်းတို့သည် မိမိတို့၏ ဥစ္စာပစ္စည်းမှ (၎င်းတို့အား ထောက်ပံ့ရန်) သုံးစွဲကြသောကြောင့်လည်းကောင်း ဖြစ်သည်။ အမျိုးသားသည် မိသားစု၏ ထိန်းသိမ်းစောင့်ရှောက်သူနှင့် အထောက်အပံ့ဖြစ်သူ ဖြစ်သည်။ 4:34
- အလ္လာဟ်အရှင်မြတ်ကို ကိုးကွယ်ပြီး အရှင်နှင့် မည်သူ့ကိုမျှ တွဲဖက်မထားပါနှင့်၊ မိဘများ၊ ဆွေမျိုးသားချင်းများ၊ မိဘမဲ့များ၊ ဆင်းရဲနွမ်းပါးသူများ၊ အိမ်နီးချင်း၊ ဘေးချင်းကပ်လျက် နေထိုင်သူ၊ ခရီးသွားဖြစ်သူ (သင်တို့တွေ့ဆုံသော သူ) နှင့် သင်တို့၏ ညာသန် (ကျွန်အဖြစ် ပိုင်ဆိုင်ထားသူများ) အား ကောင်းမှုပြုပါ။ အလ္လာဟ်အရှင်မြတ်သည် မာနကြီးသူများနှင့် ဝါကြွားသူများကို မနှစ်သက်ပါ။ အခြားသူများကို ကောင်းမှုပြုပါ။ အားနည်းသူများကို ကရုဏာထားပါ။ မိသားစုဆက်ဆံရေးကို ထိန်းသိမ်းပြီး ဆွေမျိုးသားချင်းများကို ဂုဏ်ပြုပါ။ 4:36
- ဝန်ခံခြင်း မပြုပါနှင့်။ 4:37
- အလ္လာဟ်အရှင်မြတ်သည် အရှင်နှင့် တွဲဖက်ထားခြင်းကို ခွင့်မလွှတ်ပါ၊ သို့သော် ထိုမှအပ အခြားသော အပြစ်များကို အရှင်အလိုတော်ရှိသူအား ခွင့်လွှတ်တော်မူသည်။ 4:48
- အခြားသူများကို မနာလိုမပြုပါနှင့်။ 4:54
- အလ္လာဟ်အရှင်မြတ်သည် သင်တို့အား ယုံကြည်စိတ်ချရသော တာဝန်ဝတ္တရားများကို ၎င်းတို့၏ ပိုင်ရှင်များထံ ပြန်အပ်နှင်းရန် အမိန့်ပေးတော်မူသည်။ လူသားများကြားတွင် စီရင်ဆုံးဖြတ်သောအခါ တရားမျှတစွာ စီရင်ဆုံးဖြတ်ပါ။ 4:58
- အလ္လာဟ်အရှင်မြတ်နှင့် အရှင်၏ ရစူလ်တမန်တော်ကို နာခံပါ။ သင်တို့ထဲရှိ အာဏာရှိသူများကို လျောက်ပတ်သော ရိုသေမှုကို ပေးအပ်ပါ။ 4:59
- အားနည်းသူများနှင့် ထိခိုက်လွယ်သူများကို ညှဉ်းပန်းနှိပ်စက်ခြင်းမပြုပါနှင့်။ 4:75
- သင်တို့ထံ ရောက်ရှိလာသော ကောင်းသောအရာများသည် အလ္လာဟ်အရှင်မြတ်ထံမှ ဖြစ်သည်။ သို့သော် သင်တို့ထံ ရောက်ရှိလာသော မကောင်းသောအရာများသည် သင်တို့ကိုယ်တိုင်မှ ဖြစ်သည်။ 4:79
- မည်သူမဆို ရစူလ်တမန်တော် (မုဟမ္မဒ် ﷺ) ကို နာခံပါက၊ ထိုသူသည် အလ္လာဟ်အရှင်မြတ်ကို နာခံပြီးဖြစ်သည်။ 4:80
- မည်သူမဆို ကောင်းသောကိစ္စတစ်ခုအတွက် ကြားဝင်စေ့စပ်ပေးပါက၊ ထိုသူသည် ၎င်းမှ ဆုလာဘ်ဝေစုကို ရရှိမည်။ ထို့ပြင် မည်သူမဆို မကောင်းသောကိစ္စတစ်ခုအတွက် ကြားဝင်စေ့စပ်ပေးပါက၊ ထိုသူသည် ၎င်း၏ ဝန်ထုပ်ဝန်ပိုး၏ ဝေစုကို ရရှိမည်။ 4:85
- ယုံကြည်သူတစ်ဦးသည် အခြားသော ယုံကြည်သူတစ်ဦးကို မတော်တဆမှု မဟုတ်ပါက သတ်ဖြတ်ခြင်းမပြုသင့်ပေ။ 4:92
- မည်သူမဆို ယုံကြည်သူတစ်ဦးကို ရည်ရွယ်ချက်ရှိရှိ သတ်ဖြတ်ပါက၊ ထိုသူ၏ အပြစ်ဒဏ်မှာ ထိုတွင် ထာဝရစံမြန်းရမည့် ငရဲဂျဟန္နမ်ဖြစ်သည်။ အလ္လာဟ်အရှင်မြတ်၏ အမျက်တော်နှင့် ကျိန်ဆဲခြင်းတော်သည် ထိုသူအပေါ်၌ ရှိသည်။ ထို့ပြင် ထိုသူအတွက် ကြီးလေးသော ပြစ်ဒဏ်ကို ပြင်ဆင်ထားပြီးဖြစ်သည်။ 4:93
- မည်သူမဆို အလ္လာဟ်အရှင်မြတ်၏ လမ်းတော်အတွက် (မိမိ၏ နေရပ်မှ) ထွက်ခွာသွားပါက၊ ထိုသူသည် ကမ္ဘာမြေပေါ်၌ နေရာများစွာနှင့် ပေါများကြွယ်ဝမှုကို တွေ့ရှိရမည်။ 4:100
- သင်တို့၏ ဆုတောင်းများကို အချိန်မှန်ပြုလုပ်ပါ။ 4:103
- မိမိတို့၏ ယုံကြည်စိတ်ချရသော တာဝန်ဝတ္တရားများကို သစ္စာဖောက်သူများကို ထောက်ခံခြင်းမပြုပါနှင့် သို့မဟုတ် ၎င်းတို့၏ ရှေ့နေမဖြစ်ပါနှင့်။ 4:105
- အလ္လာဟ်အရှင်မြတ်၏ ခွင့်လွှတ်ခြင်းကို တောင်းခံပါ၊ အမှန်မှာ အလ္လာဟ်အရှင်မြတ်သည် အလွန်ခွင့်လွှတ်တော်မူသော အရှင်၊ အလွန်ကရုဏာတော်ရှိသော အရှင် ဖြစ်သည်။ 4:106
- အို ယုံကြည်သူများ။ တရားမျှတမှုအတွက် ခိုင်မာစွာ ရပ်တည်ကြပါ၊ အလ္လာဟ်အရှင်မြတ်အတွက် သက်သေများဖြစ်ကြပါ၊ ၎င်းသည် သင်တို့ကိုယ်တိုင်၊ သင်တို့၏ မိဘများ သို့မဟုတ် သင်တို့၏ ဆွေမျိုးသားချင်းများကို ဆန့်ကျင်သည်ဖြစ်စေ၊ ထိုသူသည် ချမ်းသာသည် ဖြစ်စေ ဆင်းရဲသည် ဖြစ်စေ (တရားမျှတမှုမှ မဆုတ်နှင့်)။ တရားမျှတမှုကို မနှောင့်နှေးပါနှင့်။ အမှားများကို ပြင်ဆင်ရန် အမြန်ဆုံးဆောင်ရွက်ပါ။ 4:135
- လျှို့ဝှက်သွေဖည်သူများ (မနာဖီကန်များ) သည် အလ္လာဟ်အရှင်မြတ်ကို လှည့်ဖြားရန် ကြိုးစားကြသော်လည်း အရှင်သည်ပင် ၎င်းတို့ကို လှည့်ဖြားတော်မူသည်။ 4:142
- လျှို့ဝှက်သွေဖည်သူများ (မနာဖီကန်များ) သည် ငရဲမီး၏ အနိမ့်ဆုံး (အဆင့်) တွင်ရှိကြမည်။ ၎င်းတို့အတွက် ကူညီသူတစ်စုံတစ်ယောက်ကို သင်တွေ့ရှိမည်မဟုတ်။ 4:145
- အလ္လာဟ်အရှင်မြတ်သည် မတရားသဖြင့် ညှဉ်းပန်းနှိပ်စက်ခြင်းခံရသူမှတစ်ပါး မကောင်းမှုကို လူအများကြားတွင် ပြောဆိုခြင်းကို မနှစ်သက်ပါ။ 4:148
- ရစူလ်တမန်တော်များကို ဝမ်းမြောက်ဖွယ်သတင်းပေးသူများနှင့် သတိပေးသူများအဖြစ် စေလွှတ်တော်မူခဲ့သည်။ အကြောင်းမှာ ရစူလ်တမန်တော်များ (ကြွလာခြင်း) ပြီးနောက် လူသားများအား အလ္လာဟ်အရှင်မြတ်၏ ပြောစရာအကြောင်းမရှိစေရန်ဖြစ်သည်။ 4:165
- သင်တို့၏ စာချုပ်များနှင့် ကတိများကို ကျေပွန်အောင်ဆောင်ရွက်ပါ။ 5:1
- ကောင်းမှုကုသိုလ်နှင့် အလ္လာဟ်အရှင်မြတ်အား ကြောက်ရွံ့ခြင်းတို့တွင် အချင်းချင်း ကူညီပံ့ပိုးကြပါ၊ သို့သော် အပြစ်နှင့် ရန်လိုခြင်းတို့တွင် အချင်းချင်း ကူညီပံ့ပိုးခြင်းမပြုပါနှင့်။ 5:2
- သေသောသတ္တဝါ၊ သွေးနှင့် ဝက်သားတို့ကို မစားသုံးပါနှင့်။ 5:3
- တရားမျှတမှုရှိကြပါ၊ အခြားသူများအပေါ် ရန်လိုခြင်းနှင့် မုန်းတီးခြင်းတို့သည် သင်တို့ကို တရားမျှတမှုမှ ရှောင်ကြဉ်ခြင်းမပြုပါစေနှင့်။ တရားမျှတမှုရှိကြပါ။ တရားမျှတမှုရှိခြင်းသည် အလ္လာဟ်အရှင်မြတ်အား ကြောက်ရွံ့ခြင်းနှင့် နီးစပ်သည်ကို သိမှတ်ပါ။ တရားမျှတမှုကို မနှောင့်နှေးပါနှင့်။ အမှားများကို ပြင်ဆင်ရန် အမြန်ဆုံးဆောင်ရွက်ပါ။ 5:8
- အလ္လာဟ်အရှင်မြတ်ထံ ချဉ်းကပ်ရန် နည်းလမ်းများကို ရှာဖွေပြီး အရှင်၏ လမ်းတော်တွင် သင်တို့တတ်နိုင်သမျှ ကြိုးစားအားထုတ်ပါ။ သို့မှသာ သင်တို့ အောင်မြင်ကြမည်။ 5:35
- သင်တို့၏ ကျိန်ဆိုမှုများနှင့် ကတိသစ္စာများကို ကျေပွန်အောင်ဆောင်ရွက်ပါ။ 5:89
- မူးယစ်စေသော အရာများနှင့် အရက်ကို ရှောင်ကြဉ်ပါ။ မူးယစ်စေသော အရာများ (အရက်အမျိုးမျိုး)၊ လောင်းကစား၊ အလ်-အန်ဆွတ်ဘ် (ကျောက်တုံးပလ္လင်များ) နှင့် အလ်-အက်ဇ်လမ် (ကံကောင်းခြင်း သို့မဟုတ် ဆုံးဖြတ်ချက်ရယူရန် မြှားများ) တို့ကို ပြင်းထန်စွာ ရှောင်ကြဉ်ပါ။ ၎င်းတို့အားလုံးသည် ရှိုင်သွန် (စာတန်) ၏ လက်ရာများမှ စက်ဆုပ်ရွံရှာဖွယ်ရာများဖြစ်သည်။ 5:90
- သင်တို့သည် ဟဂ်ျ သို့မဟုတ် အွမ်ရာဟ် (ဘုရားဖူးသွားခြင်း) အတွက် အီဟ်ရန်မ် အခြေအနေတွင် ရှိစဉ် တောတိရစ္ဆာန်ကို မသတ်ပါနှင့်။ 5:95
- သင်တို့အား ရှင်းလင်းပြတ်သားစွာ ပြောပြခဲ့လျှင် သင်တို့ကို ဒုက္ခပေးနိုင်သော အကြောင်းအရာများကို မမေးမြန်းပါနှင့်။ 5:101
- အခြားသူများ၏ နတ်ဘုရားများကို မဆဲဆိုပါနှင့်။ (မယုံကြည်သူများ) သည် အလ္လာဟ်အရှင်မြတ်မှတစ်ပါး ကိုးကွယ်သော အရာများကို မဆဲဆိုပါနှင့်၊ သို့မဟုတ်ပါက ၎င်းတို့သည် အသိပညာမရှိဘဲ အလ္လာဟ်အရှင်မြတ်ကို ဆဲဆိုမိမည်။ 6:108
- အကယ်၍ သင်သည် ကမ္ဘာမြေပေါ်ရှိ လူအများစုကို နာခံပါက၊ ၎င်းတို့သည် သင်တို့ကို အလ္လာဟ်အရှင်မြတ်၏ လမ်းတော်မှ လမ်းလွှဲစေမည်။ ၎င်းတို့သည် ထင်မြင်ချက်ကိုသာလျှင် လိုက်နာကြပြီး ၎င်းတို့သည် မဟုတ်မမှန်သာ ပြောဆိုကြသည်။ 6:116
- (အို လူသားတို့) အပြစ်တရားအားလုံးကို ထင်ရှားသော အပြစ်ရော ကွယ်ဝှက်သော အပြစ်ပါ စွန့်ခွာပါ။ 6:120
- (အို ယုံကြည်သူများ) အလ္လာဟ်အရှင်မြတ်၏ နာမတော်ကို (တိရစ္ဆာန်သတ်ချိန်တွင်) ဖော်ပြခြင်းမပြုခဲ့သော အရာ (အသား) ကို မစားပါနှင့်။ 6:121
- အလ္လာဟ်အရှင်မြတ်သည် မည်သူကို လမ်းညွှန်တော်မူလိုပါက၊ ထိုသူ၏ ရင်ဘတ်ကို အစ္စလာမ်ဘာသာအတွက် ပွင့်စေတော်မူသည်။ ထို့ပြင် အရှင်သည် မည်သူကို လမ်းလွှဲစေလိုပါက၊ ထိုသူ၏ ရင်ဘတ်ကို ကျဉ်းကျပ်၍ ဖိအားဖြစ်စေတော်မူသည်။ 6:125
- သုံးစွဲရာတွင် မျှတပြီး အလွန်အကျွံသုံးစွဲခြင်းကို ရှောင်ကြဉ်ပါ။ သတ္တဝါအားလုံး၏ အခွင့်အရေးများကို ထိန်းသိမ်းပါ။ 6:141
- အလ္လာဟ်အရှင်မြတ်နှင့် ကိုးကွယ်ဆည်းကပ်ရာတွင် မည်သည့်အရာကိုမျှ တွဲဖက်မထားပါနှင့်၊ မိဘများကို ကောင်းမှုပြုပါ၊ ဆင်းရဲမွဲတေမှုကိုစိုး၍ သင်တို့၏ သားသမီးများကို မသတ်ပါနှင့်၊ ညစ်ညမ်းသော အကျင့်များသို့ မချဉ်းကပ်ပါနှင့်၊ အလ္လာဟ်အရှင်မြတ် တားမြစ်တော်မူခဲ့သော မည်သူ့ကိုမျှ တရားသော အကြောင်းမရှိဘဲ မသတ်ပါနှင့်။ 6:151
- ရိုးသားကြပါ၊ မိမိတို့၏ ကိစ္စရပ်များတွင် မလိမ်လည်ပါနှင့်။ မိဘမဲ့၏ ဥစ္စာပစ္စည်းထံသို့ မချဉ်းကပ်ပါနှင့်၊ ၎င်းကို တိုးတက်ကောင်းမွန်စေရန်မှတစ်ပါး၊ မျှတမှုဖြင့် ပြည့်ပြည့်စုံစုံ တိုင်းတာခြင်းနှင့် ချိန်ဆခြင်းကို ဆောင်ရွက်ပါ၊ သင်တို့ စကားပြောသောအခါတိုင်း ဆွေမျိုးသားချင်းနှင့် သက်ဆိုင်သည်ဖြစ်စေ အမှန်တရားကို ပြောဆိုပါ၊ ထို့ပြင် အလ္လာဟ်အရှင်မြတ်၏ ကတိသစ္စာကို ကျေပွန်အောင်ဆောင်ရွက်ပါ။ 6:152
- ဖြောင့်မတ်သောလမ်း (စီရာသွလ်မွတ်စတကီမ်) ကို လိုက်နာပြီး (အခြားသော) လမ်းများကို မလိုက်ပါနှင့်၊ အကြောင်းမှာ ၎င်းတို့သည် သင်တို့ကို အရှင်၏ လမ်းတော်မှ ကွဲကွာသွားစေမည်ဖြစ်သောကြောင့်တည်း။ 6:153
- (အို မုဟမ္မဒ် ﷺ) ဟောပါ။ "အမှန်မှာ၊ ကျွန်ုပ်၏ ဆွလာသ်ဝတ်ပြုဆုတောင်းခြင်း၊ ကျွန်ုပ်၏ ကုရ်ဗာန်ပူဇော်ခြင်း၊ ကျွန်ုပ်၏ အသက်ရှင်ခြင်းနှင့် ကျွန်ုပ်၏ သေခြင်းသည် စကြဝဠာများ၏ အရှင်သခင် (ရဗ်ဗ်) အလ္လာဟ်အရှင်မြတ်အတွက်သာ ဖြစ်သည်။" 6:162
- မာနကြီးခြင်းမပြုပါနှင့်။ 7:13
- ရှိုင်သွန် (စာတန်) သည် သင်တို့ကို လှည့်ဖြားခြင်း မပြုပါစေနှင့်။ 7:27
- (အို မုဟမ္မဒ် ﷺ) ဟောပါ။ "ကျွန်ုပ်၏ အရှင်သခင် (ရဗ်ဗ်) သည် တရားမျှတမှုကို အမိန့်ပေးတော်မူသည်…" 7:29
- ကိစ္စအရပ်ရပ်၌ အလ္လာဟ်အရှင်မြတ် သတ်မှတ်တော်မူသော နယ်နိမိတ်များကို စောင့်ထိန်းပါ။ စကားနှင့် လုပ်ရပ်တို့တွင် ကျူးကျော်ခြင်းကို ရှောင်ကြဉ်ပါ။ စားပါ၊ သောက်ပါ သို့သော် အလွန်အကျွံ မပြုပါနှင့်။ ဆုတောင်းချိန်များတွင် ကောင်းမွန်သော အဝတ်အစားများကို ဝတ်ဆင်ပါ။ 7:31
- အလ္လာဟ်အရှင်မြတ်သည် မိုးကောင်းကင်များနှင့် ကမ္ဘာမြေကို ခြောက်ရက်အတွင်း ဖန်တီးတော်မူခဲ့ပြီး၊ ထို့နောက် အရှင်သည် အရ်ရှ်ဗိမာန်တော်ပေါ်၌ (အရှင်၏ မြင့်မြတ်တော်မူခြင်းနှင့် လျော်ညီသော နည်းလမ်းဖြင့်) စိုးစံတော်မူခဲ့သည်။ 7:54
- သင်တို့၏ အရှင်သခင် (ရဗ်ဗ်) ကို နှိမ့်ချစွာဖြင့်လည်းကောင်း၊ လျှို့ဝှက်စွာဖြင့်လည်းကောင်း ဆုတောင်းပါ။ အရှင်သည် ကျူးကျော်သူများကို မနှစ်သက်ပါ။ 7:55
- ကမ္ဘာမြေကို ပြုပြင်ဖြောင့်မတ်စေပြီးနောက် ထိုတွင် ဖောက်ပြန်ခြင်းမပြုပါနှင့်၊ ထို့ပြင် အရှင်ကို ကြောက်ရွံ့ခြင်းနှင့် မျှော်လင့်ခြင်းဖြင့် ဆုတောင်းပါ။ 7:56
- သို့ရာတွင် မည်သည့်သူမဆို မကောင်းသော အကျင့်များကို ကျူးလွန်ပြီးနောက် နောင်တရကာ ယုံကြည်ခဲ့ပါက၊ အမှန်မှာ သင်တို့၏ အရှင်သခင် (ရဗ်ဗ်) သည် ထိုအရာများပြီးနောက် အလွန်ခွင့်လွှတ်တော်မူသောအရှင်၊ အလွန်ကရုဏာတော်ရှိသောအရှင်ဖြစ်သည်။ 7:153
- (အို မုဟမ္မဒ် ﷺ) ဟောပါ။ "အို လူသားအပေါင်းတို့။ အမှန်မှာ၊ ကျွန်ုပ်သည် သင်တို့အားလုံးထံသို့ အလ္လာဟ်အရှင်မြတ်၏ ရစူလ်တမန်တော်အဖြစ် စေလွှတ်ခြင်းခံရသူဖြစ်သည်…" 7:158
- ထို့ပြင် (အလ္လာဟ်အရှင်မြတ်၏) အကောင်းဆုံး နာမတော်များအားလုံးသည် အရှင်အတွက်သာဖြစ်သည်။ ထို့ကြောင့် ၎င်းတို့ဖြင့် အရှင်ကို ဆုတောင်းပါ။ ထို့ပြင် အရှင်၏ နာမတော်များနှင့် ပတ်သက်၍ ကောက်ကျစ်ခြင်းပြုသူများကို စွန့်ခွာပါ… 7:180
- အလ္လာဟ်အရှင်မြတ်သည် မည်သူကို လမ်းလွှဲတော်မူပါက၊ ထိုသူအား လမ်းညွှန်ပြသူ မရှိပါ။ ထို့ပြင် အရှင်သည် ၎င်းတို့ကို ၎င်းတို့၏ ကျူးကျော်မှုများတွင် မျက်စိမမြင် လမ်းလွဲနေစေတော်မူသည်။ 7:186
- ခွင့်လွှတ်ခြင်းကို ကျင့်သုံးပါ၊ ကောင်းမှုကုသိုလ်ကို ညွှန်ကြားပါ၊ ထို့ပြင် မိုက်မဲသူများထံမှ မျက်နှာလွှဲပါ (ဆိုလိုသည်မှာ ၎င်းတို့ကို ပြစ်ဒဏ်မပေးပါနှင့်)။ 7:199
- အခြားသူများ၏ အမှားများကို ခွင့်လွှတ်ပါ။ 7:199
- ထို့ပြင် ရှိုင်သွန် (စာတန်) ထံမှ မကောင်းသော တိုက်တွန်းမှုတစ်ခု သင်တို့ထံ ရောက်ရှိလာပါက၊ အလ္လာဟ်အရှင်မြတ်ထံတွင် ခိုလှုံပါ။ အမှန်မှာ၊ အရှင်သည် အရာခပ်သိမ်းကို ကြားတော်မူသောအရှင်၊ အရာခပ်သိမ်းကို သိရှိတော်မူသောအရှင် ဖြစ်သည်။ 7:200
- ယုံကြည်သူများသည် အလ္လာဟ်အရှင်မြတ် အောက်မေ့သတိရသောအခါ ၎င်းတို့၏ နှလုံးသားများတွင် ကြောက်ရွံ့ခြင်း ခံစားရသော သူများ၊ ထို့ပြင် အရှင်၏ အာယသ်တော်များ ရွတ်ဖတ်ပြသသောအခါ ၎င်းတို့၏ အီမာန်ယုံကြည်ခြင်းကို တိုးပွားစေသော သူများသာ ဖြစ်ကြသည်… 8:2
- အလ္လာဟ်အရှင်မြတ်နှင့် အရှင်၏ ရစူလ်တမန်တော်ကို သစ္စာမဖောက်ပါနှင့်၊ ထို့ပြင် သင်တို့၏ ယုံကြည်စိတ်ချရသော တာဝန်ဝတ္တရားများ (နှင့် အလ္လာဟ်အရှင်မြတ် သင်တို့အပေါ် အမိန့်ပေးတော်မူသော တာဝန်များအားလုံး) ကို သိရှိလျက်သာလျှင် သစ္စာမဖောက်ပါနှင့်။ 8:27
- အကယ်၍ သင်တို့သည် အလ္လာဟ်အရှင်မြတ်အား နာခံပြီး ကြောက်ရွံ့ပါက၊ အရှင်သည် သင်တို့အား ဖှာရ်ကာန် (အမှန်နှင့်အမှား ခွဲခြားနိုင်သော စံသတ်မှတ်ချက်၊ သို့မဟုတ် ခက်ခဲသော အခြေအနေတိုင်းမှ ထွက်မြောက်ရန် နည်းလမ်း) ကို ပေးအပ်တော်မူမည်။ 8:29
- မယုံကြည်သူများသည် မိမိတို့၏ ဥစ္စာပစ္စည်းကို (လူများကို) အလ္လာဟ်အရှင်မြတ်၏ လမ်းတော်မှ တားဆီးရန် သုံးစွဲကြပြီး၊ ၎င်းတို့သည် ထိုသို့ ဆက်လက်သုံးစွဲနေကြလိမ့်မည်။ သို့သော် နောက်ဆုံးတွင် ၎င်းသည် ၎င်းတို့အတွက် နောင်တရစရာ ဖြစ်လာမည်။ 8:36
- မယုံကြည်သူများအား ပြောပါ၊ အကယ်၍ ၎င်းတို့သည် (မယုံကြည်ခြင်းမှ) ရပ်စဲပါက၊ ၎င်းတို့၏ အတိတ်က အပြစ်များကို ခွင့်လွှတ်ခြင်းခံရမည်။ သို့သော် အကယ်၍ ၎င်းတို့သည် (ထိုသို့) ပြန်လာပါက၊ ၎င်းတို့မတိုင်မီ (ပြစ်ဒဏ်ခံခဲ့ရသော) သူများ၏ စံနမူနာများသည် သတိပေးချက်အနေဖြင့် ကြိုတင်ရှိနှင့်ပြီးဖြစ်သည်။ 8:38
- သင်တို့သည် (ရန်သူ) တပ်အင်အားနှင့် ရင်ဆိုင်တွေ့ဆုံသောအခါ၊ ခိုင်မာစွာရပ်တည်ပြီး အလ္လာဟ်အရှင်မြတ်၏ နာမတော်ကို (နှုတ်နှင့်ရော စိတ်နှင့်ပါ) များစွာ အောက်မေ့သတိရပါ။ သို့မှသာ သင်တို့ အောင်မြင်ကြမည်။ 8:45
- မိမိတို့၏ အိမ်များမှ မာနကြီးစွာဖြင့်လည်းကောင်း၊ လူတို့အား ပြသရန်အတွက်လည်းကောင်း ထွက်လာကြပြီး (လူများကို) အလ္လာဟ်အရှင်မြတ်၏ လမ်းတော်မှ တားဆီးကြသော သူများနှင့် မတူကြပါနှင့်။ 8:47
- အလ္လာဟ်အရှင်မြတ်သည် လူမျိုးတစ်မျိုးအား ပေးအပ်တော်မူခဲ့သော ကျေးဇူးတော်ကို ၎င်းတို့သည် မိမိတို့ကိုယ်တွင်းရှိ အခြေအနေကို မပြောင်းလဲမချင်း ဘယ်သောအခါမျှ မပြောင်းလဲတော်မူပါ။ 8:53
- အလ္လာဟ်အရှင်မြတ်ထံတော်၌ သတ္တဝါများအနက် အဆိုးရွားဆုံးမှာ မယုံကြည်သူများဖြစ်သည်။ 8:55
- ဘုရားရှင်သည် အရှင်ကို ယုံကြည်သူများ၏ နှလုံးသားများကြားတွင် မေတ္တာတရားနှင့် ချစ်ခင်မှုကို ဖြစ်ပေါ်စေတော်မူသည်။ 8:63
- ခိုလှုံရန် တောင်းခံသူများကို ကာကွယ်စောင့်ရှောက်ပြီး ကူညီပါ။ 9:6
- အလ္လာဟ်အရှင်မြတ်၏ ဗလီများကို မွတ်ရှ်ရစ်ကန်များ (အလ္လာဟ်အရှင်မြတ်နှင့် တွဲဖက်ကိုးကွယ်သူများ) က ထိန်းသိမ်းခြင်းသည် မသင့်လျော်ပါ။ 9:17
- ၎င်းတို့ (မယုံကြည်သူများ၊ ဂျူးများနှင့် ခရစ်ယာန်များ) သည် အလ္လာဟ်အရှင်မြတ်၏ အလင်းတော် (မုဟမ္မဒ် ﷺ ကို စေလွှတ်တော်မူခဲ့သည့် အစ္စလာမ်ဘာသာ၏ တစ်ဆူတည်းသော ဘုရားကိုးကွယ်ခြင်း) ကို ၎င်းတို့၏ ပါးစပ်များဖြင့် ငြိမ်းသတ်ရန် ကြိုးစားကြသည်။ သို့သော် အလ္လာဟ်အရှင်မြတ်သည် မယုံကြည်သူများ မုန်းတီးသော်လည်း အရှင်၏ အလင်းတော် ပြည့်စုံတော်မူခြင်းကိုသာလျှင် ငြင်းပယ်တော်မူမည်မဟုတ်ပေ။ 9:32
- ဆွဒကါသ် (ဇကာသ်) များသည် အောက်ပါသူများအတွက်သာ ဖြစ်သည်။ ၁) ဖုခရာဟ် (အလွန်ဆင်းရဲသူများ)၊ ၂) အလ်-မဆာကီးန် (ဆင်းရဲနွမ်းပါးသူများ)၊ ၃) ထိုငွေများကို စုဆောင်းရန် စေလွှတ်ခြင်းခံရသူများ၊ ၄) အစ္စလာမ်ဘာသာသို့ စိတ်စေတနာ စွဲမက်လာအောင် ဆွဲဆောင်ရမည့်သူများ၊ ၅) ကျွန်များကို လွှတ်ပေးရန်၊ ၆) ကြွေးမြီရှိသူများ၊ ၇) အလ္လာဟ်အရှင်မြတ်၏ လမ်းတော်အတွက် (မုဂျာဟိဒ်များ)၊ ၈) ခရီးသွားများအတွက် ဖြစ်သည်။ 9:60
- မည်သူမဆို အလ္လာဟ်အရှင်မြတ်နှင့် အရှင်၏ ရစူလ်တမန်တော် (ﷺ) ကို ဆန့်ကျင်ပြီး ရန်လိုပါက၊ ထိုသူအတွက် ငရဲဂျဟန္နမ်၏ မီးရှိမည်ဖြစ်ပြီး၊ ထိုတွင် ထာဝရစံမြန်းရမည်။ ဤသည်မှာ အလွန်ကြီးကျယ်သော အရှက်တွဲခြင်းပင်ဖြစ်သည်။ 9:63
- လျှို့ဝှက်သွေဖည်သူ အမျိုးသားများနှင့် အမျိုးသမီးများသည် အချင်းချင်း တူညီကြသည်။ ၎င်းတို့သည် အလ္လာဟ်အရှင်မြတ်ကို မေ့လျော့ခဲ့ကြသည်၊ ထို့ကြောင့် အရှင်သည်လည်း ၎င်းတို့ကို မေ့လျော့တော်မူခဲ့သည်။ 9:67
- သန့်ရှင်းစင်ကြယ်မှုအတွက် ကြိုးစားပါ။ ဗလီ၏ မြင့်မြတ်မှုကို ရိုသေပါ။ 9:108
- မွတ်ရှ်ရစ်ကန်များအတွက် — ၎င်းတို့သည် ဆွေမျိုးသားချင်းများဖြစ်ကြသော်လည်း — ၎င်းတို့သည် ငရဲသားများဖြစ်ကြောင်း ရှင်းလင်းသိရှိပြီးနောက် (၎င်းတို့သည် မယုံကြည်မှုဖြင့် သေဆုံးသွားသောကြောင့်) (နဗီတမန်တော်နှင့် ယုံကြည်သူများအတွက်) အလ္လာဟ်အရှင်မြတ်ထံ ခွင့်လွှတ်ခြင်းတောင်းခံခြင်းသည် မသင့်လျော်ပါ။ 9:113
- အလ္လာဟ်အရှင်မြတ်ပေါ်တွင် မဟုတ်မမှန်ကို စွပ်စွဲသော သို့မဟုတ် အရှင်၏ အာယသ်တော်များကို ငြင်းပယ်သော သူထက် သာ၍ မတရားကျူးလွန်သူ မည်သူရှိသနည်း။ အမှန်မှာ၊ အပြစ်ကျူးလွန်သူများသည် ဘယ်သောအခါမျှ အောင်မြင်ကြမည်မဟုတ်ပေ။ 10:17
- ၎င်းတို့သည် အလ္လာဟ်အရှင်မြတ်မှတစ်ပါး ၎င်းတို့အား အန္တရာယ်မပြုနိုင်သော သို့မဟုတ် အကျိုးမပေးနိုင်သော အရာများကို ကိုးကွယ်ကြပြီး၊ "ဤအရာများသည် အလ္လာဟ်အရှင်မြတ်ထံတော်၌ ကျွန်ုပ်တို့၏ ကြားဝင်စေ့စပ်ပေးသူများဖြစ်သည်" ဟု ဆိုကြသည်။ ဟောပါ။ "သင်တို့သည် မိုးကောင်းကင်များနှင့် ကမ္ဘာမြေပေါ်တွင် အရှင်မသိရှိသော အရာကို အလ္လာဟ်အရှင်မြတ်အား သတင်းပေးနေကြသလော။" အရှင်သည် ၎င်းတို့ တွဲဖက်ကိုးကွယ်သော အရာအားလုံးထက် မြင့်မြတ်တော်မူပြီး စင်ကြယ်တော်မူ၏။ 10:18
- မကောင်းမှု၏ အပြစ်ဒဏ်သည် ၎င်းနှင့် တူညီသော မကောင်းမှုပင်ဖြစ်သည်။ 10:27
- ဤအရှင်သည် အလ္လာဟ်အရှင်မြတ်၊ သင်တို့၏ အမှန်တရားဖြစ်သော အရှင်သခင် (ရဗ်ဗ်) ပင်ဖြစ်သည်။ သို့ဖြစ်၍ အမှန်တရားပြီးနောက် လမ်းလွဲခြင်းမှတစ်ပါး အခြားဘာရှိမည်နည်း။ သို့ဖြစ်လျှင် သင်တို့ကို မည်သို့ လှည့်ဖြားခြင်းခံရသနည်း။ 10:32
- ၎င်းတို့အနက် အများစုသည် ထင်မြင်ချက်ကိုသာလျှင် လိုက်နာကြသည်။ အမှန်မှာ ထင်မြင်ချက်သည် အမှန်တရားကို မည်သည့်အရာမျှ အစားမထိုးနိုင်ပေ။ 10:36
- အမှန်မှာ။ အလ္လာဟ်အရှင်မြတ်သည် လူသားများကို မည်သည့်အရာမျှ မတရားမပြုပါ။ သို့သော် လူသားများပင် မိမိတို့ကိုယ်ကို မတရားပြုကြသည်။ 10:44
- အလ္လာဟ်အရှင်မြတ်၏ ကျေးဇူးတော်သည် လူသားတစ်ဦး စုဆောင်းသိမ်းဆည်းနိုင်သမျှထက် သာလွန်ကောင်းမွန်ကြောင်း သိမှတ်ပါ။ 10:58
- အလ္လာဟ်အရှင်မြတ်၏ အာယသ်တော်များကို ငြင်းပယ်သူများထဲမှ မဖြစ်ပါနှင့်၊ သို့မဟုတ်ပါက သင်တို့သည် ရှုံးနိမ့်သူများထဲတွင် ဖြစ်သွားမည်။ 10:95
- အကယ်၍ အလ္လာဟ်အရှင်မြတ်သည် သင်တို့အား အန္တရာယ်တစ်စုံတစ်ရာ ထိခိုက်စေတော်မူပါက၊ အရှင်မှတစ်ပါး ၎င်းကို ဖယ်ရှားနိုင်သူမရှိပါ။ ထို့ပြင် အကယ်၍ အရှင်သည် သင်တို့အတွက် ကောင်းကျိုးတစ်စုံတစ်ရာကို ရည်ရွယ်တော်မူပါက၊ အရှင်၏ ကျေးဇူးတော်ကို ပြန်လည်တားဆီးနိုင်သူမရှိပါ။ အရှင်သည် ၎င်းအား အရှင်၏ ကျွန်များအနက် အလိုရှိတော်မူသူထံသို့ ပေးအပ်တော်မူသည်။ 10:107
- ကမ္ဘာမြေပေါ်တွင် မည်သည့် သက်ရှိသတ္တဝါမျှ မရှိပါ၊ ၎င်း၏ အစားအစာသည် အလ္လာဟ်အရှင်မြတ်အပေါ်၌ မတည်ရှိသော သတ္တဝါမျှ မရှိပါ။ ထို့ပြင် အရှင်သည် ၎င်း၏ နေထိုင်ရာနေရာနှင့် ၎င်း၏ သိုမှီးရာနေရာ (သန္ဓေအိမ်၊ သင်္ချိုင်းတွင်းစသည်) ကို သိရှိတော်မူသည်။ 11:6
- အကယ်၍ ကျွန်ုပ်တို့သည် လူသားအား ကျွန်ုပ်တို့ထံမှ ကရုဏာတော်ကို မြည်းစမ်းစေပြီးနောက်၊ ၎င်းကို သူ့ထံမှ ပြန်လည်ရုပ်သိမ်းလိုက်ပါက၊ အမှန်မှာ သူသည် အားကိုးရာမဲ့ပြီး ကျေးဇူးကန်းသော သူဖြစ်သွားသည်။ 11:9
- မည်သူမဆို လောကီဘဝနှင့် ၎င်း၏ တင့်တယ်ခြင်းကို လိုလားပါက၊ ၎င်းတို့အား ကျွန်ုပ်တို့သည် ထိုဘဝတွင် ၎င်းတို့၏ လုပ်ရပ်များအတွက် အပြည့်အစုံ ပေးအပ်မည်ဖြစ်ပြီး ၎င်းတို့အား ထိုဘဝတွင် လျှော့ပေါ့ခြင်း မပြုရ။ 11:15
- ကျွန်ုပ်တို့သည် ၎င်းတို့ကို မတရားပြုခဲ့ခြင်းမဟုတ်ပါ။ သို့သော် ၎င်းတို့သည် မိမိတို့ကိုယ်တိုင် မတရားပြုခဲ့ကြသည်။ ၎င်းတို့၏ အရှင်သခင် (ရဗ်ဗ်) ၏ အမိန့်တော် ရောက်ရှိလာသောအခါ ၎င်းတို့သည် အလ္လာဟ်အရှင်မြတ်မှတစ်ပါး ဆုတောင်းပူဇော်ခဲ့သော ၎င်းတို့၏ နတ်ဘုရားများသည် ၎င်းတို့အတွက် မည်သည့်အကျိုးမျှ မပေးနိုင်ခဲ့ပေ။ ထို့ပြင် ၎င်းတို့အား ပျက်စီးခြင်းမှတစ်ပါး အခြား မည်သည့်အရာကိုမျှ မတိုးပွားစေခဲ့ပေ။ 11:101
- ၎င်း (ပြစ်ဒဏ်) ရောက်ရှိလာသော ထိုနေ့တွင်၊ အလ္လာဟ်အရှင်မြတ်၏ ခွင့်ပြုချက်တော်မရှိဘဲ မည်သူမျှ စကားမပြောနိုင်ရ။ ၎င်းတို့အနက် အချို့သည် ကံဆိုးသူများဖြစ်ကြပြီး (အချို့မှာ) ကံကောင်းသူများဖြစ်ကြသည်။ 11:105
- ကံဆိုးသူများအနေဖြင့် ၎င်းတို့သည် ငရဲမီး၌ ရှိကြမည်။ ထိုတွင် ၎င်းတို့အတွက် မြည်တမ်းခြင်းနှင့် ညည်းညူခြင်းတို့ရှိကြမည်။ 11:106
- ၎င်းတို့သည် မိုးကောင်းကင်များနှင့် ကမ္ဘာမြေ တည်ရှိနေသမျှ ကာလပတ်လုံး ထိုတွင် ထာဝရစံမြန်းကြမည်။ သို့သော် သင်တို့၏ အရှင်သခင် (ရဗ်ဗ်) ၏ အလိုတော်မှတစ်ပါး။ အမှန်မှာ သင်တို့၏ အရှင်သခင် (ရဗ်ဗ်) သည် အလိုရှိတော်မူသောအရာကို ပြုတတ်သောအရှင် ဖြစ်သည်။ 11:107
- ကံကောင်းသူများမူကား ၎င်းတို့သည် ဂျန္နသ်သုခဘုံ၌ ရှိကြမည်။ ထိုတွင် ထာဝရစံမြန်းကြမည်။ မိုးကောင်းကင်များနှင့် ကမ္ဘာမြေ တည်ရှိနေသမျှ ကာလပတ်လုံး၊ သို့သော် သင်တို့၏ အရှင်သခင် (ရဗ်ဗ်) ၏ အလိုတော်မှတစ်ပါး။ (၎င်းသည်) ကုန်ဆုံးခြင်းမရှိသော လက်ဆောင်တော်ဖြစ်သည်။ 11:108
- မတရားကျူးလွန်သူများထံသို့ မယိမ်းယိုင်/မျက်နှာသာမပေးပါနှင့်၊ သို့မဟုတ်ပါက ငရဲမီးသည် သင်တို့ကို ထိခိုက်မည်။ ထို့ပြင် အလ္လာဟ်အရှင်မြတ်မှတစ်ပါး သင်တို့အတွက် ကာကွယ်စောင့်ရှောက်သူများမရှိဘဲ၊ ထို့နောက် သင်တို့အား ကူညီခြင်းလည်း မပြုရ။ 11:113
- နေ့၏ အစွန်းနှစ်ဖက်နှင့် ည၏ အချို့သော အချိန်များတွင် ဆွလာသ်ဝတ်ပြုဆုတောင်းခြင်းကို ဆောင်ရွက်ပါ (ဆိုလိုသည်မှာ နေ့စဉ် ဆုတောင်း ၅ ကြိမ်)။ ကောင်းမှုကုသိုလ်များသည် မကောင်းမှုများ (ဆိုလိုသည်မှာ အငယ်စား အပြစ်များ) ကို ဖယ်ရှားပေးသည်။ 11:114
- မိုးကောင်းကင်များနှင့် ကမ္ဘာမြေ၏ မမြင်နိုင်သော အရာများသည် အလ္လာဟ်အရှင်မြတ်အတွက်သာ ဖြစ်သည်။ ထို့ပြင် ကိစ္စအရပ်ရပ်အားလုံးသည် အရှင်ထံသို့ ပြန်လည်ရောက်ရှိသည်။ 11:123
- အမိန့်တော် (သို့မဟုတ် စီရင်ဆုံးဖြတ်ခြင်း) သည် အလ္လာဟ်အရှင်မြတ်အတွက်သာ ဖြစ်သည်။ အရှင်သည် သင်တို့အား အရှင်မှတစ်ပါး မည်သူ့ကိုမျှ မကိုးကွယ်ရန် (တစ်ဆူတည်းသော ဘုရားကိုးကွယ်ခြင်း) အမိန့်ပေးတော်မူခဲ့သည်။ ထိုအရာသည် ဖြောင့်မတ်သော ဘာသာတရားဖြစ်သည်။ သို့သော် လူအများစုမှာ မသိရှိကြပေ။ 12:40
- အလ္လာဟ်အရှင်မြတ်၏ ကရုဏာတော်ကို ဘယ်သောအခါမျှ မျှော်လင့်ချက်မဖြတ်ပါနှင့်။ 12:87
- သင်တို့သည် အလွန်လိုလားတောင့်တသော်လည်း လူအများစုသည် ယုံကြည်ကြမည်မဟုတ်ပေ။ 12:103
- ထို့ပြင် ၎င်းတို့အနက် အများစုသည် အလ္လာဟ်အရှင်မြတ်ကို ယုံကြည်ခြင်းမရှိကြဘဲ၊ ၎င်းတို့သည် (အရှင်နှင့်) တွဲဖက်ကိုးကွယ်ခြင်းသာလျှင်ရှိသည် (ဆိုလိုသည်မှာ ၎င်းတို့သည် မွတ်ရှ်ရစ်ကန်များဖြစ်ကြသည်)။ 12:106
- ၎င်း (ကုရ်အာန်ကျမ်းတော်မြတ်) သည် ပြုလုပ်ခဲ့သော စကားတစ်ခုမဟုတ်ပါ။ သို့သော် ၎င်းသည် အလ္လာဟ်အရှင်မြတ်၏ ရှိပြီးသား ကျမ်းတော်များ (သော်ရသ်၊ အင်ဂျီလ်နှင့် အခြားသော ကျမ်းတော်များ) ကို အတည်ပြုခြင်းဖြစ်ပြီး၊ အရာခပ်သိမ်း၏ အသေးစိတ် ရှင်းလင်းချက်နှင့် ယုံကြည်သူများအတွက် လမ်းညွှန်မှုနှင့် ကရုဏာတော်လည်းဖြစ်သည်။ 12:111
- အလ္လာဟ်အရှင်မြတ်သည် အလိုရှိတော်မူသူအား စားနပ်ရိက္ခာကို ချဲ့ထွင်ပေးတော်မူပြီး (အလိုရှိတော်မူသူအား) ကျဉ်းမြောင်းစေတော်မူသည်။ 13:26
- အလ္လာဟ်အရှင်မြတ်ကို ဇစ်ကရ် (အောက်မေ့သတိရခြင်း) ဖြင့် မကြာခဏ အောက်မေ့သတိရပါ။ အလ္လာဟ်အရှင်မြတ်ကို ယုံကြည်သူများသည် အရှင်ကို အောက်မေ့သတိရခြင်းဖြင့် စိတ်အေးချမ်းမှုကို ရရှိကြသည်။ 13:28
- ယုံကြည်ပြီး ကောင်းမှုကုသိုလ်များကို ပြုကြသော သူများသည် ပျော်ရွှင်ခြင်းနှင့် စိတ်ငြိမ်သက်ခြင်းကို ခံစားကြရသည်။ 13:29
- နောင်ဘဝ (အာခိရသ်) ထက် လောကီဘဝကို ဦးစားပေးသော သူများ၊ (လူများကို) အလ္လာဟ်အရှင်မြတ်၏ လမ်းတော် (အစ္စလာမ်) မှ တားဆီးသော သူများနှင့် ထိုလမ်းကို ကောက်ကွေးအောင် ကြိုးစားသော သူများ — ထိုသူများသည် ဝေးကွာသော လမ်းလွဲခြင်း၌ ရှိကြသည်။ 14:3
- ဝတ်ပြုဆည်းကပ်ရာတွင် နှိမ့်ချခြင်းနှင့် ကျေးဇူးတင်ခြင်းကို ကျင့်သုံးပါ။ 14:7
- မိမိတို့၏ အရှင်သခင် (ရဗ်ဗ်) ကို မယုံကြည်သူများ၏ ဥပမာမှာ၊ ၎င်းတို့၏ လုပ်ရပ်များသည် မုန်တိုင်းထန်သော နေ့တွင် လေသည် ၎င်းအပေါ် ပြင်းထန်စွာ တိုက်ခတ်သော ပြာများကဲ့သို့ဖြစ်သည်။ ၎င်းတို့သည် မိမိတို့ ရရှိထားသော အရာများမှ မည်သည့်အရာကိုမျှ ရရှိနိုင်မည်မဟုတ်ပေ။ 14:18
- အလ္လာဟ်အရှင်မြတ်သည် ယုံကြည်သူများကို ဤလောကဘဝတွင် (ဆိုလိုသည်မှာ ၎င်းတို့သည် အလ္လာဟ်အရှင်မြတ်ကိုသာ ဆက်လက်ကိုးကွယ်ကြလိမ့်မည်) နှင့် နောင်ဘဝတွင် ခိုင်ခံ့သော စကားဖြင့် တည်မြဲစေတော်မူမည်။ 14:27
- မတရားကျူးလွန်သူများ (မွတ်ရှ်ရစ်ကန်များ၊ ညှဉ်းပန်းနှိပ်စက်သူများ စသည်) ပြုလုပ်သော အရာများကို အလ္လာဟ်အရှင်မြတ် သတိမပြုမိဟု မထင်ပါနှင့်။ သို့သော် အရှင်သည် ၎င်းတို့အား မျက်လုံးများ ထိတ်လန့်တုန်လှုပ်ဖွင့်မောနေသော ထိုနေ့တိုင်အောင် ၎င်းတို့ကို ဆိုင်းငံ့ထားတော်မူသည်။ 14:42
- အလ္လာဟ်အရှင်မြတ်သည် လူတိုင်းအား မိမိရရှိခဲ့သော အကျိုးအတိုင်း အပြည့်အစုံ ဆပ်တော်မူရန်ဖြစ်သည်။ အမှန်မှာ အလ္လာဟ်အရှင်မြတ်သည် စာရင်းရှင်းလင်းရာတွင် အလွန်လျင်မြန်တော်မူသော အရှင်ဖြစ်သည်။ 14:51
- ထို့ပြင် အမှန်မှာ ကျွန်ုပ်တို့သည် လူသားကို အသံမြည်သော ရွှံ့စေး၊ အနက်ရောင် ပြောင်းလဲထားသော ရွှံ့မှ ဖန်တီးတော်မူခဲ့သည်။ 15:26
- ထို့ပြင် ဂျင်န်များကို ကျွန်ုပ်တို့သည် ယင်းမတိုင်မီက မီးတောက်မှ ဖန်တီးတော်မူခဲ့သည်။ 15:27
- ၎င်း (ငရဲ) တွင် တံခါးခုနစ်ပေါက်ရှိသည်။ ထိုတံခါးပေါက်တစ်ခုစီအတွက် (သီးခြား) အပြစ်သားအုပ်စုကို သတ်မှတ်ထားသည်။ 15:44
- အရှင်သည် လူသားကို သုက်ရည်မှ (အမျိုးသားနှင့် အမျိုးသမီး လိင်ထွက်ပစ္စည်းများ ရောစပ်ထားသော အရာ) ဖန်တီးတော်မူခဲ့ပြီး၊ ထို့နောက် ဤ (လူသား) သည် ထင်ရှားသော ဆန့်ကျင်ဘက်ဖြစ်သူ ဖြစ်လာသည်။ 16:4
- ထို့ပြင် မွေးမြူရေးတိရစ္ဆာန်များကို အရှင်သည် သင်တို့အတွက် ဖန်တီးတော်မူခဲ့သည်။ ၎င်းတို့တွင် သင်တို့အတွက် နွေးထွေးမှု (နွေးထွေးသော အဝတ်အစား) နှင့် အကျိုးကျေးဇူးများစွာရှိပြီး၊ ၎င်းတို့မှ သင်တို့ စားသုံးကြသည်။ 16:5
- ထို့ပြင် (အရှင်သည် ဖန်တီးတော်မူခဲ့သည်) မြင်းများ၊ လားများနှင့် မြည်းများကို သင်တို့ စီးနင်းရန်နှင့် အဆင်တန်ဆာအဖြစ်။ ထို့ပြင် အရှင်သည် သင်တို့ မသိသော အခြားအရာများကိုလည်း ဖန်တီးတော်မူသည်။ 16:8
- အရှင်သည် မိုးကောင်းကင်မှ ရေ (မိုးရွာခြင်း) ကို သွန်းချပေးတော်မူသောအရှင်ဖြစ်သည်။ ၎င်းမှ သင်တို့ သောက်သုံးကြပြီး၊ ၎င်းမှ သင်တို့သည် မိမိတို့၏ မွေးမြူရေးတိရစ္ဆာန်များကို ကျွေးမွေးရာ အပင်များ ပေါက်ရောက်သည်။ 16:10
- အရှင်သည် ပင်လယ်ကို သင်တို့အလိုသို့ လိုက်စေတော်မူသောအရှင်ဖြစ်သည်။ သင်တို့သည် ၎င်းမှ လတ်ဆတ်သော အသား (ငါး) ကို စားသုံးနိုင်ရန်နှင့် ၎င်းမှ သင်တို့ ဝတ်ဆင်နိုင်သော အဆင်တန်ဆာများကို ထုတ်ယူနိုင်ရန်တည်း။ 16:14
- အရှင်သည် ကမ္ဘာမြေပေါ်တွင် ခိုင်မြဲသော တောင်တန်းများကို စိုက်ထူတော်မူခဲ့သည်။ သို့မှသာ ၎င်းသည် သင်တို့နှင့်အတူ လှုပ်ယမ်းခြင်းမရှိစေရန်၊ ထို့ပြင် မြစ်များနှင့် လမ်းများ (ဖန်တီးတော်မူခဲ့သည်)။ သို့မှသာ သင်တို့ လမ်းညွှန်ခြင်းခံရရန်။ 16:15
- ဖန်တီးတော်မူသောအရှင်သည် မဖန်တီးနိုင်သော အရာနှင့် တူညီပါသလော။ သင်တို့သည် အဘယ်ကြောင့် သတိမရသနည်း။ 16:17
- အကယ်၍ သင်တို့သည် အလ္လာဟ်အရှင်မြတ်၏ ကျေးဇူးတော်များကို ရေတွက်ရန် ကြိုးစားပါက၊ ၎င်းတို့ကို ဘယ်သောအခါမျှ ရေတွက်နိုင်မည်မဟုတ်ပေ။ 16:18
- အလ္လာဟ်အရှင်မြတ်သည် သင်တို့ ဖုံးကွယ်ထားသောအရာနှင့် သင်တို့ ထုတ်ဖော်ပြသသောအရာကို သိရှိတော်မူသည်။ 16:19
- ၎င်းတို့ (မွတ်ရှ်ရစ်ကန်များ) သည် အလ္လာဟ်အရှင်မြတ်မှတစ်ပါး ဆုတောင်းပူဇော်သော အရာများသည် မည်သည့်အရာကိုမျှ မဖန်တီးခဲ့ကြဘဲ၊ ၎င်းတို့ကိုယ်တိုင်ပင် ဖန်တီးခြင်းခံရသည်။ 16:20
- (၎င်းတို့သည်) သေလွန်သောသူများ၊ အသက်မရှိသောသူများဖြစ်ကြပြီး၊ ၎င်းတို့သည် မည်သည့်အခါ ပြန်လည်ထမြောက်ခြင်းခံရမည်ကိုလည်း မသိကြပေ။ 16:21
- ကျွန်ုပ်တို့သည် တစ်စုံတစ်ရာကို လိုလားသောအခါ၊ ၎င်းအတွက် ကျွန်ုပ်တို့၏ စကားတော်သည် "ဖြစ်လော့" ဟု ဆိုရုံမျှသာဖြစ်ပြီး၊ ၎င်းသည် ဖြစ်သွားသည်။ 16:40
- မကောင်းသော ကြံစည်မှုများကို ပြုလုပ်သူများသည် အလ္လာဟ်အရှင်မြတ် သူတို့ကို မြေကြီးထဲသို့ နစ်မြုပ်စေတော်မူမည်မဟုတ်၊ သို့မဟုတ် ပြစ်ဒဏ်သည် ၎င်းတို့ သိမြင်နိုင်ခြင်းမရှိသော ဘက်မှ ရောက်ရှိလာမည်မဟုတ်ဟု စိတ်ချလုံခြုံနေကြပါသလော။ 16:45
- သင်တို့၌ ရှိသော ကောင်းချီးမင်္ဂလာများနှင့် ကောင်းသောအရာများအားလုံးသည် အလ္လာဟ်အရှင်မြတ်ထံမှဖြစ်သည်။ ထို့နောက် အန္တရာယ်တစ်စုံတစ်ရာ သင်တို့ကို ထိခိုက်သောအခါ၊ သင်တို့သည် အရှင်ထံသို့သာလျှင် အကူအညီတောင်းခံ အော်ဟစ်ကြသည်။ 16:53
- ထို့နောက် အရှင်သည် အန္တရာယ်ကို သင်တို့ထံမှ ဖယ်ရှားပေးတော်မူသောအခါ၊ သင်တို့အနက်မှ အချို့သောသူများသည် မိမိတို့၏ အရှင်သခင် (ရဗ်ဗ်) (အလ္လာဟ်အရှင်မြတ်) နှင့် တွဲဖက်ကိုးကွယ်ကြသည်။ 16:54
- မွေးမြူရေးတိရစ္ဆာန်များတွင် သင်တို့အတွက် သင်ခန်းစာရှိသည်။ ကျွန်ုပ်တို့သည် ၎င်းတို့၏ ဗိုက်အတွင်းမှ၊ မစင်နှင့် သွေးကြားမှ၊ သန့်ရှင်းသော နို့ကို သင်တို့အား တိုက်ကျွေးပါသည်။ ၎င်းသည် သောက်သုံးသူများအတွက် အရသာရှိသော အရာဖြစ်သည်။ 16:66
- ထို့ကြောင့် အလ္လာဟ်အရှင်မြတ်အတွက် ပုံခိုင်းမှုများ ပြုလုပ်ခြင်းမပြုပါနှင့် (အကြောင်းမှာ အရှင်နှင့် တူညီသောအရာမရှိသလို၊ အရှင်သည်လည်း မည်သည့်အရာနှင့်မျှ မတူပါ)။ အမှန်မှာ အလ္လာဟ်အရှင်မြတ်သည် သိရှိတော်မူသည်။ သို့သော် သင်တို့မှာ မသိရှိကြပေ။ 16:74
- အလ္လာဟ်အရှင်မြတ်သည် လူသားများအား ကြားနိုင်မှု၊ မြင်နိုင်မှု၊ ဉာဏ်ရည်နှင့် ခံစားချက်များကို ပေးအပ်တော်မူခဲ့ကြောင်း သိမှတ်ပါ။ သို့မှသာ ၎င်းတို့သည် ကျေးဇူးတင်တတ်ကြရန်။ 16:78
- လောဘနှင့် ဝန်ခံခြင်းကို ရှောင်ကြဉ်ပါ။ 16:97
- သင်တို့သည် ကုရ်အာန်ကျမ်းတော်မြတ်ကို ရွတ်ဖတ်လိုသောအခါ၊ နှင်ထုတ်ခြင်းခံရသော (ကျိန်ဆဲခြင်းခံရသော) ရှိုင်သွန် (စာတန်) မှ အလ္လာဟ်အရှင်မြတ်ထံတွင် ခိုလှုံပါ။ 16:98
- အသိပညာမရှိဘဲ ပြုလုပ်မိသော မကောင်းမှုသည် ထိုသူ နောင်တရကာ မိမိကိုယ်ကို ပြုပြင်ပါက ခွင့်လွှတ်ခြင်းခံရကြောင်း သိမှတ်ပါ။ 16:119
- (အို မုဟမ္မဒ် ﷺ) သင်တို့၏ အရှင်သခင် (ရဗ်ဗ်) ၏ လမ်းတော် (အစ္စလာမ်) သို့ ဉာဏ်ပညာနှင့် ကောင်းသော ဆုံးမဩဝါဒဖြင့် ဖိတ်ခေါ်ပါ။ ထို့ပြင် ၎င်းတို့နှင့် အကောင်းဆုံးသော နည်းလမ်းဖြင့် ဆွေးနွေးပါ။ အခြားသူများကို အလ္လာဟ်အရှင်မြတ်၏ လမ်းတော်သို့ ဖိတ်ခေါ်ခြင်းသည် ဉာဏ်ပညာနှင့် ကြင်နာမှုဖြင့် ပြုလုပ်သင့်သည်။ 16:125
- အလ္လာဟ်အရှင်မြတ်သည် အရှင်အား ကြောက်ရွံ့သော သူများ (အရှင်အပေါ် သစ္စာစောင့်သိသော သူများ) နှင့် ကောင်းမှုကုသိုလ်ပြုသူများ (မုဟ်ဆင်န်) တို့နှင့်အတူရှိတော်မူသည်။ 16:128
- ဤကုရ်အာန်ကျမ်းတော်မြတ်သည် အလွန်ဖြောင့်မတ်ပြီး အကောင်းဆုံးသော အရာဆီသို့ လမ်းညွှန်တော်မူသည်။ 17:9
- မည်သူတစ်ဦးတစ်ယောက်မျှ အခြားသူတစ်ဦး၏ အပြစ်များကို ထမ်းဆောင်ရမည်မဟုတ်ပေ။ 17:15
- မည်သူမဆို နောင်ဘဝ (အာခိရသ်) ကို လိုလားပြီး ၎င်းအတွက် သင့်လျော်သော ကြိုးစားအားထုတ်မှုကို ပြုလုပ်ပါက၊ ထိုသူသည် ယုံကြည်သူတစ်ဦးဖြစ်နေစဉ်၊ ထိုသို့သော သူများ၏ ကြိုးစားအားထုတ်မှုကို အသိအမှတ်ပြုခြင်း၊ ကျေးဇူးတင်ခြင်းနှင့် ဆုလာဘ်ပေးအပ်ခြင်းခံရမည် (အလ္လာဟ်အရှင်မြတ်ထံတော်မှ)။ 17:19
- မိဘများကို ဂုဏ်ပြုပြီး ကရုဏာထားပါ။ မိဘများကို သစ္စာစောင့်သိပါ။ မိဘများအား မရိုမသေစကားတစ်ခွက်မျှ မပြောပါနှင့်။ သင်တို့၏ အရှင်သခင် (ရဗ်ဗ်) သည် သင်တို့အား အရှင်မှတစ်ပါး မည်သူ့ကိုမျှ မကိုးကွယ်ရန် အမိန့်ပေးတော်မူခဲ့သည်။ ထို့ပြင် မိဘများကို ကောင်းမှုပြုရန်။ အကယ်၍ ၎င်းတို့အနက်မှ တစ်ဦးဦး သို့မဟုတ် နှစ်ဦးစလုံးသည် သင်တို့၏ ဘဝတွင် အိုမင်းမှုသို့ ရောက်ရှိပါက၊ ၎င်းတို့အား "ဖျင်" ဟူသော စကားကိုမျှ မပြောပါနှင့်၊ ထို့ပြင် ၎င်းတို့ကို အော်ဟစ်ငေါက်ငမ်းခြင်းမပြုပါနှင့်။ သို့သော် ၎င်းတို့အား ရိုသေမှုရှိသော စကားဖြင့် ပြောဆိုပါ။ 17:23
- ထို့ပြင် ကရုဏာတရားဖြင့် နှိမ့်ချမှု၏ အတောင်ကို ၎င်းတို့အတွက် နှိမ့်ချထားပြီး၊ "အို ကျွန်ုပ်၏ အရှင်သခင် (ရဗ်ဗ်)။ ကျွန်ုပ် ငယ်စဉ်အခါက ၎င်းတို့ ကျွန်ုပ်ကို ပြုစုပျိုးထောင်ခဲ့သကဲ့သို့၊ အရှင်သည် ၎င်းတို့အား ကရုဏာတော်ဖြင့် သနားတော်မူပါ။" ဟု ဆုတောင်းပါ။ 17:24
- အမှန်မှာ အလွန်အကျွံသုံးစွဲသူများသည် ရှိုင်သွန် (စာတန်) ၏ ညီအစ်ကိုများဖြစ်ကြပြီး၊ ရှိုင်သွန် (စာတန်) သည် မိမိ၏ အရှင်သခင် (ရဗ်ဗ်) အား အမြဲ ကျေးဇူးကန်းသော သူဖြစ်သည်။ 17:27
- ငွေကြေးကို အလွန်အကျွံမသုံးစွဲပါနှင့်။ 17:29
- ဆင်းရဲမွဲတေမှုကိုစိုး၍ သင်တို့၏ သားသမီးများကို မသတ်ပါနှင့်။ 17:31
- အိမ်ထောင်ရေးဖောက်ပြန်ခြင်းကို မကျူးလွန်ပါနှင့်။ အိမ်ထောင်ရေး၏ မြင့်မြတ်မှုကို ထိန်းသိမ်းပြီး အိမ်ထောင်ရေးဖောက်ပြန်ခြင်းကို ရှောင်ကြဉ်ပါ။ 17:32
- သင်တို့ တိုင်းတာသောအခါ ပြည့်ပြည့်စုံစုံ တိုင်းတာပြီး ဖြောင့်မတ်သော ချိန်ခွင်ဖြင့် ချိန်ဆပါ။ ဤအရာသည် ကောင်းမွန်သည် (အကျိုးရှိသည်) နှင့် နောက်ဆုံးရလဒ်တွင် ပိုမိုကောင်းမွန်သည်။ 17:35
- (အို လူသား) သင်တို့တွင် အသိပညာမရှိသော အရာကို မလိုက်နာပါနှင့် (ဥပမာ — "ကျွန်ုပ် မြင်ခဲ့သည်" ဟု ဆိုခြင်း၊ သို့သော် သူမမြင်ခဲ့ဘဲ၊ သို့မဟုတ် "ကျွန်ုပ် ကြားခဲ့သည်" ဟု ဆိုခြင်း၊ သို့သော် သူမကြားခဲ့ဘဲ)။ 17:36
- နှိမ့်ချပြီး မာနကြီးခြင်းမပြုပါနှင့်။ ကမ္ဘာမြေပေါ်တွင် မာနကြီးစွာဖြင့် မလျှောက်ပါနှင့်။ အမှန်မှာ သင်တို့သည် ကမ္ဘာမြေကို ဖောက်ခွဲနိုင်မည်မဟုတ်သလို၊ တောင်တန်းများ၏ အမြင့်ကိုလည်း မရောက်ရှိနိုင်ပေ။ 17:37
- သင်တို့၏ အရှင်သခင် (ရဗ်ဗ်) သည် သင်တို့ကို အကောင်းဆုံး သိရှိတော်မူသည်။ အကယ်၍ အရှင်အလိုရှိတော်မူပါက၊ သင်တို့အား ကရုဏာတော်ထားတော်မူမည်။ သို့မဟုတ် အကယ်၍ အရှင်အလိုရှိတော်မူပါက၊ သင်တို့ကို ပြစ်ဒဏ်ပေးတော်မူမည်။ 17:54
- ဤလောကဘဝတွင် မျက်စိမမြင်သူ (ဆိုလိုသည်မှာ အလ္လာဟ်အရှင်မြတ်၏ သက်သေလက္ခဏာတော်များကို မမြင်ရဘဲ အရှင်ကို မယုံကြည်သူ) သည် နောင်ဘဝ (အာခိရသ်) ၌လည်း မျက်စိမမြင်သူဖြစ်ပြီး လမ်းမှ ပိုမိုလွဲမှားသော သူဖြစ်သည်။ 17:72
- သတ်မှတ်ထားသော ဆုတောင်းချိန်များကို စောင့်ထိန်းပါ။ 17:78
- အမှန်မှာ ကျွန်ုပ်တို့သည် ဤကုရ်အာန်ကျမ်းတော်မြတ်တွင် လူသားများအတွက် ပုံသက်သေမျိုးစုံကို အသေးစိတ် ရှင်းပြထားပြီးဖြစ်သည်။ သို့သော် လူအများစုသည် (အမှန်တရားကို) ငြင်းပယ်ခြင်းမှတစ်ပါး အခြားမည်သည့်အရာကိုမျှ လက်မခံကြပေ။ 17:89
- ကျွန်ုပ်တို့သည် ဤကုရ်အာန်ကျမ်းတော်မြတ်တွင် လူသားများအတွက် ပုံသက်သေမျိုးစုံကို ဖော်ပြထားပြီးဖြစ်သည်။ သို့သော် လူသားသည် အရာခပ်သိမ်းထက် ငြင်းခုံတတ်သော သတ္တဝါဖြစ်သည်။ 18:54
- ၎င်းတို့၏ ပြစ်ဒဏ်မှာ ငရဲဂျဟန္နမ်ဖြစ်သည်။ အကြောင်းမှာ ၎င်းတို့သည် မယုံကြည်ခဲ့ကြပြီး ကျွန်ုပ်၏ အာယသ်တော်များနှင့် ကျွန်ုပ်၏ ရစူလ်တမန်တော်များကို လှောင်ပြောင်ခြင်းနှင့် သရော်ခြင်းအဖြစ် သတ်မှတ်ခဲ့ကြသောကြောင့်ဖြစ်သည်။ 18:106
- အလ္လာဟ်အရှင်မြတ် (၏ မြင့်မြတ်တော်မူခြင်း) နှင့် မသင့်လျော်ပါ။ အရှင်သည် သားတော်တစ်ပါးရှိရန် (ဤအချက်သည် ခရစ်ယာန်များ အလ္လာဟ်အရှင်မြတ်အပေါ် စွပ်စွဲသော �лепетမှု ဖြစ်သည့် အီစာ (ယေရှု) သည် အလ္လာဟ်အရှင်မြတ်၏ သားတော်ဖြစ်သည်ဟု ဆိုခြင်းကို ရည်ညွှန်းသည်)။ အရှင်သည် (၎င်းတို့ တွဲဖက်ကိုးကွယ်သော အရာအားလုံးထက်) မြင့်မြတ်တော်မူသည်။ 19:35
- လူများကို နူးညံ့သိမ်မွေ့စွာ ပြောဆိုပါ။ 20:44
- ကောင်းမှုကုသိုလ်များတွင် အချင်းချင်း ယှဉ်ပြိုင်ပါ။ 21:90
- အချည်းနှီးသော စကားများကို ရှောင်ကြဉ်ပါ။ 23:3
- မိမိတို့၏ ယဉ်ကျေးလိမ္မာမှု (အဝတ်အစား ဆင်ယင်မှု) ကို စောင့်ထိန်းပါ။ 23:5
- မိမိတို့၏ နှလုံးသားကို အပြစ်ဆီသို့ စေ့ဆော်မှုများမှ ကာကွယ်ပါ။ 23:97
- အခြားသူများကို ခွင့်လွှတ်ပြီး ၎င်းတို့၏ အမှားများကို သည်းခံပါ။ 24:22
- အခြားသူများ၏ ကိုယ်ရေးကိုယ်တာ လွတ်လပ်ခွင့်ကို ရိုသေပါ၊ အထူးသဖြင့် ၎င်းတို့၏ အိမ်များတွင်။ အိမ်နီးချင်းများ၏ အခွင့်အရေးများကို ကျေပွန်အောင်ဆောင်ရွက်ပါ။ 24:27
- (အမျိုးသားရော အမျိုးသမီးပါ) မျက်နှာကို နှိမ့်ချထားပါ။ မိမိတို့၏ ယဉ်ကျေးလိမ္မာမှုနှင့် အပျိုစင်ဘဝကို စောင့်ထိန်းပါ။ 24:30
- အဝတ်အစားနှင့် အပြုအမူတွင် ယဉ်ကျေးလိမ္မာမှုကို စောင့်ထိန်းပါ။ 24:31
- အလ္လာဟ်အရှင်မြတ်သည် အရှင်ကို ကိုးကွယ်ပြီး ကောင်းမှုကုသိုလ်များကို ပြုသူများအား လုံခြုံမှုနှင့် ငြိမ်းချမ်းမှုကို ပေးအပ်တော်မူကြောင်း သိမှတ်ပါ။ 24:55
- ခွင့်ပြုချက်မရှိဘဲ မိဘများ၏ ကိုယ်ရေးအိမ်သို့ မဝင်ပါနှင့်။ 24:58
- နှိမ့်ချပြီး ကျိုးနွံပါ။ 25:63
- မှားယွင်းသော သက်သေခံခြင်းနှင့် လှည့်စားခြင်းကို ရှောင်ကြဉ်ပါ။ 25:72
- နောင်ဘဝ (အာခိရသ်) ၏ ဆုလာဘ်အတွက် ကြိုးစားပါ၊ သို့သော် ဤလောကဘဝ၏ ကိစ္စများကို လျစ်လျူမရှုပါနှင့်။ 28:77
- အလ္လာဟ်အရှင်မြတ်မှတစ်ပါး အခြားသော နတ်ဘုရားတစ်ပါးကို ဆုတောင်းပူဇော်ခြင်းမပြုပါနှင့်။ 28:88
- လိင်တူဆက်ဆံခြင်းတွင် မပါဝင်ပါနှင့်။ 29:29
- မိမိတို့၏ ကြိုးပမ်းအားထုတ်မှုအားလုံးတွင် ထူးချွန်မှုအတွက် ကြိုးစားပါ။ 29:69
- ဆွလာသ်ဝတ်ပြုဆုတောင်းခြင်းကို ဆောက်တည်ပြီး ဇကာသ်ကို ပေးအပ်ပါ။ 31:4
- ကောင်းမှုကုသိုလ်ကို ညွှန်ကြားပြီး မကောင်းမှုကို တားမြစ်ပါ။ 31:17
- မိမိတို့၏ အပြုအမူတွင် မာနကြီးခြင်းကို ရှောင်ကြဉ်ပါ။ အချည်းနှီးသော စကားများဖြင့် အချိန်မဖြုန်းပါနှင့်။ 31:18
- မိမိတို့၏ လမ်းလျှောက်ပုံနှင့် စကားသံ၏ ကျယ်လောင်မှုတွင် မျှတပါ။ 31:19
- နဗီတမန်တော် မုဟမ္မဒ် ၏ စံနမူနာကို လိုက်နာပါ။ 33:21
- အမျိုးသမီးများသည် မိမိတို့၏ အလှအပနှင့် အဆင်တန်ဆာများကို ပြသခြင်း သို့မဟုတ် ကြွားဝါခြင်းမပြုသင့်ပါ။ 33:33
- အခြေအနေအားလုံးတွင် အမှန်တရားကို ပြောဆိုပါ။ 33:70
- ဆင်ခြင်သုံးသပ်ခြင်းဖြင့် ဉာဏ်ပညာနှင့် နားလည်မှုကို ရှာဖွေပါ။ 38:29
- ကုရ်အာန်ကျမ်းတော်မြတ်၏ အမိန့်တော်များကို လိုက်နာပါ။ 39:23
- အပြစ်သားတစ်ဦးသည် နောင်တရကာ အရှင်ထံသို့ ပြန်လာသောအခါ အလ္လာဟ်အရှင်မြတ်သည် အပြစ်အားလုံးကို ခွင့်လွှတ်တော်မူသည်။ 39:53
- အလ္လာဟ်အရှင်မြတ်ထံသို့ ရိုးသားသော ဒူအာ (ဆုတောင်း) ကို ပြုလုပ်ပါ။ 40:60
- မကောင်းမှုကို ပိုမိုကောင်းမွန်သော အရာဖြင့် တွန်းလှန်ပါ။ 41:34
- ကိစ္စများကို ညှိနှိုင်းဆွေးနွေးခြင်းဖြင့် ဆုံးဖြတ်ပါ။ 42:38
- သင်တို့၏ အသံကို နဗီတမန်တော်၏ အသံထက် မမြှင့်ပါနှင့်။ 49:2
- လျှို့ဝှက်ချက်များကို စောင့်ထိန်းပြီး သစ္စာဖောက်ခြင်းကို ရှောင်ကြဉ်ပါ။ 49:6
- ပဋိပက္ခဖြစ်နေသူများကြားတွင် ငြိမ်းချမ်းရေးကို လွယ်ကူချောမွေ့စေပါ။ ပဋိပက္ခများတွင် ပြန်လည်သင့်မြတ်ရေးကို ရှာဖွေပါ။ 49:9
- အခြားသူများကို မလှောင်ပြောင်ပါနှင့်။ 49:11
- သံသယစိတ်ကို ရှောင်ကြဉ်ပါ။ သူလျှိုလုပ်ခြင်းနှင့် ကုလားထိုင် (အနာပြော) ခြင်းကို ရှောင်ကြဉ်ပါ။ အခြားသူများကို အသရေမဖျက်ပါနှင့် သို့မဟုတ် ကлеветаမပြုပါနှင့်။ ကုလားထိုင်ခြင်းနှင့် ကлеветаခြင်း ပုံစံအားလုံးမှ ရှောင်ကြဉ်ပါ။ မာနကြီးခြင်းသည် သင်တို့ကို မတရားမှုဆီသို့ မပို့ဆောင်ပါစေနှင့်။ 49:12
- ဖြောင့်မတ်ခြင်းသာလျှင် လူတစ်ဦးကို မြင့်မြတ်စေကြောင်း သိမှတ်ပါ။ လူသားများနှင့် ယဉ်ကျေးမှုများကြားရှိ ကွဲပြားမှုများကို ရိုသေပါ။ 49:13
- ဧည့်သည်များကို ဂုဏ်ပြုပါ။ 51:26
- အလ္လာဟ်အရှင်မြတ်အပေါ် မိမိတို့၏ တာဝန်ဝတ္တရားများကို သတိရှိပါ။ 51:56
- ဥစ္စာပစ္စည်းကို ကုသိုလ်ဖြစ်စေရန် သုံးစွဲပါ။ 57:7
- ဘာသာတရားတွင် ရဟန်းပြုခြင်း (အိမ်ထောင်ပြုခြင်းနှင့် သက်တောင့်သက်သာများကို စွန့်လွှတ်ခြင်း၊ ရဟန်းများ၊ သီလရှင်များ သို့မဟုတ် ဘာသာရေးဆိုင်ရာ ကတိသစ္စာများဖြင့် နေထိုင်သူများ သို့မဟုတ် ၎င်းတို့ နေထိုင်ရာ အဆောက်အအုံများကဲ့သို့) မရှိကြောင်း သိမှတ်ပါ။ 57:27
- ဥစ္စာပစ္စည်းက သင်တို့ကို အလ္လာဟ်အရှင်မြတ် အောက်မေ့သတိရခြင်းမှ မလွဲစေပါနှင့်။ 58:11
- အသိပညာရှိသူများအား အလ္လာဟ်အရှင်မြတ်က မြင့်မားသော ရာထူးအဆင့်အတန်းကို ပေးအပ်တော်မူမည်။ 58:11
- မွတ်စ်လင်မ်မဟုတ်သူများကို ကြင်နာစွာနှင့် တရားမျှတစွာ ဆက်ဆံပါ။ 60:8
- မိမိတို့၏ ယုံကြည်ချက်များနှင့် လုပ်ရပ်များတွင် လျှို့ဝှက်သွေဖည်ခြင်း (မုနာဖီကန်) ကို ရှောင်ကြဉ်ပါ။ 63:9
- လောဘနှင့် ဝန်ခံခြင်းမှ ဝေးဝေးနေပါ။ 64:16
- သင်တို့အား အပ်နှင်းထားသော ဗျာဒိတ်တော်များကို စောင့်ထိန်းပါ။ 73:15
- တရားစီရင်ရာနေ့ (ခိယာမသ်) ကို သတိရပါ။ 75:36
- စိတ်ရှည်သည်းခံမှုနှင့် ကရုဏာတရားကို ညွှန်ကြားပါ။ 90:17
- မိမိတို့၏ စိတ်ဝိညာဉ်ကို သန့်စင်စေသူများသည် အောင်မြင်ကြသည်။ ထို့ပြင် ၎င်းကို ညစ်ညမ်းစေသူများသည် ရှုံးနိမ့်ကြသည်။ 91:10
- ဆင်းရဲနွမ်းပါးသူများကို ဂရုမစိုက်ခြင်း သို့မဟုတ် တွန်းထုတ်ခြင်းမပြုပါနှင့်။ 93:10
- အသိပညာနှင့် နားလည်မှုကို ရှာဖွေပါ။ ကုရ်အာန်ကျမ်းတော်မြတ်ကို ဖတ်ရှုပြီး ၎င်းအပေါ် ဆင်ခြင်သုံးသပ်ပါ။ 96:1–5
- ဆင်းရဲနွမ်းပါးသူများကို အစာကျွေးရန် အားပေးပါ။ 107:3
""";
